            {
                dtbCopy = Table.Copy();
                dtbCopy.DefaultView.RowFilter = "(" + condition + ")" + " or QuizID is null";
            }
            else
                dtbCopy = Table;
            lookup.InitData(dtbCopy, "--Chọn--", "QuizID", "Title", "", "Mã", "Title", "Tên");
