ALTER PROCEDURE dbo.LMS_Enrollment_Cancel
    @Id Bigint,
    @ActorId Bigint,
    @UpdatedUser NVARCHAR(100) = NULL
As
Begin
    Set Nocount On;

    Update dbo.LMS_Enrollments
    Set Status = 'CANCELLED',
        LastAccessAt = Sysutcdatetime(),
        UpdatedUser = @UpdatedUser
    Where (EnrollmentID = @Id)
        And (Status <> 'CANCELLED');

    Declare @Rows Int = @@Rowcount;

    If @Rows > 0
        Insert dbo.AuditLogs
        (
            UserId,
            Action,
            Module,
            EntityName,
            EntityId
        )
        Values
        (
            @ActorId,
            'CANCEL',
            'ENROLLMENT',
            'Enrollment',
            Convert(Nvarchar(100), @Id)
        );

    Select
        @Rows;
End

ALTER PROCEDURE dbo.LMS_Question_Create
    @Id Bigint = Null,
    @QuestionType Varchar(50),
    @QuestionText Nvarchar(Max),
    @Description Nvarchar(Max) = Null,
    @Explanation Nvarchar(Max) = Null,
    @Difficulty Varchar(30),
    @DefaultScore Decimal(8, 2),
    @ShortAnswerMode Varchar(30) = Null,
    @Status Varchar(30),
    @ActorId Bigint,
    @CreatedUser NVARCHAR(100) = NULL
As
Begin
    Set Nocount On;

    If @QuestionType Not In ('SINGLE_CHOICE', 'MULTIPLE_CHOICE', 'TRUE_FALSE', 'SHORT_ANSWER', 'CLOZE_DRAG_DROP')
        Or Nullif(Ltrim(Rtrim(@QuestionText)), '') Is Null
        Or @DefaultScore < 0
        Throw 50001, N'Dữ liệu câu hỏi không hợp lệ.', 1;

    Insert dbo.LMS_Questions
    (
        QuestionType,
        QuestionText,
        Description,
        Explanation,
        Difficulty,
        DefaultScore,
        ShortAnswerMode,
        CreatedByUserID,
        CreatedUser,
        UpdatedUser,
        Status
    )
    Values
    (
        @QuestionType,
        @QuestionText,
        @Description,
        @Explanation,
        @Difficulty,
        @DefaultScore,
        @ShortAnswerMode,
        @ActorId,
        @CreatedUser,
        @CreatedUser,
        @Status
    );

    Declare @QuestionId Bigint = Scope_identity();

    Insert dbo.AuditLogs
    (
        UserId,
        Action,
        Module,
        EntityName,
        EntityId
    )
    Values
    (
        @ActorId,
        'CREATE',
        'QUESTION',
        'Question',
        Convert(Nvarchar(100), @QuestionId)
    );

    Select
        @QuestionId;
End

ALTER PROCEDURE dbo.LMS_Question_Update
    @Id Bigint,
    @QuestionType Varchar(50),
    @QuestionText Nvarchar(Max),
    @Description Nvarchar(Max) = Null,
    @Explanation Nvarchar(Max) = Null,
    @Difficulty Varchar(30),
    @DefaultScore Decimal(8, 2),
    @ShortAnswerMode Varchar(30) = Null,
    @Status Varchar(30),
    @ActorId Bigint,
    @IsAdmin Bit = 0,
    @UpdatedUser NVARCHAR(100) = NULL
As
Begin
    Set Nocount On;

    If @QuestionType Not In ('SINGLE_CHOICE', 'MULTIPLE_CHOICE', 'TRUE_FALSE', 'SHORT_ANSWER', 'CLOZE_DRAG_DROP')
        Or Nullif(Ltrim(Rtrim(@QuestionText)), '') Is Null
        Or @DefaultScore < 0
        Throw 50001, N'Dữ liệu câu hỏi không hợp lệ.', 1;

    Update dbo.LMS_Questions
    Set QuestionType = @QuestionType,
        QuestionText = @QuestionText,
        Description = @Description,
        Explanation = @Explanation,
        Difficulty = @Difficulty,
        DefaultScore = @DefaultScore,
        ShortAnswerMode = @ShortAnswerMode,
        Status = @Status,
        UpdatedAt = Sysutcdatetime(),
        UpdatedUser = @UpdatedUser
    Where (QuestionID = @Id)
        And (IsDeleted = 0)
        And (@IsAdmin = 1 Or CreatedByUserID = @ActorId);

    If @@Rowcount = 0
        Throw 50003, N'Không tìm thấy câu hỏi hoặc bạn không có quyền sửa.', 1;

    Insert dbo.AuditLogs
    (
        UserId,
        Action,
        Module,
        EntityName,
        EntityId
    )
    Values
    (
        @ActorId,
        'UPDATE',
        'QUESTION',
        'Question',
        Convert(Nvarchar(100), @Id)
    );

    Select
        @Id;
End

ALTER PROCEDURE dbo.LMS_Question_Delete
    @Id Bigint,
    @ActorId Bigint,
    @IsAdmin Bit = 0,
    @UpdatedUser NVARCHAR(100) = NULL
As
Begin
    Set Nocount On;

    Update dbo.LMS_Questions
    Set IsDeleted = 1,
        UpdatedAt = Sysutcdatetime(),
        UpdatedUser = @UpdatedUser
    Where (QuestionID = @Id)
        And (IsDeleted = 0)
        And (@IsAdmin = 1 Or CreatedByUserID = @ActorId);

    Declare @Rows Int = @@Rowcount;

    If @Rows = 0
        Throw 50003, N'Không tìm thấy câu hỏi hoặc bạn không có quyền xóa.', 1;

    If @Rows > 0
    Begin
        Update dbo.LMS_VideoInteractions
        Set IsDeleted = 1,
            UpdatedAt = Sysutcdatetime()
        Where (QuestionId = @Id)
            And (IsDeleted = 0);

        Insert dbo.AuditLogs
        (
            UserId,
            Action,
            Module,
            EntityName,
            EntityId
        )
        Values
        (
            @ActorId,
            'DELETE',
            'QUESTION',
            'Question',
            Convert(Nvarchar(100), @Id)
        );
    End

    Select
        @Rows;
End

ALTER PROCEDURE dbo.LMS_QuestionOption_Create
    @QuestionId Bigint,
    @OptionCode Nvarchar(20),
    @OptionText Nvarchar(2000),
    @IsCorrect Bit,
    @SortOrder Int
As
Begin
    Set Nocount On;

    If Nullif(Ltrim(Rtrim(@OptionCode)), '') Is Null
        Or Nullif(Ltrim(Rtrim(@OptionText)), '') Is Null
        Throw 50001, N'Phương án trả lời không hợp lệ.', 1;

    Set @OptionCode = Upper(Ltrim(Rtrim(@OptionCode)));

    If Exists
    (
        Select
            1
        From dbo.LMS_QuestionOptions
        Where (QuestionID = @QuestionId)
            And (OptionCode = @OptionCode)
    )
        Update dbo.LMS_QuestionOptions
        Set OptionText = @OptionText,
            IsCorrect = @IsCorrect,
            SortOrder = @SortOrder,
            IsDeleted = 0
        Where (QuestionID = @QuestionId)
            And (OptionCode = @OptionCode);
    Else
        Insert dbo.LMS_QuestionOptions
        (
            QuestionID,
            OptionCode,
            OptionText,
            IsCorrect,
            SortOrder,
            IsDeleted
        )
        Values
        (
            @QuestionId,
            @OptionCode,
            @OptionText,
            @IsCorrect,
            @SortOrder,
            0
        );
End

