ALTER PROCEDURE dbo.LMS_Lesson_Create
    @ChapterId Bigint,
    @Title Nvarchar(500),
    @Description Nvarchar(1000) = Null,
    @LessonType Varchar(50),
    @DurationSeconds Int,
    @SortOrder Int,
    @IsRequired Bit,
    @PassingScore Decimal(5, 2) = Null,
    @ContentHtml Nvarchar(Max) = Null,
    @DocumentUrl Nvarchar(1000) = Null,
    @AssignmentFolderName Nvarchar(250) = Null,
    @AssignmentStartAt Datetime2 = Null,
    @DueAt Datetime2 = Null,
    @AssignmentMaxScore Decimal(8, 2) = 100,
    @MaxSubmissionAttempts Int = 3,
    @MaxSubmissionFileSizeMB Int = 50,
    @AllowLateSubmission Bit = 0,
    @Status Varchar(30),
    @ActorId Bigint,
    @IsAdmin Bit = 0
As
Begin
    Set Nocount On;

    Declare @CourseId Bigint = (
        Select
            dbo.SIM_Chapters.CourseID
        From dbo.SIM_Chapters
            Inner Join dbo.SIM_Courses On dbo.SIM_Courses.CourseID = dbo.SIM_Chapters.CourseID
        Where (dbo.SIM_Chapters.ChapterID = @ChapterId)
            And (dbo.SIM_Chapters.IsDeleted = 0)
            And (@IsAdmin = 1 Or dbo.SIM_Courses.TeacherUserID = @ActorId)
    );

    If @CourseId Is Null Throw 50003,
    N'Bạn không có quyền quản lý chương này.',
    1;

    If Nullif(Ltrim(Rtrim(@Title)), '') Is Null
    Or @LessonType Not In ('VIDEO', 'INTERACTIVE_VIDEO', 'QUIZ', 'DOCUMENT', 'EDITOR', 'ASSIGNMENT', 'INTERACTIVE_CONTENT')
    Or @DurationSeconds < 0
    Or @SortOrder < 1
    Or @AssignmentMaxScore Not Between 1 And 10000
    Or @MaxSubmissionAttempts Not Between 1 And 20
    Or @MaxSubmissionFileSizeMB Not Between 1 And 200
    Or @PassingScore Not Between 0 And 100  Throw 50001,
    N'Dữ liệu bài học không hợp lệ.',
    1;

    Insert dbo.SIM_Lessons (CourseID, ChapterID, Title, Description, LessonType, DurationSeconds, SortOrder, IsRequired, PassingScore, ContentHtml, DocumentUrl, AssignmentFolderName, AssignmentStartAt, DueAt, AssignmentMaxScore, MaxSubmissionAttempts, MaxSubmissionFileSizeMB, AllowLateSubmission, Status)
    Values
        (@CourseId, @ChapterId, @Title, @Description, @LessonType, @DurationSeconds, @SortOrder, @IsRequired, @PassingScore, @ContentHtml, @DocumentUrl, @AssignmentFolderName, @AssignmentStartAt, @DueAt, @AssignmentMaxScore, @MaxSubmissionAttempts, @MaxSubmissionFileSizeMB, @AllowLateSubmission, @Status);

    Declare @Id Bigint = Scope_identity();

    Insert dbo.SYS_AuditLogs (UserId, Action, Module, EntityName, EntityId)
    Values
        (@ActorId, 'CREATE', 'LESSON', 'Lesson', Convert(Nvarchar(100), @Id));

    Select
        @Id;

End

ALTER PROCEDURE dbo.LMS_Course_Update
    @Id Bigint,
    @Code Nvarchar(100),
    @Title Nvarchar(500),
    @Slug Nvarchar(500) = Null,
    @ThumbnailUrl Nvarchar(1000) = Null,
    @ShortDescription Nvarchar(1000) = Null,
    @Description Nvarchar(Max) = Null,
    @TeacherId Bigint,
    @CategoryId Bigint = Null,
    @ClassSubjectID Bigint = Null,
    @Level Varchar(50),
    @PassingScore Decimal(5, 2),
    @Status Varchar(30),
    @ActorId Bigint,
    @IsAdmin Bit = 0
As
Begin
    Set Nocount On;

    Set Xact_abort On;

    Set @Code = Ltrim(Rtrim(@Code));

    Set @Title = Ltrim(Rtrim(@Title));

    Set @Slug = Coalesce(Nullif(Ltrim(Rtrim(@Slug)), ''), Lower(Replace(@Code, ' ', '-')));

    If @Code = ''
    Or @Title = ''
    Or @PassingScore < 0
    Or @PassingScore > 100
    Or @Status Not In ('DRAFT', 'PUBLISHED', 'ARCHIVED') Throw 50001,
    N'Dữ liệu khóa học không hợp lệ.',
    1;

    If Not Exists (
        Select
            1
        From dbo.SYS_Users
        Where (UserID = @TeacherId)
            And (TeacherID Is Not Null)
            And (IsDeleted = 0)
    ) Throw 50002,
    N'Giảng viên không tồn tại.',
    1;

    If @CategoryId Is Not Null
    AND NOT EXISTS (
        Select
            1
        From dbo.SIM_CourseCategories
        Where (CourseCategoryID = @CategoryId)
            And (Status = 'ACTIVE')
    ) Throw 50002,
    N'Danh mục không tồn tại.',
    1;

    If @ClassSubjectID Is Not Null
    AND NOT EXISTS (
        Select
            1
        From dbo.SIM_Class_Subject
        Where (DataGroupID = 1)
            And (ClassSubjectID = @ClassSubjectID)
            And (ClassSubjectStatus = 1)
    ) Throw 50002,
    N'Môn học lớp không tồn tại.',
    1;

    If Exists (
        Select
            1
        From dbo.SIM_Courses
        Where (CourseID <> @Id)
            And (Code = @Code Or Slug = @Slug)
            And (IsDeleted = 0)
    ) Throw 50006,
    N'Mã hoặc slug khóa học đã tồn tại.',
    1;

    Declare @Old Nvarchar(Max) = (
        Select
            Code code,
            Title title,
            Status status
        From dbo.SIM_Courses
        Where (CourseID = @Id)
        For Json Path, Without_array_wrapper
    );

    Begin Transaction;

    Update dbo.SIM_Courses
    Set
        Code = @Code,
        Title = @Title,
        Slug = @Slug,
        ThumbnailUrl = @ThumbnailUrl,
        ShortDescription = @ShortDescription,
        Description = @Description,
        TeacherUserID = @TeacherId,
        CourseCategoryID = @CategoryId,
        DataGroupID = 1,
        ClassSubjectID = @ClassSubjectID,
        Level = @Level,
        PassingScore = @PassingScore,
        Status = @Status,
        PublishedAt = Iif(@Status = 'PUBLISHED', Coalesce(PublishedAt, Sysutcdatetime()), PublishedAt),
        UpdatedAt = Sysutcdatetime(),
        UpdatedByUserID = @ActorId
    Where (CourseID = @Id)
        And (IsDeleted = 0)
        And (@IsAdmin = 1 Or TeacherUserID = @ActorId);

    Declare @Rows Int = @@Rowcount;

    If @Rows > 0
    Insert dbo.SYS_AuditLogs (UserId, Action, Module, EntityName, EntityId, OldValuesJson, NewValuesJson, CreatedAt)
    Values
        (
            @ActorId,
            'UPDATE',
            'COURSE',
            'Course',
            Convert(Nvarchar(100), @Id),
            @Old,
            (
                Select
                    @Code code,
                    @Title title,
                    @Status status
                For Json Path, Without_array_wrapper
            ),
            Sysutcdatetime()
        );

    Commit Transaction;

    Select
        @Rows;

End

