ALTER PROCEDURE dbo.LMS_Course_Create
    @Code Nvarchar(100),
    @Title Nvarchar(500),
    @Slug Nvarchar(500) = Null,
    @ThumbnailUrl Nvarchar(1000) = Null,
    @ShortDescription Nvarchar(1000) = Null,
    @Description Nvarchar(Max) = Null,
    @TeacherId Bigint,
    @CategoryId Bigint = Null,
    @ClassSubjectID Bigint = Null,
    @Level Varchar(50),
    @PassingScore Decimal(5, 2),
    @Status Varchar(30),
    @ActorId Bigint
As
Begin
    Set Nocount On;

    Set Xact_abort On;

    Set @Code = Ltrim(Rtrim(@Code));

    Set @Title = Ltrim(Rtrim(@Title));

    Set @Slug = Coalesce(Nullif(Ltrim(Rtrim(@Slug)), ''), Lower(Replace(@Code, ' ', '-')));

    If @Code = ''
    Or @Title = ''
    Or @PassingScore < 0
    Or @PassingScore > 100
    Or @Status Not In ('DRAFT', 'PUBLISHED', 'ARCHIVED') Throw 50001,
    N'Dữ liệu khóa học không hợp lệ.',
    1;

    If Not Exists (
        Select
            1
        From dbo.SYS_Users
        Where (UserID = @TeacherId)
            And (TeacherID Is Not Null)
            And (IsDeleted = 0)
    ) Throw 50002,
    N'Giảng viên không tồn tại.',
    1;

    If @CategoryId Is Not Null
    AND NOT EXISTS (
        Select
            1
        From dbo.SIM_CourseCategories
        Where (CourseCategoryID = @CategoryId)
            And (Status = 'ACTIVE')
    ) Throw 50002,
    N'Danh mục không tồn tại.',
    1;

    If @ClassSubjectID Is Not Null
    AND NOT EXISTS (
        Select
            1
        From dbo.SIM_Class_Subject
        Where (DataGroupID = 1)
            And (ClassSubjectID = @ClassSubjectID)
            And (ClassSubjectStatus = 1)
    ) Throw 50002,
    N'Môn học lớp không tồn tại.',
    1;

    If Exists (
        Select
            1
        From dbo.SIM_Courses
        Where (
                Code = @Code
            Or (Slug = @Slug)
        )
            And (IsDeleted = 0)
    ) Throw 50006,
    N'Mã hoặc slug khóa học đã tồn tại.',
    1;

    Begin Transaction;

    Insert dbo.SIM_Courses
    (
        Code, 
        Title, 
        Slug, 
        ThumbnailUrl, 
        ShortDescription, 
        Description, 
        TeacherUserID, 
        CourseCategoryID, 
        DataGroupID, 
        ClassSubjectID, 
        Level, 
        PassingScore, 
        Status, 
        PublishedAt, 
        CreatedByUserID
    )
    Values
        (
            @Code, 
            @Title, 
            @Slug, 
            @ThumbnailUrl, 
            @ShortDescription, 
            @Description, 
            @TeacherId, 
            @CategoryId, 
            1, 
            @ClassSubjectID, 
            @Level, 
            @PassingScore, 
            @Status, 
            Iif(@Status = 'PUBLISHED', Sysutcdatetime(), Null), 
            @ActorId
        );

    Declare @Id Bigint = Scope_identity();

    Insert dbo.AuditLogs 
    (
        UserId, 
        Action, 
        Module, 
        EntityName, 
        EntityId, 
        NewValuesJson, 
        CreatedAt
    )
    Values
        (
            @ActorId,
            'CREATE',
            'COURSE',
            'Course',
            Convert(Nvarchar(100), @Id),
            (
                Select
                    @Code code,
                    @Title title,
                    @Status status
                For Json Path, Without_array_wrapper
            ),
            Sysutcdatetime()
        );

    Commit Transaction;

    Select
        @Id;

End

ALTER PROCEDURE dbo.LMS_Course_Delete
    @Id Bigint,
    @ActorId Bigint,
    @IsAdmin Bit = 0
As
Begin
    Set Nocount On;

    Set Xact_abort On;

    If Not Exists (
        Select
            1
        From dbo.SIM_Courses
        Where (CourseID = @Id)
            And (IsDeleted = 0)
            And (@IsAdmin = 1 Or TeacherUserID = @ActorId)
    ) Begin
    Select
        0;

    Return;

End;

Begin Transaction;

Update dbo.SIM_Courses
Set
    IsDeleted = 1,
    UpdatedAt = Sysutcdatetime(),
    UpdatedByUserID = @ActorId
Where (CourseID = @Id);

Update dbo.SIM_Chapters
Set
    IsDeleted = 1,
    UpdatedAt = Sysutcdatetime()
Where (CourseID = @Id);

Update dbo.SIM_Lessons
Set
    IsDeleted = 1,
    UpdatedAt = Sysutcdatetime()
Where (CourseID = @Id);

Insert dbo.AuditLogs (UserId, Action, Module, EntityName, EntityId, NewValuesJson, CreatedAt)
Values
    (@ActorId, 'DELETE', 'COURSE', 'Course', Convert(Nvarchar(100), @Id), N'{"isDeleted":true}', Sysutcdatetime());

Commit Transaction;

Select
    1;

End

