    If @Code = ''
    Or @Title = ''
    Or @PassingScore < 0
    Or @PassingScore > 100
    Or @Status Not In ('DRAFT', 'PUBLISHED', 'ARCHIVED') Throw 50001,
    N'Dữ liệu khóa học không hợp lệ.',
    1;

    If Not Exists (
        Select
            1
        From dbo.SYS_Users
        Where (UserID = @TeacherId)
