CREATE OR ALTER PROCEDURE dbo.LMS_Discussion_Create
    @CourseId Bigint,
    @LessonId Bigint = Null,
    @UserId Bigint,
    @Title NVARCHAR(500),
    @Content NVARCHAR(MAX),
    @ParentId Bigint = Null,
    @UpdatedUser NVARCHAR(100) = NULL
As
Begin
    Set Nocount On;
    Set Xact_abort On;

    If Not Exists
    (
        Select
            1
        From dbo.SIM_Courses
        Where (CourseID = @CourseId)
            And (IsDeleted = 0)
    )
        Throw 50002, N'Khóa học không tồn tại.', 1;

    If @LessonId Is Not Null And Not Exists
    (
        Select
            1
        From dbo.SIM_Lessons
        Where (LessonID = @LessonId)
            And (CourseId = @CourseId)
            And (IsDeleted = 0)
    )
        Throw 50003, N'Bài học không tồn tại hoặc không thuộc khóa học này.', 1;

    If @ParentId Is Not Null And Not Exists
    (
        Select
            1
        From dbo.SIM_Discussions
        Where (DiscussionID = @ParentId)
            And (IsDeleted = 0)
    )
        Throw 50004, N'Chủ đề cha không tồn tại.', 1;

    Begin Transaction;

    Declare @DiscussionId Bigint;
    Select @DiscussionId = NextId From dbo.Sequence Where Name = 'Discussion';
    Update dbo.Sequence Set NextId = NextId + 1 Where Name = 'Discussion';

    Insert dbo.SIM_Discussions
    (
        DiscussionID,
        CourseID,
        LessonID,
        UserID,
        Title,
        Content,
        ParentID,
        ReplyCount,
        ViewCount,
        CreatedUser,
        UpdatedUser
    )
    Values
    (
        @DiscussionId,
        @CourseId,
        @LessonId,
        @UserId,
        @Title,
        @Content,
        @ParentId,
        0,
        0,
        @UpdatedUser,
        @UpdatedUser
    );

    If @ParentId Is Not Null
    Begin
        Update dbo.SIM_Discussions
        Set ReplyCount = ReplyCount + 1,
            UpdatedAt = Sysutcdatetime(),
            UpdatedUser = @UpdatedUser
        Where DiscussionID = @ParentId;
    End

    Insert dbo.AuditLogs
    (
        UserId,
        Action,
        Module,
        EntityName,
        EntityId
    )
    Values
    (
        @UserId,
        'CREATE',
        'DISCUSSION',
        'Discussion',
        Convert(Nvarchar(100), @DiscussionId)
    );

    Commit Transaction;

    Select
        @DiscussionId DiscussionID;
End

CREATE OR ALTER PROCEDURE dbo.LMS_Discussion_Update
    @DiscussionId Bigint,
    @UserId Bigint,
    @Title NVARCHAR(500) = Null,
    @Content NVARCHAR(MAX) = Null,
    @UpdatedUser NVARCHAR(100) = NULL
As
Begin
    Set Nocount On;
    Set Xact_abort On;

    If Not Exists
    (
        Select
            1
        From dbo.SIM_Discussions
        Where (DiscussionID = @DiscussionId)
            And (IsDeleted = 0)
    )
        Throw 50002, N'Chủ đề thảo luận không tồn tại.', 1;

    If Not Exists
    (
        Select
            1
        From dbo.SIM_Discussions
        Where (DiscussionID = @DiscussionId)
            And (UserID = @UserId)
            And (IsDeleted = 0)
    )
        Throw 50003, N'Bạn không có quyền chỉnh sửa chủ đề này.', 1;

    Begin Transaction;

    Update dbo.SIM_Discussions
    Set Title = Coalesce(@Title, Title),
        Content = Coalesce(@Content, Content),
        UpdatedAt = Sysutcdatetime(),
        UpdatedUser = @UpdatedUser
    Where DiscussionID = @DiscussionId;

    Insert dbo.AuditLogs
    (
        UserId,
        Action,
        Module,
        EntityName,
        EntityId
    )
    Values
    (
        @UserId,
        'UPDATE',
        'DISCUSSION',
        'Discussion',
        Convert(Nvarchar(100), @DiscussionId)
    );

    Commit Transaction;

    Select
        1;
End

