CREATE OR ALTER PROCEDURE dbo.LMS_Enrollment_Create
    @CourseId Bigint,
    @StudentId Bigint,
    @ActorId Bigint,
    @CreatedUser NVARCHAR(100) = NULL
As
Begin
    Set Nocount On;
    Set Xact_abort On;

    If Not Exists
    (
        Select
            1
        From dbo.SIM_Courses
        Where (CourseID = @CourseId)
            And (IsDeleted = 0)
    )
        Or Not Exists
    (
        Select
            1
        From dbo.SYS_Users
        Where (UserID = @StudentId)
            And (IsDeleted = 0)
    )
        Throw 50002, N'Khóa học hoặc học viên không tồn tại.', 1;

    If Exists
    (
        Select
            1
        From dbo.LMS_Enrollments
        Where (CourseId = @CourseId)
            And (StudentUserID = @StudentId)
            And (Status <> 'CANCELLED')
    )
        Throw 50006, N'Học viên đã được ghi danh vào khóa học.', 1;

    Begin Transaction;

    Declare @Id Bigint;

    Insert dbo.LMS_Enrollments
    (
        CourseId,
        StudentUserID,
        EnrolledAt,
        Status,
        ProgressPercent,
        CreatedByUserID,
        CreatedUser
    )
    Values
    (
        @CourseId,
        @StudentId,
        Sysutcdatetime(),
        'ACTIVE',
        0,
        @ActorId,
        @CreatedUser
    );

    Set @Id = Scope_Identity();

    Insert dbo.SIM_Notifications
    (
        UserID,
        Title,
        Message,
        NotificationType,
        EntityType,
        EntityID,
        CreatedAt,
        CreatedUser
    )
    Select
        @StudentId,
        N'Bạn đã được ghi danh khóa học',
        Concat(N'Bạn có thể bắt đầu học khóa "', dbo.SIM_Courses.Title, N'".'),
        'COURSE',
        'COURSE',
        dbo.SIM_Courses.CourseID,
        Sysutcdatetime(),
        @CreatedUser
    From dbo.SIM_Courses
    Where (dbo.SIM_Courses.CourseID = @CourseId);

    Commit;

    Select
        @Id;
End

CREATE OR ALTER PROCEDURE dbo.LMS_Lesson_Update
    @Id Bigint,
    @Title Nvarchar(500),
    @Description Nvarchar(1000) = Null,
    @LessonType Varchar(50),
    @DurationSeconds Int,
    @SortOrder Int,
    @IsRequired Bit,
    @PassingScore Decimal(5, 2) = Null,
    @ContentHtml Nvarchar(Max) = Null,
    @DocumentUrl Nvarchar(1000) = Null,
    @AssignmentFolderName Nvarchar(250) = Null,
    @AssignmentStartAt Datetime2 = Null,
    @DueAt Datetime2 = Null,
    @AssignmentMaxScore Decimal(8, 2) = 100,
    @MaxSubmissionAttempts Int = 3,
    @MaxSubmissionFileSizeMB Int = 50,
    @AllowLateSubmission Bit = 0,
    @Status Varchar(30),
    @ActorId Bigint,
    @IsAdmin Bit = 0
As
Begin
    Set Nocount On;
    Set Xact_abort On;

    If Nullif(Ltrim(Rtrim(@Title)), '') Is Null
    Or @LessonType Not In ('VIDEO', 'INTERACTIVE_VIDEO', 'QUIZ', 'DOCUMENT', 'EDITOR', 'ASSIGNMENT', 'INTERACTIVE_CONTENT')
    Or @DurationSeconds < 0
    Or @SortOrder < 1
    Or @AssignmentMaxScore Not Between 1 And 10000
    Or @MaxSubmissionAttempts Not Between 1 And 20
    Or @MaxSubmissionFileSizeMB Not Between 1 And 200
    Or @PassingScore Not Between 0 And 100
        Throw 50001, N'Dữ liệu bài học không hợp lệ.', 1;

    Begin Transaction;

    Update dbo.SIM_Lessons
    Set
        Title = @Title,
        Description = @Description,
        LessonType = @LessonType,
        DurationSeconds = @DurationSeconds,
        SortOrder = @SortOrder,
        IsRequired = @IsRequired,
        PassingScore = @PassingScore,
        ContentHtml = @ContentHtml,
        DocumentUrl = @DocumentUrl,
        AssignmentFolderName = @AssignmentFolderName,
        AssignmentStartAt = @AssignmentStartAt,
        DueAt = @DueAt,
        AssignmentMaxScore = @AssignmentMaxScore,
        MaxSubmissionAttempts = @MaxSubmissionAttempts,
        MaxSubmissionFileSizeMB = @MaxSubmissionFileSizeMB,
        AllowLateSubmission = @AllowLateSubmission,
        Status = @Status,
        UpdatedAt = Sysutcdatetime()
    From dbo.SIM_Lessons
        Inner Join dbo.SIM_Courses On dbo.SIM_Courses.CourseID = dbo.SIM_Lessons.CourseID
    Where (dbo.SIM_Lessons.LessonID = @Id)
        And (dbo.SIM_Lessons.IsDeleted = 0)
        And (@IsAdmin = 1 Or dbo.SIM_Courses.TeacherUserID = @ActorId);

    Declare @Rows Int = @@Rowcount;

    If @Rows > 0
    Begin
        Insert dbo.AuditLogs (UserId, Action, Module, EntityName, EntityId)
        Values
            (@ActorId, 'UPDATE', 'LESSON', 'Lesson', Convert(Nvarchar(100), @Id));

        -- Send notifications to enrolled students
        Insert dbo.SIM_Notifications
        (
            UserID,
            Title,
            Message,
            NotificationType,
            EntityType,
            EntityID,
            CreatedAt,
            CreatedUser
        )
        Select
            e.StudentUserID,
            N'Cập nhật bài học',
            Concat(N'Bài học "', @Title, N'" trong khóa "', c.Title, N'" đã được cập nhật.'),
            'LESSON',
            'LESSON',
            @Id,
            Sysutcdatetime(),
            Convert(Nvarchar(100), @ActorId)
        From dbo.LMS_Enrollments e
            Inner Join dbo.SIM_Courses c On c.CourseID = e.CourseId
            Inner Join dbo.SIM_Lessons l On l.CourseID = c.CourseID
        Where (l.LessonID = @Id)
            And (e.Status = 'ACTIVE')
            And (c.IsDeleted = 0);
    End

    Commit;

    Select
        @Rows;
End

CREATE OR ALTER PROCEDURE dbo.LMS_Course_Update
    @Id Bigint,
    @Code Nvarchar(100),
    @Title Nvarchar(500),
    @Slug Nvarchar(500) = Null,
    @ThumbnailUrl Nvarchar(1000) = Null,
    @ShortDescription Nvarchar(1000) = Null,
    @Description Nvarchar(Max) = Null,
    @TeacherId Bigint,
    @CategoryId Bigint = Null,
    @ClassSubjectID Bigint = Null,
    @Level Varchar(50),
    @PassingScore Decimal(5, 2),
    @Status Varchar(30),
    @ActorId Bigint,
    @IsAdmin Bit = 0
As
Begin
    Set Nocount On;
    Set Xact_abort On;

    Set @Code = Ltrim(Rtrim(@Code));
    Set @Title = Ltrim(Rtrim(@Title));
    Set @Slug = Coalesce(Nullif(Ltrim(Rtrim(@Slug)), ''), Lower(Replace(@Code, ' ', '-')));

    If @Code = ''
    Or @Title = ''
    Or @PassingScore < 0
    Or @PassingScore > 100
    Or @Status Not In ('DRAFT', 'PUBLISHED', 'ARCHIVED')
        Throw 50001, N'Dữ liệu khóa học không hợp lệ.', 1;

    If Not Exists (
        Select
            1
        From dbo.SYS_Users
        Where (UserID = @TeacherId)
            And (TeacherID Is Not Null)
            And (IsDeleted = 0)
    )
        Throw 50002, N'Giảng viên không tồn tại.', 1;

    If @CategoryId Is Not Null
    AND NOT EXISTS (
        Select
            1
        From dbo.SIM_CourseCategories
        Where (CourseCategoryID = @CategoryId)
            And (Status = 'ACTIVE')
    )
        Throw 50002, N'Danh mục không tồn tại.', 1;

    If @ClassSubjectID Is Not Null
    AND NOT EXISTS (
        Select
            1
        From dbo.SIM_Class_Subject
        Where (DataGroupID = 1)
            And (ClassSubjectID = @ClassSubjectID)
            And (ClassSubjectStatus = 1)
    )
        Throw 50002, N'Môn học lớp không tồn tại.', 1;

    If Exists (
        Select
            1
        From dbo.SIM_Courses
        Where (CourseID <> @Id)
            And (Code = @Code Or Slug = @Slug)
            And (IsDeleted = 0)
    )
        Throw 50006, N'Mã hoặc slug khóa học đã tồn tại.', 1;

    Declare @Old Nvarchar(Max) = (
        Select
            Code code,
            Title title,
            Status status
        From dbo.SIM_Courses
        Where (CourseID = @Id)
        For Json Path, Without_array_wrapper
    );

    Begin Transaction;

    Update dbo.SIM_Courses
    Set
        Code = @Code,
        Title = @Title,
        Slug = @Slug,
        ThumbnailUrl = @ThumbnailUrl,
        ShortDescription = @ShortDescription,
        Description = @Description,
        TeacherUserID = @TeacherId,
        CourseCategoryID = @CategoryId,
        DataGroupID = 1,
        ClassSubjectID = @ClassSubjectID,
        Level = @Level,
        PassingScore = @PassingScore,
        Status = @Status,
        PublishedAt = Iif(@Status = 'PUBLISHED', Coalesce(PublishedAt, Sysutcdatetime()), PublishedAt),
        UpdatedAt = Sysutcdatetime(),
        UpdatedByUserID = @ActorId
    Where (CourseID = @Id)
        And (IsDeleted = 0)
        And (@IsAdmin = 1 Or TeacherUserID = @ActorId);

    Declare @Rows Int = @@Rowcount;

    If @Rows > 0
    Begin
        Insert dbo.AuditLogs (UserId, Action, Module, EntityName, EntityId, OldValuesJson, NewValuesJson, CreatedAt)
        Values
            (
                @ActorId,
                'UPDATE',
                'COURSE',
                'Course',
                Convert(Nvarchar(100), @Id),
                @Old,
                (
                    Select
                        @Code code,
                        @Title title,
                        @Status status
                    For Json Path, Without_array_wrapper
                ),
                Sysutcdatetime()
            );

        -- Send notifications to enrolled students
        Insert dbo.SIM_Notifications
        (
            UserID,
            Title,
            Message,
            NotificationType,
            EntityType,
            EntityID,
            CreatedAt,
            CreatedUser
        )
        Select
            e.StudentUserID,
            N'Cập nhật khóa học',
            Concat(N'Khóa học "', @Title, N'" đã được cập nhật.'),
            'COURSE',
            'COURSE',
            @Id,
            Sysutcdatetime(),
            Convert(Nvarchar(100), @ActorId)
        From dbo.LMS_Enrollments e
        Where (e.CourseId = @Id)
            And (e.Status = 'ACTIVE');
    End

    Commit Transaction;

    Select
        @Rows;
End

