CREATE OR ALTER PROCEDURE dbo.LMS_Course_Create
    @Code Nvarchar(100),
    @Title Nvarchar(500),
    @Slug Nvarchar(500) = Null,
    @ThumbnailUrl Nvarchar(1000) = Null,
    @ShortDescription Nvarchar(1000) = Null,
    @Description Nvarchar(Max) = Null,
    @TeacherId Bigint,
    @CategoryId Bigint = Null,
    @ClassSubjectID Bigint = Null,
    @Level Varchar(50),
    @PassingScore Decimal(5, 2),
    @Status Varchar(30),
    @ActorId Bigint
As
Begin
    Set Nocount On;
    Set Xact_abort On;

    Set @Code = Ltrim(Rtrim(@Code));
    Set @Title = Ltrim(Rtrim(@Title));
    Set @Slug = Coalesce(Nullif(Ltrim(Rtrim(@Slug)), ''), Lower(Replace(@Code, ' ', '-')));

    If @Code = ''
    Or @Title = ''
    Or @PassingScore < 0
    Or @PassingScore > 100
    Or @Status Not In ('DRAFT', 'PUBLISHED', 'ARCHIVED')
        Throw 50001, N'Dữ liệu khóa học không hợp lệ.', 1;

    If Not Exists (
        Select
            1
        From dbo.SYS_Users
        Where (UserID = @TeacherId)
            And (TeacherID Is Not Null)
            And (IsDeleted = 0)
    )
        Throw 50002, N'Giảng viên không tồn tại.', 1;

    If @CategoryId Is Not Null
    AND NOT EXISTS (
        Select
            1
        From dbo.SIM_CourseCategories
        Where (CourseCategoryID = @CategoryId)
            And (Status = 'ACTIVE')
    )
        Throw 50002, N'Danh mục không tồn tại.', 1;

    If @ClassSubjectID Is Not Null
    AND NOT EXISTS (
        Select
            1
        From dbo.SIM_Class_Subject
        Where (DataGroupID = 1)
            And (ClassSubjectID = @ClassSubjectID)
            And (ClassSubjectStatus = 1)
    )
        Throw 50002, N'Môn học lớp không tồn tại.', 1;

    If Exists (
        Select
            1
        From dbo.SIM_Courses
        Where (Code = @Code Or Slug = @Slug)
            And (IsDeleted = 0)
    )
        Throw 50006, N'Mã hoặc slug khóa học đã tồn tại.', 1;

    Begin Transaction;

    Insert dbo.SIM_Courses
    (
        Code, 
        Title, 
        Slug, 
        ThumbnailUrl, 
        ShortDescription, 
        Description, 
        TeacherUserID, 
        CourseCategoryID, 
        DataGroupID, 
        ClassSubjectID, 
        Level, 
        PassingScore, 
        Status, 
        PublishedAt, 
        CreatedByUserID
    )
    Values
        (
            @Code, 
            @Title, 
            @Slug, 
            @ThumbnailUrl, 
            @ShortDescription, 
            @Description, 
            @TeacherId, 
            @CategoryId, 
            1, 
            @ClassSubjectID, 
            @Level, 
            @PassingScore, 
            @Status, 
            Iif(@Status = 'PUBLISHED', Sysutcdatetime(), Null), 
            @ActorId
        );

    Declare @Id Bigint = Scope_identity();

    Insert dbo.AuditLogs 
    (
        UserId, 
        Action, 
        Module, 
        EntityName, 
        EntityId, 
        NewValuesJson, 
        CreatedAt
    )
    Values
        (
            @ActorId,
            'CREATE',
            'COURSE',
            'Course',
            Convert(Nvarchar(100), @Id),
            (
                Select
                    @Code code,
                    @Title title,
                    @Status status
                For Json Path, Without_array_wrapper
            ),
            Sysutcdatetime()
        );

    -- Send notification to teacher when course is created
    Insert dbo.SIM_Notifications
    (
        UserID,
        Title,
        Message,
        NotificationType,
        EntityType,
        EntityID,
        CreatedAt,
        CreatedUser
    )
    Values
    (
        @TeacherId,
        N'Khóa học mới',
        Concat(N'Khóa học "', @Title, N'" đã được tạo thành công.'),
        'COURSE',
        'COURSE',
        @Id,
        Sysutcdatetime(),
        Convert(Nvarchar(100), @ActorId)
    );

    Commit Transaction;

    Select
        @Id;
End

CREATE OR ALTER PROCEDURE dbo.LMS_QuizAttempt_Submit
    @QuizAttemptID Bigint,
    @StudentUserID Bigint,
    @AnswersJson Nvarchar(Max)
As
Begin
    Set Nocount On;
    Set Xact_abort On;

    Declare @QuizID Bigint;
    Declare @LessonID Bigint;
    Declare @CourseID Bigint;
    Declare @PassingScore Decimal(5, 2);
    Declare @TimeLimitMinutes Int;
    Declare @StartedAt Datetime2;
    Declare @TeacherID Bigint;

    Select
        @QuizID = dbo.SIM_QuizAttempts.QuizID,
        @LessonID = dbo.SIM_Quizzes.LessonID,
        @CourseID = (Select CourseId From dbo.SIM_Lessons Where LessonID = dbo.SIM_Quizzes.LessonID),
        @PassingScore = dbo.SIM_Quizzes.PassingScore,
        @TimeLimitMinutes = dbo.SIM_Quizzes.TimeLimitMinutes,
        @StartedAt = dbo.SIM_QuizAttempts.StartedAt,
        @TeacherID = (Select TeacherUserID From dbo.SIM_Courses Where CourseID = (Select CourseId From dbo.SIM_Lessons Where LessonID = dbo.SIM_Quizzes.LessonID))
    From dbo.SIM_QuizAttempts
        Inner Join dbo.SIM_Quizzes On dbo.SIM_Quizzes.QuizID = dbo.SIM_QuizAttempts.QuizID
    Where (dbo.SIM_QuizAttempts.QuizAttemptID = @QuizAttemptID)
        And (dbo.SIM_QuizAttempts.StudentUserID = @StudentUserID)
        And (dbo.SIM_QuizAttempts.AttemptStatus = 'IN_PROGRESS');

    If @QuizID Is Null
        Throw 50002, N'Lượt làm bài không tồn tại hoặc đã được nộp.', 1;

    If @TimeLimitMinutes Is Not Null And Dateadd(Second, 15, Dateadd(Minute, @TimeLimitMinutes, @StartedAt)) < Sysutcdatetime()
        Throw 50004, N'Lượt làm bài đã hết thời gian.', 1;

    Create Table #tblAnswer
    (
        QuestionID Bigint Not Null Primary Key,
        AnswerText Nvarchar(Max) Null
    );

    Insert #tblAnswer(QuestionID, AnswerText)
    Select
        QuestionID,
        Upper(Ltrim(Rtrim(AnswerText)))
    From Openjson(Coalesce(@AnswersJson, N'[]'))
    With
    (
        QuestionID Bigint '$.questionId',
        AnswerText Nvarchar(Max) '$.answerText'
    );

    If Exists (Select 1 From #tblAnswer Where Not Exists (Select 1 From dbo.SIM_QuizQuestions Where QuizID = @QuizID And QuestionID = #tblAnswer.QuestionID))
        Throw 50001, N'Câu trả lời không thuộc bài kiểm tra.', 1;

    Begin Transaction;

    Insert dbo.SIM_QuizAttemptAnswers(QuizAttemptID, QuestionID, AnswerText, IsCorrect, ScoreAwarded)
    Select
        @QuizAttemptID,
        dbo.SIM_QuizQuestions.QuestionID,
        #tblAnswer.AnswerText,
        Result.IsCorrect,
        Iif(Result.IsCorrect = 1, dbo.SIM_QuizQuestions.Points, 0)
    From dbo.SIM_QuizQuestions
        Left Join #tblAnswer On #tblAnswer.QuestionID = dbo.SIM_QuizQuestions.QuestionID
        Outer Apply
        (
            Select Case
                When dbo.SIM_QuizQuestions.QuestionType In ('SINGLE_CHOICE', 'TRUE_FALSE', 'MULTIPLE_CHOICE')
                    Then Iif(Convert(Nvarchar(10), #tblAnswer.AnswerText) = Convert(Nvarchar(10), dbo.SIM_QuizQuestions.CorrectOption), Convert(Bit, 1), Convert(Bit, 0))
                When dbo.SIM_QuizQuestions.QuestionType = 'SHORT_ANSWER'
                    Then Iif
                    (
                        Upper(Ltrim(Rtrim(dbo.SIM_QuizQuestions.CorrectAnswerText))) = Upper(Ltrim(Rtrim(#tblAnswer.AnswerText))),
                        Convert(Bit, 1),
                        Convert(Bit, 0)
                    )
                Else Convert(Bit, 0)
            End IsCorrect
        ) Result
    Where (dbo.SIM_QuizQuestions.QuizID = @QuizID);

    Declare @Score Decimal(8, 2) = (Select Coalesce(Sum(ScoreAwarded), 0) From dbo.SIM_QuizAttemptAnswers Where QuizAttemptID = @QuizAttemptID);
    Declare @MaxScore Decimal(8, 2) = (Select Coalesce(Sum(Points), 0) From dbo.SIM_QuizQuestions Where QuizID = @QuizID);
    Declare @ScorePercent Decimal(5, 2) = Convert(Decimal(5, 2), @Score * 100.0 / Nullif(@MaxScore, 0));
    Declare @Passed Bit = Iif(@ScorePercent >= @PassingScore, 1, 0);

    Update dbo.SIM_QuizAttempts
    Set
        SubmittedAt = Sysutcdatetime(),
        Score = @Score,
        MaxScore = @MaxScore,
        ScorePercent = @ScorePercent,
        Passed = @Passed,
        AttemptStatus = 'SUBMITTED'
    Where (QuizAttemptID = @QuizAttemptID);

    Merge dbo.SIM_StudentLessonProgress As Target
    Using (Select @StudentUserID StudentUserID, @CourseID CourseID, @LessonID LessonID) As Source
        On Target.StudentUserID = Source.StudentUserID And Target.LessonID = Source.LessonID
    When Matched Then
        Update Set Score = @ScorePercent, AttemptCount = Target.AttemptCount + 1, ProgressPercent = 100, Completed = 1, CompletedAt = Coalesce(Target.CompletedAt, Sysutcdatetime()), LastAccessAt = Sysutcdatetime(), UpdatedAt = Sysutcdatetime()
    When Not Matched Then
        Insert (StudentUserID, CourseID, LessonID, ProgressPercent, Score, AttemptCount, Completed, CompletedAt, LastAccessAt, ActiveStudySeconds)
        Values (Source.StudentUserID, Source.CourseID, Source.LessonID, 100, @ScorePercent, 1, 1, Sysutcdatetime(), Sysutcdatetime(), 0);

    -- Send notification to teacher when student submits quiz
    If @TeacherID Is Not Null
    Begin
        Insert dbo.SIM_Notifications
        (
            UserID,
            Title,
            Message,
            NotificationType,
            EntityType,
            EntityID,
            CreatedAt,
            CreatedUser
        )
        Select
            @TeacherID,
            N'Học sinh nộp bài kiểm tra',
            Concat(N'Học sinh ', u.FullName, N' đã nộp bài kiểm tra. Điểm: ', @ScorePercent, N'%'),
            'QUIZ',
            'QUIZ_ATTEMPT',
            @QuizAttemptID,
            Sysutcdatetime(),
            Convert(Nvarchar(100), @StudentUserID)
        From dbo.SYS_Users u
        Where u.UserID = @StudentUserID;
    End

    Commit Transaction;

    Insert dbo.AuditLogs
    (
        UserId,
        Action,
        Module,
        EntityName,
        EntityId
    )
    Values
    (
        @StudentUserID,
        'SUBMIT',
        'QUIZ',
        'QuizAttempt',
        Convert(Nvarchar(100), @QuizAttemptID)
    );

    Select
        @QuizAttemptID QuizAttemptID,
        @Score Score,
        @MaxScore MaxScore,
        @ScorePercent ScorePercent,
        @Passed Passed;
End

CREATE OR ALTER PROCEDURE dbo.LMS_AssignmentSubmission_Save
    @LessonID Bigint,
    @StudentUserID Bigint,
    @SubmissionText Nvarchar(Max) = Null,
    @FileUrl Nvarchar(1000) = Null,
    @OriginalFileName Nvarchar(500) = Null,
    @StoredFileName Nvarchar(500) = Null,
    @FileSize Bigint = Null,
    @MimeType Nvarchar(150) = Null,
    @Action Varchar(20) = 'SUBMIT'
As
Begin
    Set Nocount On;
    Set Xact_abort On;

    Set @Action = Upper(Ltrim(Rtrim(@Action)));

    If @Action Not In ('DRAFT', 'SUBMIT')
        Throw 50001, N'Thao tác bài nộp không hợp lệ.', 1;

    Declare @CourseID Bigint;
    Declare @AssignmentStartAt Datetime2;
    Declare @DueAt Datetime2;
    Declare @AllowLateSubmission Bit;
    Declare @MaxSubmissionAttempts Int;
    Declare @TeacherID Bigint;
    Declare @LessonTitle Nvarchar(500);

    Select
        @CourseID = dbo.SIM_Lessons.CourseID,
        @AssignmentStartAt = dbo.SIM_Lessons.AssignmentStartAt,
        @DueAt = dbo.SIM_Lessons.DueAt,
        @AllowLateSubmission = dbo.SIM_Lessons.AllowLateSubmission,
        @MaxSubmissionAttempts = dbo.SIM_Lessons.MaxSubmissionAttempts,
        @LessonTitle = dbo.SIM_Lessons.Title
    From dbo.SIM_Lessons
    Where (dbo.SIM_Lessons.LessonID = @LessonID)
        And (dbo.SIM_Lessons.LessonType = 'ASSIGNMENT')
        And (dbo.SIM_Lessons.IsDeleted = 0);

    -- Get teacher ID
    Select @TeacherID = TeacherUserID
    From dbo.SIM_Courses
    Where CourseID = @CourseID;

    If @CourseID Is Null
        Throw 50002, N'Bài tập không tồn tại.', 1;

    If Not Exists
    (
        Select 1
        From dbo.LMS_Enrollments
        Where (dbo.LMS_Enrollments.CourseID = @CourseID)
            And (dbo.LMS_Enrollments.StudentUserID = @StudentUserID)
            And (dbo.LMS_Enrollments.Status <> 'CANCELLED')
    )
        Throw 50003, N'Học viên chưa được ghi danh vào môn học.', 1;

    If @AssignmentStartAt Is Not Null And Sysutcdatetime() < @AssignmentStartAt
        Throw 50006, N'Bài tập chưa đến thời gian mở.', 1;

    If @Action = 'SUBMIT' And @DueAt Is Not Null And Sysutcdatetime() > @DueAt And @AllowLateSubmission = 0
        Throw 50006, N'Bài tập đã hết hạn nộp.', 1;

    If Nullif(Ltrim(Rtrim(@SubmissionText)), N'') Is Null And @FileUrl Is Null
        Throw 50001, N'Cần nhập nội dung hoặc chọn file cho bài làm.', 1;

    Begin Transaction;

    Declare @AssignmentSubmissionID Bigint;
    Declare @AttemptNumber Int;
    Declare @CurrentSubmissionStatus Varchar(30);

    If Exists
    (
        Select 1
        From dbo.LMS_AssignmentSubmissions
        Where (dbo.LMS_AssignmentSubmissions.LessonID = @LessonID)
            And (dbo.LMS_AssignmentSubmissions.StudentUserID = @StudentUserID)
            And (dbo.LMS_AssignmentSubmissions.SubmissionStatus = 'GRADED')
    )
        Throw 50006, N'Bài làm đã được giáo viên chấm nên không thể chỉnh sửa.', 1;

    Select Top (1)
        @AssignmentSubmissionID = dbo.LMS_AssignmentSubmissions.AssignmentSubmissionID,
        @AttemptNumber = dbo.LMS_AssignmentSubmissions.AttemptNumber,
        @CurrentSubmissionStatus = dbo.LMS_AssignmentSubmissions.SubmissionStatus
    From dbo.LMS_AssignmentSubmissions With (Updlock, Holdlock)
    Where (dbo.LMS_AssignmentSubmissions.LessonID = @LessonID)
        And (dbo.LMS_AssignmentSubmissions.StudentUserID = @StudentUserID)
        And
        (
            (dbo.LMS_AssignmentSubmissions.SubmissionStatus = 'DRAFT')
            Or
            (
                dbo.LMS_AssignmentSubmissions.SubmissionStatus In ('SUBMITTED', 'RETURNED')
                And (@DueAt Is Null Or Sysutcdatetime() <= @DueAt)
            )
        )
    Order By dbo.LMS_AssignmentSubmissions.AttemptNumber Desc;

    If @AssignmentSubmissionID Is Null
    Begin
        Select
            @AttemptNumber = Coalesce(Max(dbo.LMS_AssignmentSubmissions.AttemptNumber), 0) + 1
        From dbo.LMS_AssignmentSubmissions With (Updlock, Holdlock)
        Where (dbo.LMS_AssignmentSubmissions.LessonID = @LessonID)
            And (dbo.LMS_AssignmentSubmissions.StudentUserID = @StudentUserID);

        If @AttemptNumber > @MaxSubmissionAttempts
            Throw 50006, N'Bạn đã sử dụng hết số lần nộp bài cho phép.', 1;

        Insert dbo.LMS_AssignmentSubmissions
        (
            LessonID,
            CourseID,
            StudentUserID,
            AttemptNumber,
            SubmissionText,
            FileUrl,
            OriginalFileName,
            StoredFileName,
            FileSize,
            MimeType,
            SubmittedAt,
            SubmissionStatus,
            IsLate
        )
        Values
            (@LessonID, @CourseID, @StudentUserID, @AttemptNumber, @SubmissionText, @FileUrl, @OriginalFileName, @StoredFileName, @FileSize, @MimeType, Sysutcdatetime(), Iif(@Action = 'SUBMIT', 'SUBMITTED', 'DRAFT'), Iif(@Action = 'SUBMIT' And @DueAt Is Not Null And Sysutcdatetime() > @DueAt, 1, 0));

        Set @AssignmentSubmissionID = Scope_identity();
    End;
    Else
    Begin
        Update dbo.LMS_AssignmentSubmissions
        Set
            SubmissionText = @SubmissionText,
            FileUrl = Coalesce(@FileUrl, FileUrl),
            OriginalFileName = Coalesce(@OriginalFileName, OriginalFileName),
            StoredFileName = Coalesce(@StoredFileName, StoredFileName),
            FileSize = Coalesce(@FileSize, FileSize),
            MimeType = Coalesce(@MimeType, MimeType),
            SubmittedAt = Sysutcdatetime(),
            SubmissionStatus = Case When @CurrentSubmissionStatus In ('SUBMITTED', 'RETURNED') Then 'SUBMITTED' Else Iif(@Action = 'SUBMIT', 'SUBMITTED', 'DRAFT') End,
            IsLate = Iif(@Action = 'SUBMIT' And @DueAt Is Not Null And Sysutcdatetime() > @DueAt, 1, 0)
        Where (dbo.LMS_AssignmentSubmissions.AssignmentSubmissionID = @AssignmentSubmissionID);
    End;

    If @FileUrl Is Not Null
        Insert dbo.LMS_AssignmentSubmissionFiles
        (
            AssignmentSubmissionID,
            OriginalFileName,
            StoredFileName,
            FileUrl,
            FileSize,
            MimeType
        )
        Values
            (@AssignmentSubmissionID, @OriginalFileName, @StoredFileName, @FileUrl, Coalesce(@FileSize, 0), Coalesce(@MimeType, N'application/octet-stream'));

    If @Action = 'SUBMIT'
    Begin
        Merge dbo.LMS_StudentLessonProgress As Target
        Using (Select @StudentUserID StudentUserID, @CourseID CourseID, @LessonID LessonID) As Source
            On Target.StudentUserID = Source.StudentUserID And Target.LessonID = Source.LessonID
        When Matched Then
            Update Set ProgressPercent = 100, Completed = 1, CompletedAt = Coalesce(Target.CompletedAt, Sysutcdatetime()), LastAccessAt = Sysutcdatetime(), UpdatedAt = Sysutcdatetime()
        When Not Matched Then
            Insert (StudentUserID, CourseID, LessonID, ProgressPercent, Score, AttemptCount, Completed, CompletedAt, LastAccessAt)
            Values (Source.StudentUserID, Source.CourseID, Source.LessonID, 100, 0, @AttemptNumber, 1, Sysutcdatetime(), Sysutcdatetime());

        -- Send notification to teacher when student submits assignment
        If @TeacherID Is Not Null
        Begin
            Insert dbo.SIM_Notifications
            (
                UserID,
                Title,
                Message,
                NotificationType,
                EntityType,
                EntityID,
                CreatedAt,
                CreatedUser
            )
            Select
                @TeacherID,
                N'Học sinh nộp bài tập',
                Concat(N'Học sinh ', u.FullName, N' đã nộp bài tập "', @LessonTitle, N'" (Lần ', @AttemptNumber, N').'),
                'ASSIGNMENT',
                'ASSIGNMENT_SUBMISSION',
                @AssignmentSubmissionID,
                Sysutcdatetime(),
                Convert(Nvarchar(100), @StudentUserID)
            From dbo.SYS_Users u
            Where u.UserID = @StudentUserID;
        End
    End;

    Commit Transaction;

    Select
        @AssignmentSubmissionID AssignmentSubmissionID,
        @AttemptNumber AttemptNumber,
        Case When @CurrentSubmissionStatus In ('SUBMITTED', 'RETURNED') Then 'SUBMITTED' Else Iif(@Action = 'SUBMIT', 'SUBMITTED', 'DRAFT') End SubmissionStatus;
End

CREATE OR ALTER PROCEDURE dbo.LMS_AssignmentSubmission_Grade
    @AssignmentSubmissionID Bigint,
    @Score Decimal(8, 2) = Null,
    @Feedback Nvarchar(Max) = Null,
    @Action Varchar(20),
    @ActorID Bigint,
    @IsAdmin Bit = 0
As
Begin
    Set Nocount On;
    Set Xact_abort On;

    Set @Action = UPPER(LTRIM(RTRIM(@Action)));

    If @Action Not In ('GRADE', 'RETURN')
        Throw 50001, N'Thao tác chấm bài không hợp lệ.', 1;

    Declare @LessonID Bigint;
    Declare @StudentUserID Bigint;
    Declare @CourseID Bigint;
    Declare @AssignmentMaxScore Decimal(8, 2);
    Declare @LessonTitle Nvarchar(500);

    Select
        @LessonID = dbo.LMS_AssignmentSubmissions.LessonID,
        @StudentUserID = dbo.LMS_AssignmentSubmissions.StudentUserID,
        @CourseID = dbo.LMS_AssignmentSubmissions.CourseID,
        @AssignmentMaxScore = dbo.SIM_Lessons.AssignmentMaxScore,
        @LessonTitle = dbo.SIM_Lessons.Title
    From dbo.LMS_AssignmentSubmissions
        Inner Join dbo.SIM_Lessons On dbo.SIM_Lessons.LessonID = dbo.LMS_AssignmentSubmissions.LessonID
        Inner Join dbo.SIM_Courses On dbo.SIM_Courses.CourseID = dbo.LMS_AssignmentSubmissions.CourseID
    Where (dbo.LMS_AssignmentSubmissions.AssignmentSubmissionID = @AssignmentSubmissionID)
        And (@IsAdmin = 1 Or dbo.SIM_Courses.TeacherUserID = @ActorID);

    If @LessonID Is Null
        Throw 50003, N'Không tìm thấy bài nộp hoặc bạn không có quyền chấm.', 1;

    If @Action = 'GRADE' And (@Score Is Null Or @Score < 0 Or @Score > @AssignmentMaxScore)
        Throw 50001, N'Điểm phải nằm trong khoảng từ 0 đến điểm tối đa của bài tập.', 1;

    Begin Transaction;

    Update dbo.LMS_AssignmentSubmissions
    Set
        Score = Iif(@Action = 'GRADE', @Score, Null),
        Feedback = @Feedback,
        SubmissionStatus = Iif(@Action = 'GRADE', 'GRADED', 'RETURNED'),
        GradedByUserID = @ActorID,
        GradedAt = Sysutcdatetime()
    Where (dbo.LMS_AssignmentSubmissions.AssignmentSubmissionID = @AssignmentSubmissionID);

    If @Action = 'GRADE'
        Update dbo.LMS_StudentLessonProgress
        Set
            Score = @Score,
            ProgressPercent = 100,
            Completed = 1,
            CompletedAt = Coalesce(CompletedAt, Sysutcdatetime()),
            UpdatedAt = Sysutcdatetime()
        Where (dbo.LMS_StudentLessonProgress.StudentUserID = @StudentUserID)
            And (dbo.LMS_StudentLessonProgress.LessonID = @LessonID);
    Else
        update dbo.LMS_StudentLessonProgress
        Set
            Completed = 0,
            CompletedAt = Null,
            ProgressPercent = 80,
            UpdatedAt = Sysutcdatetime()
        Where (dbo.LMS_StudentLessonProgress.StudentUserID = @StudentUserID)
            And (dbo.LMS_StudentLessonProgress.LessonID = @LessonID);

    -- Send notification to student when assignment is graded or returned
    If @Action = 'GRADE'
    Begin
        Insert dbo.SIM_Notifications
        (
            UserID,
            Title,
            Message,
            NotificationType,
            EntityType,
            EntityID,
            CreatedAt,
            CreatedUser
        )
        Values
        (
            @StudentUserID,
            N'Bài tập đã được chấm điểm',
            Concat(N'Bài tập "', @LessonTitle, N'" của bạn đã được chấm điểm. Điểm: ', @Score, N'/', @AssignmentMaxScore),
            'ASSIGNMENT',
            'ASSIGNMENT_SUBMISSION',
            @AssignmentSubmissionID,
            Sysutcdatetime(),
            Convert(Nvarchar(100), @ActorID)
        );
    End
    Else
    Begin
        Insert dbo.SIM_Notifications
        (
            UserID,
            Title,
            Message,
            NotificationType,
            EntityType,
            EntityID,
            CreatedAt,
            CreatedUser
        )
        Values
        (
            @StudentUserID,
            N'Bài tập đã được trả lại',
            Concat(N'Bài tập "', @LessonTitle, N'" của bạn đã được trả lại để sửa lại.'),
            'ASSIGNMENT',
            'ASSIGNMENT_SUBMISSION',
            @AssignmentSubmissionID,
            Sysutcdatetime(),
            Convert(Nvarchar(100), @ActorID)
        );
    End

    Commit Transaction;

    Select
        @AssignmentSubmissionID AssignmentSubmissionID,
        Iif(@Action = 'GRADE', 'GRADED', 'RETURNED') SubmissionStatus,
        Iif(@Action = 'GRADE', @Score, Null) Score;
End

