-- =====================================================================
-- LMS Notification Flow Test Script
-- =====================================================================
-- Purpose: Test the notification system for various LMS events
-- Author: System
-- Date: 2026-10-19
-- =====================================================================

USE LMSCMS_DB_SAMPLE;
GO

PRINT '=====================================================================';
PRINT 'LMS Notification Flow Test';
PRINT '=====================================================================';
PRINT '';

-- =====================================================================
-- SETUP: Get or create test data
-- =====================================================================
PRINT 'STEP 0: Setup - Get test data';
PRINT '----------------------------------------------------------------------';

DECLARE @TestCourseID BIGINT;
DECLARE @TestStudentID BIGINT;
DECLARE @TestTeacherID BIGINT;
DECLARE @TestQuizID BIGINT;
DECLARE @TestQuestionID BIGINT;
DECLARE @TestLessonID BIGINT;
DECLARE @ActorID BIGINT = 1; -- System or admin user

-- Get an existing course
SELECT TOP 1 @TestCourseID = CourseID
FROM dbo.SIM_Courses
WHERE IsDeleted = 0;

IF @TestCourseID IS NULL
BEGIN
    PRINT 'ERROR: No course found in database. Please create a course first.';
    RETURN;
END
PRINT 'Test Course ID: ' + CAST(@TestCourseID AS NVARCHAR(50));

-- Get an existing student
SELECT TOP 1 @TestStudentID = UserID
FROM dbo.SMS_Users
WHERE RoleID = 3 AND IsDeleted = 0; -- Assuming RoleID 3 is student

IF @TestStudentID IS NULL
BEGIN
    PRINT 'ERROR: No student found in database. Please create a student first.';
    RETURN;
END
PRINT 'Test Student ID: ' + CAST(@TestStudentID AS NVARCHAR(50));

-- Get an existing teacher
SELECT TOP 1 @TestTeacherID = UserID
FROM dbo.SMS_Users
WHERE RoleID = 2 AND IsDeleted = 0; -- Assuming RoleID 2 is teacher

IF @TestTeacherID IS NULL
BEGIN
    PRINT 'WARNING: No teacher found. Using student ID as actor.';
    SET @TestTeacherID = @TestStudentID;
END
PRINT 'Test Teacher ID: ' + CAST(@TestTeacherID AS NVARCHAR(50));

PRINT '';

-- =====================================================================
-- STEP 1: Test Course Enrollment Notification
-- =====================================================================
PRINT 'STEP 1: Test Course Enrollment Notification';
PRINT '----------------------------------------------------------------------';

BEGIN TRY
    -- Enroll student in course (this should trigger enrollment notification)
    EXEC dbo.LMS_Enrollment_Create
        @CourseID = @TestCourseID,
        @StudentUserID = @TestStudentID,
        @EnrollmentDate = GETUTCDATE(),
        @Status = 'ACTIVE',
        @CreatedByUserID = @ActorID;

    PRINT 'Enrollment created successfully. Check for notifications.';

    -- Check if notification was created
    SELECT TOP 5 
        NotificationID,
        UserID,
        Title,
        Message,
        NotificationType,
        CreatedAt
    FROM dbo.SIM_Notifications
    WHERE UserID = @TestStudentID
      AND NotificationType = 'COURSE_ENROLLMENT'
    ORDER BY CreatedAt DESC;

    IF @@ROWCOUNT > 0
        PRINT 'SUCCESS: Enrollment notification found.';
    ELSE
        PRINT 'INFO: No enrollment notification found (may need to check procedure implementation).';
END TRY
BEGIN CATCH
    PRINT 'ERROR: ' + ERROR_MESSAGE();
END CATCH
PRINT '';

-- =====================================================================
-- STEP 2: Test Quiz Creation Notification
-- =====================================================================
PRINT 'STEP 2: Test Quiz Creation Notification';
PRINT '----------------------------------------------------------------------';

BEGIN TRY
    -- Get a lesson for the quiz
    SELECT TOP 1 @TestLessonID = LessonID
    FROM dbo.SIM_Lessons
    WHERE IsDeleted = 0 AND LessonType = 'QUIZ';

    IF @TestLessonID IS NULL
    BEGIN
        PRINT 'WARNING: No quiz lesson found. Skipping quiz creation test.';
    END
    ELSE
    BEGIN
        PRINT 'Test Lesson ID: ' + CAST(@TestLessonID AS NVARCHAR(50));

        -- Create a quiz
        EXEC dbo.LMS_Quiz_Create
            @LessonID = @TestLessonID,
            @Title = N'Quiz Test Thông Báo',
            @Description = N'Mô tả quiz test',
            @QuizType = 'STANDARD',
            @Duration = 30,
            @PassingScore = 70,
            @MaxAttempts = 3,
            @ShowAnswers = 1,
            @RandomizeQuestions = 0,
            @Status = 'ACTIVE',
            @CreatedByUserID = @ActorID;

        SET @TestQuizID = SCOPE_IDENTITY();
        PRINT 'Quiz created. ID: ' + CAST(@TestQuizID AS NVARCHAR(50));

        -- Create a question
        EXEC dbo.LMS_Question_Create
            @QuestionType = 'SINGLE_CHOICE',
            @QuestionText = N'Câu hỏi test?',
            @Description = N'Mô tả câu hỏi',
            @Explanation = N'Giải thích câu trả lời',
            @Difficulty = 'EASY',
            @DefaultScore = 10,
            @Status = 'PUBLISHED',
            @CreatedByUserID = @ActorID;

        SET @TestQuestionID = SCOPE_IDENTITY();
        PRINT 'Question created. ID: ' + CAST(@TestQuestionID AS NVARCHAR(50));

        -- Link question to quiz
        EXEC dbo.LMS_QuizQuestion_Create
            @QuizID = @TestQuizID,
            @QuestionID = @TestQuestionID,
            @Score = 10,
            @SortOrder = 1,
            @IsRequired = 1;

        PRINT 'Question linked to quiz.';

        -- Check for notifications
        SELECT TOP 5 
            NotificationID,
            UserID,
            Title,
            Message,
            NotificationType,
            CreatedAt
        FROM dbo.SIM_Notifications
        WHERE NotificationType = 'QUIZ_CREATED'
        ORDER BY CreatedAt DESC;

        IF @@ROWCOUNT > 0
            PRINT 'SUCCESS: Quiz creation notification found.';
        ELSE
            PRINT 'INFO: No quiz creation notification found.';
    END
END TRY
BEGIN CATCH
    PRINT 'ERROR: ' + ERROR_MESSAGE();
END CATCH
PRINT '';

-- =====================================================================
-- STEP 3: Test Quiz Attempt Notification
-- =====================================================================
PRINT 'STEP 3: Test Quiz Attempt Notification';
PRINT '----------------------------------------------------------------------';

BEGIN TRY
    IF @TestQuizID IS NULL
    BEGIN
        PRINT 'WARNING: No quiz ID available. Skipping quiz attempt test.';
    END
    ELSE
    BEGIN
        -- Create a quiz attempt
        EXEC dbo.LMS_QuizAttempt_Create
            @QuizID = @TestQuizID,
            @StudentUserID = @TestStudentID,
            @AttemptNumber = 1,
            @StartedAt = GETUTCDATE(),
            @Status = 'IN_PROGRESS';

        PRINT 'Quiz attempt created.';

        -- Check for notifications
        SELECT TOP 5 
            NotificationID,
            UserID,
            Title,
            Message,
            NotificationType,
            CreatedAt
        FROM dbo.SIM_Notifications
        WHERE UserID = @TestStudentID
          AND NotificationType = 'QUIZ_STARTED'
        ORDER BY CreatedAt DESC;

        IF @@ROWCOUNT > 0
            PRINT 'SUCCESS: Quiz attempt notification found.';
        ELSE
            PRINT 'INFO: No quiz attempt notification found.';
    END
END TRY
BEGIN CATCH
    PRINT 'ERROR: ' + ERROR_MESSAGE();
END CATCH
PRINT '';

-- =====================================================================
-- STEP 4: Test Quiz Completion Notification
-- =====================================================================
PRINT 'STEP 4: Test Quiz Completion Notification';
PRINT '----------------------------------------------------------------------';

BEGIN TRY
    IF @TestQuizID IS NULL
    BEGIN
        PRINT 'WARNING: No quiz ID available. Skipping quiz completion test.';
    END
    ELSE
    BEGIN
        -- Simulate quiz completion by updating the attempt
        -- This would normally be done by the quiz submission procedure
        UPDATE dbo.LMS_QuizAttempts
        SET 
            CompletedAt = GETUTCDATE(),
            Score = 85.5,
            Status = 'COMPLETED',
            Passed = 1
        WHERE QuizID = @TestQuizID
          AND StudentUserID = @TestStudentID
          AND Status = 'IN_PROGRESS';

        PRINT 'Quiz attempt marked as completed.';

        -- Check for notifications
        SELECT TOP 5 
            NotificationID,
            UserID,
            Title,
            Message,
            NotificationType,
            CreatedAt
        FROM dbo.SIM_Notifications
        WHERE UserID = @TestStudentID
          AND (NotificationType = 'QUIZ_COMPLETED' OR NotificationType = 'QUIZ_PASSED')
        ORDER BY CreatedAt DESC;

        IF @@ROWCOUNT > 0
            PRINT 'SUCCESS: Quiz completion notification found.';
        ELSE
            PRINT 'INFO: No quiz completion notification found.';
    END
END TRY
BEGIN CATCH
    PRINT 'ERROR: ' + ERROR_MESSAGE();
END CATCH
PRINT '';

-- =====================================================================
-- STEP 5: Test Assignment Submission Notification
-- =====================================================================
PRINT 'STEP 5: Test Assignment Submission Notification';
PRINT '----------------------------------------------------------------------';

BEGIN TRY
    -- Get an assignment lesson
    SELECT TOP 1 @TestLessonID = LessonID
    FROM dbo.SIM_Lessons
    WHERE IsDeleted = 0 AND LessonType = 'ASSIGNMENT';

    IF @TestLessonID IS NULL
    BEGIN
        PRINT 'WARNING: No assignment lesson found. Skipping assignment submission test.';
    END
    ELSE
    BEGIN
        PRINT 'Assignment Lesson ID: ' + CAST(@TestLessonID AS NVARCHAR(50));

        -- Submit assignment
        EXEC dbo.LMS_AssignmentSubmission_Create
            @LessonID = @TestLessonID,
            @StudentUserID = @TestStudentID,
            @SubmissionText = N'Nội dung bài làm test',
            @FileUrl = NULL,
            @OriginalFileName = NULL,
            @StoredFileName = NULL,
            @FileSize = NULL,
            @MimeType = NULL,
            @SubmittedAt = GETUTCDATE(),
            @CreatedByUserID = @ActorID;

        PRINT 'Assignment submitted.';

        -- Check for notifications to teacher
        SELECT TOP 5 
            NotificationID,
            UserID,
            Title,
            Message,
            NotificationType,
            CreatedAt
        FROM dbo.SIM_Notifications
        WHERE UserID = @TestTeacherID
          AND NotificationType = 'ASSIGNMENT_SUBMITTED'
        ORDER BY CreatedAt DESC;

        IF @@ROWCOUNT > 0
            PRINT 'SUCCESS: Assignment submission notification found.';
        ELSE
            PRINT 'INFO: No assignment submission notification found.';
    END
END TRY
BEGIN CATCH
    PRINT 'ERROR: ' + ERROR_MESSAGE();
END CATCH
PRINT '';

-- =====================================================================
-- STEP 6: Test Assignment Grading Notification
-- =====================================================================
PRINT 'STEP 6: Test Assignment Grading Notification';
PRINT '----------------------------------------------------------------------';

BEGIN TRY
    -- Grade the assignment
    EXEC dbo.LMS_AssignmentSubmission_Grade
        @LessonID = @TestLessonID,
        @StudentUserID = @TestStudentID,
        @Score = 90,
        @Feedback = N'Bài làm tốt!',
        @GradedByUserID = @TestTeacherID,
        @GradedAt = GETUTCDATE();

    PRINT 'Assignment graded.';

    -- Check for notifications to student
    SELECT TOP 5 
        NotificationID,
        UserID,
        Title,
        Message,
        NotificationType,
        CreatedAt
    FROM dbo.SIM_Notifications
    WHERE UserID = @TestStudentID
      AND NotificationType = 'ASSIGNMENT_GRADED'
    ORDER BY CreatedAt DESC;

    IF @@ROWCOUNT > 0
        PRINT 'SUCCESS: Assignment grading notification found.';
    ELSE
        PRINT 'INFO: No assignment grading notification found.';
END TRY
BEGIN CATCH
    PRINT 'ERROR: ' + ERROR_MESSAGE();
END CATCH
PRINT '';

-- =====================================================================
-- STEP 7: Test Notification Reading
-- =====================================================================
PRINT 'STEP 7: Test Notification Reading';
PRINT '----------------------------------------------------------------------';

BEGIN TRY
    -- Mark notifications as read
    EXEC dbo.SIM_Notification_MarkRead
        @UserID = @TestStudentID,
        @NotificationID = NULL; -- Mark all as read

    PRINT 'Notifications marked as read.';

    -- Verify notifications are read
    SELECT 
        COUNT(*) AS TotalNotifications,
        SUM(CASE WHEN IsRead = 1 THEN 1 ELSE 0 END) AS ReadNotifications
    FROM dbo.SIM_Notifications
    WHERE UserID = @TestStudentID;
END TRY
BEGIN CATCH
    PRINT 'ERROR: ' + ERROR_MESSAGE();
END CATCH
PRINT '';

-- =====================================================================
-- SUMMARY
-- =====================================================================
PRINT '=====================================================================';
PRINT 'Test Summary';
PRINT '=====================================================================';
PRINT 'Test Course ID: ' + ISNULL(CAST(@TestCourseID AS NVARCHAR(50)), 'NULL');
PRINT 'Test Student ID: ' + ISNULL(CAST(@TestStudentID AS NVARCHAR(50)), 'NULL');
PRINT 'Test Teacher ID: ' + ISNULL(CAST(@TestTeacherID AS NVARCHAR(50)), 'NULL');
PRINT 'Test Quiz ID: ' + ISNULL(CAST(@TestQuizID AS NVARCHAR(50)), 'NULL');
PRINT 'Test Question ID: ' + ISNULL(CAST(@TestQuestionID AS NVARCHAR(50)), 'NULL');
PRINT '';

