PRINT 'All notifications for test student:';
SELECT 
    NotificationID,
    Title,
    Message,
    NotificationType,
    IsRead,
    CreatedAt
FROM dbo.SIM_Notifications
WHERE UserID = @TestStudentID
ORDER BY CreatedAt DESC;
