        PRINT 'SUCCESS: Enrollment notification found.';
    ELSE
        PRINT 'INFO: No enrollment notification found (may need to check procedure implementation).';
END TRY
BEGIN CATCH
    PRINT 'ERROR: ' + ERROR_MESSAGE();
END CATCH
PRINT '';

-- =====================================================================
-- STEP 2: Test Quiz Creation Notification
-- =====================================================================
PRINT 'STEP 2: Test Quiz Creation Notification';
PRINT '----------------------------------------------------------------------';

BEGIN TRY
    -- Get a lesson for the quiz
    SELECT TOP 1 @TestLessonID = LessonID
    FROM dbo.SIM_Lessons
    WHERE IsDeleted = 0 AND LessonType = 'QUIZ';

    IF @TestLessonID IS NULL
    BEGIN
        PRINT 'WARNING: No quiz lesson found. Skipping quiz creation test.';
    END
    ELSE
    BEGIN
        PRINT 'Test Lesson ID: ' + CAST(@TestLessonID AS NVARCHAR(50));

        -- Create a quiz
        EXEC dbo.LMS_Quiz_Create
            @LessonId = @TestLessonID,
            @Title = N'Quiz Test Thông Báo',
            @Description = N'Mô tả quiz test',
            @PassingScore = 70,
            @MaxAttempts = 3,
            @TimeLimitMinutes = 30,
            @RandomizeQuestions = 0,
            @ShowResultsImmediately = 1,
            @Status = 'ACTIVE',
            @ActorId = @ActorID,
            @CreatedUser = 'test';

        SET @TestQuizID = SCOPE_IDENTITY();
        PRINT 'Quiz created. ID: ' + CAST(@TestQuizID AS NVARCHAR(50));

        -- Create a quiz question (which also creates the question)
        EXEC dbo.LMS_QuizQuestion_Create
            @QuizId = @TestQuizID,
            @QuestionText = N'Câu hỏi test quiz?',
            @QuestionType = 'SINGLE_CHOICE',
            @Points = 10,
            @Option1 = N'Đáp án A',
            @Option2 = N'Đáp án B',
            @Option3 = N'Đáp án C',
            @Option4 = N'Đáp án D',
            @CorrectOption = 1,
            @Explanation = N'Giải thích',
            @SortOrder = 1,
            @ActorId = @ActorID,
            @CreatedUser = 'test';

        PRINT 'Quiz question created.';

        -- Check for notifications
        SELECT TOP 5 
            NotificationID,
            UserID,
            Title,
            Message,
            NotificationType,
            CreatedAt
        FROM dbo.SIM_Notifications
        WHERE NotificationType = 'QUIZ'
        ORDER BY CreatedAt DESC;

        IF @@ROWCOUNT > 0
            PRINT 'SUCCESS: Quiz creation notification found.';
        ELSE
            PRINT 'INFO: No quiz creation notification found.';
    END
END TRY
BEGIN CATCH
    PRINT 'ERROR: ' + ERROR_MESSAGE();
END CATCH
PRINT '';

-- =====================================================================
-- STEP 3: Test Quiz Attempt Notification
-- =====================================================================
PRINT 'STEP 3: Test Quiz Attempt Notification';
PRINT '----------------------------------------------------------------------';

BEGIN TRY
    IF @TestQuizID IS NULL
    BEGIN
        PRINT 'WARNING: No quiz ID available. Skipping quiz attempt test.';
    END
    ELSE
    BEGIN
        -- Create a quiz attempt
        EXEC dbo.LMS_QuizAttempt_Create
            @QuizId = @TestQuizID,
            @StudentUserId = @TestStudentID,
            @CreatedUser = 'test';

        PRINT 'Quiz attempt created.';

        -- Check for notifications
        SELECT TOP 5 
            NotificationID,
            UserID,
            Title,
            Message,
            NotificationType,
            CreatedAt
        FROM dbo.SIM_Notifications
        WHERE UserID = @TestStudentID
          AND NotificationType = 'QUIZ'
        ORDER BY CreatedAt DESC;

        IF @@ROWCOUNT > 0
            PRINT 'SUCCESS: Quiz attempt notification found.';
        ELSE
            PRINT 'INFO: No quiz attempt notification found.';
    END
END TRY
BEGIN CATCH
    PRINT 'ERROR: ' + ERROR_MESSAGE();
END CATCH
PRINT '';

-- =====================================================================
-- STEP 4: Test Quiz Completion Notification
-- =====================================================================
PRINT 'STEP 4: Test Quiz Completion Notification';
PRINT '----------------------------------------------------------------------';

BEGIN TRY
    IF @TestQuizID IS NULL
    BEGIN
        PRINT 'WARNING: No quiz ID available. Skipping quiz completion test.';
    END
    ELSE
    BEGIN
        -- Simulate quiz completion by updating the attempt
        -- This would normally be done by the quiz submission procedure
        UPDATE dbo.LMS_QuizAttempts
        SET 
            CompletedAt = GETUTCDATE(),
            Score = 85.5,
            Status = 'COMPLETED',
            Passed = 1
        WHERE QuizID = @TestQuizID
          AND StudentUserID = @TestStudentID
          AND Status = 'IN_PROGRESS';

        PRINT 'Quiz attempt marked as completed.';

        -- Check for notifications
        SELECT TOP 5 
            NotificationID,
            UserID,
            Title,
            Message,
            NotificationType,
            CreatedAt
        FROM dbo.SIM_Notifications
        WHERE UserID = @TestStudentID
          AND NotificationType = 'QUIZ'
        ORDER BY CreatedAt DESC;

        IF @@ROWCOUNT > 0
            PRINT 'SUCCESS: Quiz completion notification found.';
        ELSE
            PRINT 'INFO: No quiz completion notification found.';
    END
END TRY
BEGIN CATCH
    PRINT 'ERROR: ' + ERROR_MESSAGE();
END CATCH
PRINT '';

-- =====================================================================
-- STEP 5: Test Assignment Submission Notification
-- =====================================================================
PRINT 'STEP 5: Test Assignment Submission Notification';
PRINT '----------------------------------------------------------------------';

BEGIN TRY
    -- Get an assignment lesson
    SELECT TOP 1 @TestLessonID = LessonID
    FROM dbo.SIM_Lessons
    WHERE IsDeleted = 0 AND LessonType = 'ASSIGNMENT';

    IF @TestLessonID IS NULL
    BEGIN
