PRINT '----------------------------------------------------------------------';

BEGIN TRY
    -- Grade the assignment
    DECLARE @AssignmentSubmissionID BIGINT;

    -- Get the assignment submission ID
    SELECT TOP 1 @AssignmentSubmissionID = AssignmentSubmissionID
    FROM dbo.LMS_AssignmentSubmissions
    WHERE LessonID = @TestLessonID
      AND StudentUserID = @TestStudentID
      AND SubmissionStatus = 'SUBMITTED';

    IF @AssignmentSubmissionID IS NULL
    BEGIN
        PRINT 'WARNING: No assignment submission found to grade.';
    END
    ELSE
    BEGIN
        EXEC dbo.LMS_AssignmentSubmission_Grade
