        PRINT 'Assignment graded.';

        -- Check for notifications to student
        SELECT TOP 5 
            NotificationID,
            UserID,
            Title,
            Message,
            NotificationType,
            CreatedAt
        FROM dbo.SIM_Notifications
        WHERE UserID = @TestStudentID
          AND NotificationType = 'ASSIGNMENT'
