PRINT 'Test Student ID: ' + ISNULL(CAST(@TestStudentID AS NVARCHAR(50)), 'NULL');
PRINT 'Test Teacher ID: ' + ISNULL(CAST(@TestTeacherID AS NVARCHAR(50)), 'NULL');
PRINT 'Test Quiz ID: ' + ISNULL(CAST(@TestQuizID AS NVARCHAR(50)), 'NULL');
PRINT 'Test Question ID: ' + ISNULL(CAST(@TestQuestionID AS NVARCHAR(50)), 'NULL');
