    @ShuffleQuestions Bit = 0,
    @Status Varchar(30),
    @ActorId Bigint,
    @CreatedUser NVARCHAR(100) = NULL
As
Begin
    Set Nocount On;

    If Nullif(Ltrim(Rtrim(@Title)), '') Is Null
        Or @PassingScore < 0
        Or @PassingScore > 100
        Or @MaxAttempts < 0
        Throw 50001, N'Dữ liệu bài kiểm tra không hợp lệ.', 1;

    If Not Exists
        (
            Select
                1
            From dbo.SIM_Lessons l
                Inner Join dbo.SIM_Courses c On c.CourseID = l.CourseId
            Where (l.LessonID = @LessonId)
                And (l.IsDeleted = 0)
                And (l.LessonType = 'QUIZ')
                And (c.TeacherUserID = @ActorId)
        )
        Throw 50003, N'Bạn không có quyền tạo bài kiểm tra cho bài học này.', 1;

    Insert dbo.LMS_Quizzes
    (
        LessonID,
        Title,
        Description,
        PassingScore,
        MaxAttempts,
        TimeLimitMinutes,
        ShuffleQuestions,
        Status,
        CreatedByUserID,
        CreatedAt,
        UpdatedAt
    )
    Values
    (
        @LessonId,
        @Title,
        @Description,
        @PassingScore,
        @MaxAttempts,
        @TimeLimitMinutes,
        @ShuffleQuestions,
        @Status,
        @ActorId,
        Sysutcdatetime(),
        Sysutcdatetime()
    );

    Declare @QuizId Bigint = Scope_identity();

    Insert dbo.AuditLogs
    (
        UserId,
        Action,
        Module,
        EntityName,
        EntityId
    )
    Values
    (
        @ActorId,
        'CREATE',
        'QUIZ',
        'Quiz',
        Convert(Nvarchar(100), @QuizId)
    );

    Select
        @QuizId;
End

