DECLARE @QuizAttemptID BIGINT;
SELECT @QuizAttemptID = QuizAttemptID FROM dbo.LMS_QuizAttempts WHERE QuizID = (SELECT QuizID FROM dbo.LMS_Quizzes WHERE LessonID = (SELECT LessonID FROM dbo.SIM_Lessons WHERE Title = 'Lesson Quiz Test'));

-- Xem chi tiết QuizAttempt
SELECT
    qa.QuizAttemptID,
    q.Title AS QuizTitle,
    u.FullName AS StudentName,
    qa.AttemptStatus,
    qa.Score,
    qa.MaxScore,
    qa.ScorePercent,
    qa.Passed,
    qa.StartedAt,
    qa.SubmittedAt
FROM dbo.LMS_QuizAttempts qa
INNER JOIN dbo.LMS_Quizzes q ON qa.QuizID = q.QuizID
INNER JOIN dbo.Users u ON qa.StudentUserID = u.Id
WHERE qa.QuizAttemptID = @QuizAttemptID;

-- Xem chi tiết câu trả lời
SELECT
    qq.SortOrder,
    q.QuestionText,
    qaa.AnswerText,
    qaa.IsCorrect,
    qaa.ScoreAwarded
FROM dbo.LMS_QuizQuestions qq
INNER JOIN dbo.LMS_Questions q ON qq.QuestionID = q.QuestionID
INNER JOIN dbo.LMS_QuizAttemptAnswers qaa ON qaa.QuizAttemptID = @QuizAttemptID AND qaa.QuestionID = q.QuestionID
WHERE qq.QuizID = (SELECT QuizID FROM dbo.LMS_Quizzes WHERE LessonID = (SELECT LessonID FROM dbo.SIM_Lessons WHERE Title = 'Lesson Quiz Test'))
ORDER BY qq.SortOrder;
GO

