SELECT @StudentID = Id FROM dbo.Users WHERE Username = 'student';

PRINT 'TeacherID: ' + CAST(@TeacherID AS NVARCHAR(50));
PRINT 'StudentID: ' + CAST(@StudentID AS NVARCHAR(50));

-- Lấy Course có sẵn
SELECT TOP 1 @CourseID = CourseID FROM dbo.SIM_Courses WHERE Status = 'PUBLISHED';
IF @CourseID IS NULL
BEGIN
    PRINT 'KHÔNG TÌM THẤY COURSE PUBLISHED!';
    SET @CourseID = 1; -- Fallback
END
PRINT 'CourseID: ' + CAST(@CourseID AS NVARCHAR(50));

-- Lấy Lesson có sẵn
SELECT TOP 1 @LessonID = LessonID FROM dbo.SIM_Lessons WHERE CourseId = @CourseID;
IF @LessonID IS NULL
BEGIN
    PRINT 'KHÔNG TÌM THẤY LESSON CHO COURSE NÀY!';
