-- ============================================
-- BƯỚC 2: TẠO QUIZ
-- ============================================
PRINT '--- Bước 2: Tạo Quiz ---';

DECLARE @QuizID BIGINT;
DECLARE @LessonID BIGINT;
DECLARE @TeacherID BIGINT;

SELECT @LessonID = LessonID FROM dbo.SIM_Lessons WHERE LessonID = (SELECT TOP 1 LessonID FROM dbo.SIM_Lessons);
SELECT @TeacherID = Id FROM dbo.Users WHERE Username = 'teacher';

-- Xóa quiz cũ nếu có (để test sạch)
IF EXISTS (SELECT 1 FROM dbo.LMS_Quizzes WHERE LessonID = @LessonID AND Title LIKE 'Quiz Test%')
BEGIN
    DELETE FROM dbo.LMS_QuizQuestions WHERE QuizID IN (SELECT QuizID FROM dbo.LMS_Quizzes WHERE LessonID = @LessonID AND Title LIKE 'Quiz Test%');
    DELETE FROM dbo.LMS_Quizzes WHERE LessonID = @LessonID AND Title LIKE 'Quiz Test%';
    PRINT 'Đã xóa Quiz cũ';
