    VALUES
    (
        @LessonID,
        'Quiz Test - Cơ bản',
        'Đây là quiz test cho flow mới',
        'PUBLISHED',
        70,
        3,
        30,
        1,
        @TeacherID,
        GETUTCDATE(),
        GETUTCDATE()
    );

    SET @QuizID = SCOPE_IDENTITY();
    PRINT 'Đã tạo Quiz thành công - QuizID: ' + CAST(@QuizID AS NVARCHAR(50));
