-- ============================================
-- BƯỚC 9: KIỂM TRA KẾT QUẢ
-- ============================================
PRINT '--- Bước 9: Kiểm tra kết quả ---';

SELECT 
    qa.QuizAttemptID,
    q.Title AS QuizTitle,
    u.FullName AS StudentName,
    qa.Score,
    qa.TotalScore,
    qa.Status,
    qa.StartedAt,
    qa.SubmittedAt
FROM dbo.LMS_QuizAttempts qa
INNER JOIN dbo.LMS_Quizzes q ON qa.QuizID = q.QuizID
INNER JOIN dbo.Users u ON qa.StudentUserID = u.Id
WHERE q.Title = 'Quiz Test - Cơ bản'
ORDER BY qa.QuizAttemptID DESC;

PRINT '========================================';
PRINT 'HOÀN THÀNH TEST LUỒNG QUIZ';
PRINT '========================================';
GO

