-- ============================================
-- BƯỚC 8: SUBMIT QUIZ VÀ TÍNH ĐIỂM
-- ============================================
PRINT '--- Bước 8: Submit Quiz ---';

DECLARE @QuizAttemptID BIGINT;
DECLARE @StudentID BIGINT;
DECLARE @QuizID BIGINT;
DECLARE @TotalScore DECIMAL(8,2);
DECLARE @MaxScore DECIMAL(8,2);
DECLARE @ScorePercent DECIMAL(5,2);
DECLARE @PassingScore DECIMAL(5,2);
DECLARE @Passed BIT;

SELECT @QuizAttemptID = QuizAttemptID FROM dbo.LMS_QuizAttempts WHERE QuizID = (SELECT QuizID FROM dbo.LMS_Quizzes WHERE Title = 'Quiz Test - Cơ bản');
SELECT @StudentID = Id FROM dbo.Users WHERE Username = 'student';
SELECT @QuizID = QuizID FROM dbo.LMS_Quizzes WHERE Title = 'Quiz Test - Cơ bản';
SELECT @PassingScore = PassingScore FROM dbo.LMS_Quizzes WHERE QuizID = @QuizID;

-- Tính điểm từ QuizAttemptAnswers
SELECT @TotalScore = SUM(ScoreAwarded) FROM dbo.LMS_QuizAttemptAnswers WHERE QuizAttemptID = @QuizAttemptID;
SELECT @MaxScore = SUM(Score) FROM dbo.LMS_QuizQuestions WHERE QuizID = @QuizID;

SET @ScorePercent = CASE WHEN @MaxScore > 0 THEN (@TotalScore * 100.0 / @MaxScore) ELSE 0 END;
SET @Passed = CASE WHEN @ScorePercent >= @PassingScore THEN 1 ELSE 0 END;

PRINT 'Total Score: ' + CAST(@TotalScore AS NVARCHAR(50));
PRINT 'Max Score: ' + CAST(@MaxScore AS NVARCHAR(50));
PRINT 'Score Percent: ' + CAST(@ScorePercent AS NVARCHAR(50));
PRINT 'Passed: ' + CAST(@Passed AS NVARCHAR(50));

-- Update QuizAttempt - Submit
BEGIN TRY
    UPDATE dbo.LMS_QuizAttempts
    SET
        Score = @TotalScore,
        MaxScore = @MaxScore,
        ScorePercent = @ScorePercent,
        Passed = @Passed,
        AttemptStatus = 'SUBMITTED',
        SubmittedAt = GETUTCDATE()
    WHERE QuizAttemptID = @QuizAttemptID;
    PRINT 'Đã submit QuizAttempt thành công';
END TRY
BEGIN CATCH
    PRINT 'Lỗi khi submit QuizAttempt: ' + ERROR_MESSAGE();
END CATCH
GO

