input.contents:
-- =====================================================================
-- STORED PROCEDURE: LMS_QuizAttempt_Submit_Mixed
-- Submit bài kiểm tra và chấm tự động trắc nghiệm, để tự luận chờ chấm thủ công
-- =====================================================================
-- Chức năng:
-- 1. Nhận câu trả lời từ học sinh
-- 2. Tự động chấm các câu trắc nghiệm (SINGLE_CHOICE, MULTIPLE_CHOICE, TRUE_FALSE)
-- 3. Đánh dấu câu tự luận (ESSAY) là PENDING_MANUAL
-- 4. Tính điểm tự động (chỉ trắc nghiệm)
-- 5. Trạng thái tổng thể: SUBMITTED nếu không có tự luận, PENDING_GRADING nếu có
-- =====================================================================

IF EXISTS (SELECT 1 FROM sys.procedures WHERE name = 'LMS_QuizAttempt_Submit_Mixed')
    DROP PROCEDURE dbo.LMS_QuizAttempt_Submit_Mixed;
GO

CREATE PROCEDURE dbo.LMS_QuizAttempt_Submit_Mixed
    @QuizAttemptID BIGINT,
    @StudentUserID BIGINT,
    @AnswersJson NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @QuizID BIGINT;
    DECLARE @LessonID BIGINT;
    DECLARE @CourseID BIGINT;
    DECLARE @PassingScore DECIMAL(5, 2);
    DECLARE @TimeLimitMinutes INT;
    DECLARE @StartedAt DATETIME2;
    DECLARE @TeacherID BIGINT;
    DECLARE @AutoGradeMultipleChoice BIT;
    DECLARE @AllowShowScoreBeforeManualGrading BIT;

    -- Lấy thông tin Quiz
    SELECT
        @QuizID = qa.QuizID,
        @LessonID = q.LessonID,
        @CourseID = (SELECT CourseId FROM dbo.SIM_Lessons WHERE LessonID = q.LessonID),
        @PassingScore = q.PassingScore,
        @TimeLimitMinutes = q.TimeLimitMinutes,
        @StartedAt = qa.StartedAt,
        @TeacherID = (SELECT TeacherUserID FROM dbo.SIM_Courses WHERE CourseID = (SELECT CourseId FROM dbo.SIM_Lessons WHERE LessonID = q.LessonID)),
        @AutoGradeMultipleChoice = ISNULL(q.AutoGradeMultipleChoice, 1),
        @AllowShowScoreBeforeManualGrading = ISNULL(q.AllowShowScoreBeforeManualGrading, 0)
    FROM dbo.LMS_QuizAttempts qa
    INNER JOIN dbo.LMS_Quizzes q ON q.QuizID = qa.QuizID
    WHERE qa.QuizAttemptID = @QuizAttemptID
        AND qa.StudentUserID = @StudentUserID
        AND qa.AttemptStatus = 'IN_PROGRESS';

    IF @QuizID IS NULL
        THROW 50002, N'Lượt làm bài không tồn tại hoặc đã được nộp.', 1;

    -- Kiểm tra thời gian
    IF @TimeLimitMinutes IS NOT NULL AND DATEADD(SECOND, 15, DATEADD(MINUTE, @TimeLimitMinutes, @StartedAt)) < SYSUTCDATETIME()
        THROW 50004, N'Lượt làm bài đã hết thời gian.', 1;

    -- Parse JSON answers
    CREATE TABLE #tblAnswer
    (
        QuestionID BIGINT NOT NULL PRIMARY KEY,
        AnswerText NVARCHAR(MAX) NULL
    );

    INSERT #tblAnswer(QuestionID, AnswerText)
    SELECT
        QuestionID,
        LTRIM(RTRIM(AnswerText))
    FROM OPENJSON(COALESCE(@AnswersJson, N'[]'))
    WITH
    (
        QuestionID BIGINT '$.questionId',
        AnswerText NVARCHAR(MAX) '$.answerText'
    );

    -- Validate answers
    IF EXISTS (
        SELECT 1 FROM #tblAnswer 
        WHERE NOT EXISTS (
            SELECT 1 FROM dbo.LMS_QuizQuestionAssignments 
            WHERE QuizAttemptID = @QuizAttemptID 
            AND QuestionID = #tblAnswer.QuestionID
        )
    )
    THROW 50001, N'Câu trả lời không thuộc bài kiểm tra.', 1;

    BEGIN TRANSACTION;

    -- Insert câu trả lời với auto-grading
    INSERT dbo.LMS_QuizAttemptAnswers
    (
        QuizAttemptID, QuestionID, AnswerText, IsCorrect, ScoreAwarded, GradingStatus
    )
    SELECT
        @QuizAttemptID,
        aqa.QuestionID,
        ISNULL(ta.AnswerText, ''),
        -- Auto-grade logic
        CASE
            WHEN @AutoGradeMultipleChoice = 1 AND aqa.QuestionType IN ('SINGLE_CHOICE', 'TRUE_FALSE', 'MULTIPLE_CHOICE')
                THEN CASE
                    WHEN LTRIM(RTRIM(ta.AnswerText)) = LTRIM(RTRIM(CAST(aqa.CorrectOption AS NVARCHAR(10))))
                        THEN 1
                    ELSE 0
                   END
            WHEN @AutoGradeMultipleChoice = 1 AND aqa.QuestionType = 'SHORT_ANSWER'
                THEN CASE
                    WHEN UPPER(LTRIM(RTRIM(aqa.CorrectAnswerText))) = UPPER(LTRIM(RTRIM(ta.AnswerText)))
                        THEN 1
                    ELSE 0
                   END
            ELSE NULL  -- Essay: chờ chấm thủ công
        END AS IsCorrect,
        -- Score calculation
        CASE
            WHEN @AutoGradeMultipleChoice = 1 AND aqa.QuestionType IN ('SINGLE_CHOICE', 'TRUE_FALSE', 'MULTIPLE_CHOICE', 'SHORT_ANSWER')
                THEN CASE
                    WHEN LTRIM(RTRIM(ta.AnswerText)) = LTRIM(RTRIM(CAST(aqa.CorrectOption AS NVARCHAR(10))))
                        OR (@AutoGradeMultipleChoice = 1 AND aqa.QuestionType = 'SHORT_ANSWER' 
                            AND UPPER(LTRIM(RTRIM(aqa.CorrectAnswerText))) = UPPER(LTRIM(RTRIM(ta.AnswerText))))
                        THEN aqa.Points
                    ELSE 0
                   END
            ELSE NULL  -- Essay: điểm sẽ chấm sau
        END AS ScoreAwarded,
        -- Grading status
        CASE
            WHEN aqa.QuestionType = 'ESSAY' THEN 'PENDING_MANUAL'
            WHEN aqa.QuestionType IN ('SINGLE_CHOICE', 'TRUE_FALSE', 'MULTIPLE_CHOICE', 'SHORT_ANSWER') AND @AutoGradeMultipleChoice = 1
                THEN 'AUTO_GRADED'
            ELSE 'PENDING_MANUAL'
        END AS GradingStatus
    FROM dbo.LMS_QuizQuestionAssignments aqa
    LEFT JOIN #tblAnswer ta ON ta.QuestionID = aqa.QuestionID
    WHERE aqa.QuizAttemptID = @QuizAttemptID;

    -- Tính điểm
    DECLARE @AutoScore DECIMAL(8, 2) = (SELECT COALESCE(SUM(ScoreAwarded), 0) FROM dbo.LMS_QuizAttemptAnswers WHERE QuizAttemptID = @QuizAttemptID AND GradingStatus = 'AUTO_GRADED');
    DECLARE @ManualScore DECIMAL(8, 2) = (SELECT COALESCE(SUM(ManualScore), 0) FROM dbo.LMS_QuizAttemptAnswers WHERE QuizAttemptID = @QuizAttemptID AND GradingStatus = 'MANUALLY_GRADED');
    DECLARE @MaxScore DECIMAL(8, 2) = (SELECT COALESCE(SUM(Points), 0) FROM dbo.LMS_QuizQuestionAssignments WHERE QuizAttemptID = @QuizAttemptID);
    DECLARE @TotalScore DECIMAL(8, 2) = @AutoScore + @ManualScore;
    DECLARE @ScorePercent DECIMAL(5, 2) = CONVERT(DECIMAL(5, 2), @TotalScore * 100.0 / NULLIF(@MaxScore, 0));

    -- Kiểm tra xem có câu tự luận cần chấm không
    DECLARE @HasPendingManual BIT = CASE WHEN EXISTS (
        SELECT 1 FROM dbo.LMS_QuizAttemptAnswers 
        WHERE QuizAttemptID = @QuizAttemptID 
        AND GradingStatus = 'PENDING_MANUAL'
    ) THEN 1 ELSE 0 END;

    -- Xác định trạng thái tổng thể
    DECLARE @AttemptStatus VARCHAR(30);
    DECLARE @Passed BIT = NULL;

    IF @HasPendingManual = 1
    BEGIN
        SET @AttemptStatus = 'PENDING_GRADING';
        -- Nếu cho phép xem điểm trước khi chấm xong
        IF @AllowShowScoreBeforeManualGrading = 1
        BEGIN
            SET @Passed = CASE WHEN @ScorePercent >= @PassingScore THEN 1 ELSE 0 END;
        END
    END
    ELSE
    BEGIN
        SET @AttemptStatus = 'SUBMITTED';
        SET @Passed = CASE WHEN @ScorePercent >= @PassingScore THEN 1 ELSE 0 END;
    END

    -- Update QuizAttempt
    UPDATE dbo.LMS_QuizAttempts
    SET
        SubmittedAt = SYSUTCDATETIME(),
        Score = @TotalScore,
        AutoScore = @AutoScore,
        ManualScore = @ManualScore,
        MaxScore = @MaxScore,
        ScorePercent = @ScorePercent,
        Passed = @Passed,
        AttemptStatus = @AttemptStatus,
        TotalQuestions = (SELECT COUNT(*) FROM dbo.LMS_QuizQuestionAssignments WHERE QuizAttemptID = @QuizAttemptID),
        AutoGradedCount = (SELECT COUNT(*) FROM dbo.LMS_QuizAttemptAnswers WHERE QuizAttemptID = @QuizAttemptID AND GradingStatus = 'AUTO_GRADED'),
        ManualGradedCount = (SELECT COUNT(*) FROM dbo.LMS_QuizAttemptAnswers WHERE QuizAttemptID = @QuizAttemptID AND GradingStatus = 'MANUALLY_GRADED'),
        PendingManualCount = (SELECT COUNT(*) FROM dbo.LMS_QuizAttemptAnswers WHERE QuizAttemptID = @QuizAttemptID AND GradingStatus = 'PENDING_MANUAL')
    WHERE QuizAttemptID = @QuizAttemptID;

    -- Update Lesson Progress
    MERGE dbo.SIM_StudentLessonProgress AS Target
    USING (SELECT @StudentUserID StudentUserID, @CourseID CourseID, @LessonID LessonID) AS Source
        ON Target.StudentUserID = Source.StudentUserID AND Target.LessonID = Source.LessonID
    WHEN MATCHED THEN
        UPDATE SET 
            Score = @ScorePercent, 
            AttemptCount = Target.AttemptCount + 1, 
            ProgressPercent = CASE WHEN @AttemptStatus = 'SUBMITTED' THEN 100 ELSE Target.ProgressPercent END,
            Completed = CASE WHEN @AttemptStatus = 'SUBMITTED' THEN 1 ELSE Target.Completed END,
            CompletedAt = CASE WHEN @AttemptStatus = 'SUBMITTED' THEN COALESCE(Target.CompletedAt, SYSUTCDATETIME()) ELSE Target.CompletedAt END,
            LastAccessAt = SYSUTCDATETIME(), 
            UpdatedAt = SYSUTCDATETIME()
    WHEN NOT MATCHED THEN
        INSERT (StudentUserID, CourseID, LessonID, ProgressPercent, Score, AttemptCount, Completed, CompletedAt, LastAccessAt, ActiveStudySeconds)
        VALUES (Source.StudentUserID, Source.CourseID, Source.LessonID, 
                CASE WHEN @AttemptStatus = 'SUBMITTED' THEN 100 ELSE 0 END, 
                @ScorePercent, 1, 
                CASE WHEN @AttemptStatus = 'SUBMITTED' THEN 1 ELSE 0 END, 
                CASE WHEN @AttemptStatus = 'SUBMITTED' THEN SYSUTCDATETIME() ELSE NULL END, 
                SYSUTCDATETIME(), 0);

    -- Notification to teacher
    IF @TeacherID IS NOT NULL
    BEGIN
        INSERT dbo.SIM_Notifications
        (
            UserID, Title, Message, NotificationType, EntityType, EntityID, CreatedAt, CreatedUser
        )
        SELECT
            @TeacherID,
            CASE WHEN @HasPendingManual = 1 THEN N'Học sinh nộp bài - Chờ chấm tự luận' ELSE N'Học sinh nộp bài kiểm tra' END,
            CONCAT(
                N'Học sinh ', u.FullName, 
                CASE WHEN @HasPendingManual = 1 THEN N' đã nộp bài - Có câu tự luận cần chấm.' ELSE N' đã nộp bài kiểm tra.' END,
                N' Điểm trắc nghiệm: ', @AutoScore, N'/', @MaxScore
            ),
            'QUIZ',
            'QUIZ_ATTEMPT',
            @QuizAttemptID,
            SYSUTCDATETIME(),
            CONVERT(NVARCHAR(100), @StudentUserID)
        FROM dbo.SYS_Users u
        WHERE u.UserID = @StudentUserID;
    END

    COMMIT TRANSACTION;

    -- Audit log
    INSERT dbo.AuditLogs (UserId, Action, Module, EntityName, EntityId)
    VALUES (@StudentUserID, 'SUBMIT', 'QUIZ', 'QuizAttempt', CONVERT(NVARCHAR(100), @QuizAttemptID));

    -- Return result
    SELECT
        @QuizAttemptID QuizAttemptID,
        @TotalScore Score,
        @AutoScore AutoScore,
        @ManualScore ManualScore,
        @MaxScore MaxScore,
        @ScorePercent ScorePercent,
        @Passed Passed,
        @AttemptStatus AttemptStatus,
        @HasPendingManual HasPendingManual,
        (SELECT COUNT(*) FROM dbo.LMS_QuizAttemptAnswers WHERE QuizAttemptID = @QuizAttemptID AND GradingStatus = 'PENDING_MANUAL') PendingManualCount;

    PRINT 'Đã nộp bài kiểm tra: ' + CAST(@QuizAttemptID AS NVARCHAR(20));
    IF @HasPendingManual = 1
        PRINT 'Có câu tự luận cần chấm thủ công.';
END
GO

PRINT '========================================';
PRINT 'Đã tạo SP: LMS_QuizAttempt_Submit_Mixed';
PRINT '========================================';
GO

-- =====================================================================
-- STORED PROCEDURE: LMS_QuizAttempt_GradeEssay
-- Giáo viên chấm câu tự luận cho một lượt làm bài
-- =====================================================================
-- Chức năng:
-- 1. Giáo viên chấm điểm cho từng câu tự luận
-- 2. Có thể thêm nhận xét
-- 3. Cập nhật trạng thái thành MANUALLY_GRADED
-- 4. Tính lại tổng điểm
-- 5. Có thể override điểm tự động (nếu được phân quyền)
-- =====================================================================

IF EXISTS (SELECT 1 FROM sys.procedures WHERE name = 'LMS_QuizAttempt_GradeEssay')
    DROP PROCEDURE dbo.LMS_QuizAttempt_GradeEssay;
GO

CREATE PROCEDURE dbo.LMS_QuizAttempt_GradeEssay
    @QuizAttemptID BIGINT,
    @QuestionID BIGINT,
    @ManualScore DECIMAL(8, 2),
    @TeacherComment NVARCHAR(MAX) = NULL,
    @TeacherUserID BIGINT,
    @OverrideAutoScore BIT = 0  -- Cho phép sửa điểm trắc nghiệm
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @QuizID BIGINT;
    DECLARE @StudentUserID BIGINT;
    DECLARE @TeacherID BIGINT;
    DECLARE @MaxPointsForQuestion DECIMAL(8, 2);
    DECLARE @QuestionType VARCHAR(50);
    DECLARE @PassingScore DECIMAL(5, 2);
    DECLARE @GlobalMaxScore DECIMAL(8, 2);

    -- Validate QuizAttempt
    SELECT
        @QuizID = qa.QuizID,
        @StudentUserID = qa.StudentUserID,
        @TeacherID = c.TeacherUserID,
        @PassingScore = q.PassingScore,
        @GlobalMaxScore = q.GlobalMaxScore
    FROM dbo.LMS_QuizAttempts qa
    INNER JOIN dbo.LMS_Quizzes q ON q.QuizID = qa.QuizID
    INNER JOIN dbo.SIM_Lessons l ON l.LessonID = q.LessonID
    INNER JOIN dbo.SIM_Courses c ON c.CourseID = l.CourseId
    WHERE qa.QuizAttemptID = @QuizAttemptID;

    IF @QuizID IS NULL
        THROW 50001, N'Lượt làm bài không tồn tại.', 1;

    -- Kiểm tra quyền: chỉ giáo viên của khóa học được chấm
    IF @TeacherID != @TeacherUserID
        THROW 50003, N'Bạn không có quyền chấm bài kiểm tra này.', 1;

    -- Lấy thông tin câu hỏi
    SELECT
        @MaxPointsForQuestion = aqa.Points,
        @QuestionType = aqa.QuestionType
    FROM dbo.LMS_QuizQuestionAssignments aqa
    WHERE aqa.QuizAttemptID = @QuizAttemptID
        AND aqa.QuestionID = @QuestionID;

    IF @MaxPointsForQuestion IS NULL
        THROW 50002, N'Câu hỏi không thuộc bài kiểm tra này.', 1;

    -- Validate điểm
    IF @ManualScore < 0 OR @ManualScore > @MaxPointsForQuestion
        THROW 50004, N'Điểm không hợp lệ. Phải từ 0 đến ' + CAST(@MaxPointsForQuestion AS NVARCHAR(10)), 1;

    -- Kiểm tra xem có phải câu tự luận không
    IF @QuestionType IN ('SINGLE_CHOICE', 'MULTIPLE_CHOICE', 'TRUE_FALSE') AND @OverrideAutoScore = 0
        THROW 50005, N'Câu trắc nghiệm đã được chấm tự động. Sử dụng @OverrideAutoScore=1 để sửa điểm.', 1;

    BEGIN TRANSACTION;

    -- Kiểm tra xem câu trả lời đã tồn tại chưa
    IF EXISTS (SELECT 1 FROM dbo.LMS_QuizAttemptAnswers WHERE QuizAttemptID = @QuizAttemptID AND QuestionID = @QuestionID)
    BEGIN
        -- Update existing answer
        DECLARE @OriginalScore DECIMAL(8, 2);
        SELECT @OriginalScore = ScoreAwarded FROM dbo.LMS_QuizAttemptAnswers 
        WHERE QuizAttemptID = @QuizAttemptID AND QuestionID = @QuestionID;

        UPDATE dbo.LMS_QuizAttemptAnswers
        SET
            ManualScore = @ManualScore,
            GradingStatus = 'MANUALLY_GRADED',
            ManualGradedBy = @TeacherUserID,
            ManualGradedAt = SYSUTCDATETIME(),
            TeacherComment = @TeacherComment,
            IsOverridden = CASE WHEN @OverrideAutoScore = 1 AND @QuestionType IN ('SINGLE_CHOICE', 'MULTIPLE_CHOICE', 'TRUE_FALSE') THEN 1 ELSE IsOverridden END,
            OriginalScore = CASE WHEN @OverrideAutoScore = 1 AND @QuestionType IN ('SINGLE_CHOICE', 'MULTIPLE_CHOICE', 'TRUE_FALSE') THEN @OriginalScore ELSE OriginalScore END,
            ScoreAwarded = CASE WHEN @OverrideAutoScore = 1 THEN @ManualScore ELSE ScoreAwarded END
        WHERE QuizAttemptID = @QuizAttemptID AND QuestionID = @QuestionID;
    END
    ELSE
    BEGIN
        -- Insert new answer (chưa có câu trả lời)
        INSERT dbo.LMS_QuizAttemptAnswers
        (
            QuizAttemptID, QuestionID, AnswerText, IsCorrect, ScoreAwarded,
            GradingStatus, ManualScore, ManualGradedBy, ManualGradedAt, TeacherComment
        )
        VALUES
        (
            @QuizAttemptID, @QuestionID, '', NULL, @ManualScore,
            'MANUALLY_GRADED', @ManualScore, @TeacherUserID, SYSUTCDATETIME(), @TeacherComment
        );
    END

    -- Recalculate total score
    DECLARE @NewAutoScore DECIMAL(8, 2) = (SELECT COALESCE(SUM(ScoreAwarded), 0) FROM dbo.LMS_QuizAttemptAnswers WHERE QuizAttemptID = @QuizAttemptID AND GradingStatus = 'AUTO_GRADED');
    DECLARE @NewManualScore DECIMAL(8, 2) = (SELECT COALESCE(SUM(ManualScore), 0) FROM dbo.LMS_QuizAttemptAnswers WHERE QuizAttemptID = @QuizAttemptID AND GradingStatus = 'MANUALLY_GRADED');
    DECLARE @NewTotalScore DECIMAL(8, 2) = @NewAutoScore + @NewManualScore;
    DECLARE @MaxScore DECIMAL(8, 2) = (SELECT COALESCE(SUM(Points), 0) FROM dbo.LMS_QuizQuestionAssignments WHERE QuizAttemptID = @QuizAttemptID);
    DECLARE @NewScorePercent DECIMAL(5, 2) = CONVERT(DECIMAL(5, 2), @NewTotalScore * 100.0 / NULLIF(@MaxScore, 0));
    DECLARE @NewPassed BIT = CASE WHEN @NewScorePercent >= @PassingScore THEN 1 ELSE 0 END;

    -- Kiểm tra xem còn câu nào cần chấm không
    DECLARE @PendingManualCount INT = (SELECT COUNT(*) FROM dbo.LMS_QuizAttemptAnswers WHERE QuizAttemptID = @QuizAttemptID AND GradingStatus = 'PENDING_MANUAL');

    -- Update QuizAttempt
    UPDATE dbo.LMS_QuizAttempts
    SET
        Score = @NewTotalScore,
        AutoScore = @NewAutoScore,
        ManualScore = @NewManualScore,
        ScorePercent = @NewScorePercent,
        Passed = @NewPassed,
        AttemptStatus = CASE WHEN @PendingManualCount = 0 THEN 'SUBMITTED' ELSE 'PENDING_GRADING' END,
        ManualGradedCount = (SELECT COUNT(*) FROM dbo.LMS_QuizAttemptAnswers WHERE QuizAttemptID = @QuizAttemptID AND GradingStatus = 'MANUALLY_GRADED'),
        PendingManualCount = @PendingManualCount,
        UpdatedAt = SYSUTCDATETIME()
    WHERE QuizAttemptID = @QuizAttemptID;

    -- Update Lesson Progress nếu đã chấm xong
    IF @PendingManualCount = 0
    BEGIN
        UPDATE dbo.SIM_StudentLessonProgress
        SET
            Score = @NewScorePercent,
            ProgressPercent = 100,
            Completed = 1,
            CompletedAt = COALESCE(CompletedAt, SYSUTCDATETIME()),
            UpdatedAt = SYSUTCDATETIME()
        WHERE StudentUserID = @StudentUserID
            AND LessonID = (SELECT LessonID FROM dbo.LMS_Quizzes WHERE QuizID = @QuizID);

        -- Notification to student
        INSERT dbo.SIM_Notifications
        (
            UserID, Title, Message, NotificationType, EntityType, EntityID, CreatedAt, CreatedUser
        )
        SELECT
            @StudentUserID,
            N'Bài kiểm tra đã được chấm',
            CONCAT(N'Giáo viên đã chấm xong bài kiểm tra. Điểm của bạn: ', @NewScorePercent, N'%'),
            'QUIZ',
            'QUIZ_ATTEMPT',
            @QuizAttemptID,
            SYSUTCDATETIME(),
            CONVERT(NVARCHAR(100), @TeacherUserID);
    END

    COMMIT TRANSACTION;

    -- Audit log
    INSERT dbo.AuditLogs (UserId, Action, Module, EntityName, EntityId)
    VALUES (@TeacherUserID, 'GRADE', 'QUIZ', 'QuizAttemptAnswer', CONVERT(NVARCHAR(100), @QuestionID));

    -- Return result
    SELECT
        @QuizAttemptID QuizAttemptID,
        @QuestionID QuestionID,
        @ManualScore ScoreAwarded,
        @NewTotalScore TotalScore,
        @NewAutoScore AutoScore,
        @NewManualScore ManualScore,
        @MaxScore MaxScore,
        @NewScorePercent ScorePercent,
        @NewPassed Passed,
        @PendingManualCount PendingManualCount,
        CASE WHEN @PendingManualCount = 0 THEN 'SUBMITTED' ELSE 'PENDING_GRADING' END AttemptStatus;

    PRINT 'Đã chấm câu hỏi ' + CAST(@QuestionID AS NVARCHAR(20)) + ' với điểm: ' + CAST(@ManualScore AS NVARCHAR(10));
END
GO

PRINT '========================================';
PRINT 'Đã tạo SP: LMS_QuizAttempt_GradeEssay';
PRINT '========================================';
GO

