    )
);
DELETE FROM dbo.LMS_QuizQuestionAssignments WHERE QuizAttemptID IN (
    SELECT QuizAttemptID FROM dbo.LMS_QuizAttempts WHERE QuizID IN (
        SELECT QuizID FROM dbo.LMS_Quizzes WHERE Title LIKE 'Test Mixed%'
    )
);
DELETE FROM dbo.LMS_QuizAttempts WHERE QuizID IN (
    SELECT QuizID FROM dbo.LMS_Quizzes WHERE Title LIKE 'Test Mixed%'
);
DELETE FROM dbo.LMS_QuizQuestions WHERE QuizID IN (
    SELECT QuizID FROM dbo.LMS_Quizzes WHERE Title LIKE 'Test Mixed%'
);
DELETE FROM dbo.LMS_Quizzes WHERE Title LIKE 'Test Mixed%';
