        @Explanation = N'Giải thích câu hỏi ' + CAST(@i AS NVARCHAR(10)),
        @Difficulty = 'MEDIUM',
        @DefaultScore = 0.5,
        @Status = 'ACTIVE',
        @ActorId = (SELECT Id FROM dbo.Users WHERE Username = 'teacher_mixed_test');

    SET @i = @i + 1;
END
PRINT 'Đã tạo 35 câu trắc nghiệm';

-- 15 câu tự luận
SET @i = 1;
WHILE @i <= 15
BEGIN
    EXEC dbo.LMS_Question_Create
        @QuestionType = 'ESSAY',
        @QuestionText = N'Test Mixed Question Essay ' + CAST(@i AS NVARCHAR(10)) + N' - Câu hỏi tự luận. Hãy trình bày suy nghĩ của bạn về chủ đề này.',
        @Description = N'Mô tả câu tự luận ' + CAST(@i AS NVARCHAR(10)),
        @Explanation = N'Giải thích câu tự luận ' + CAST(@i AS NVARCHAR(10)),
        @Difficulty = 'HARD',
        @DefaultScore = 1.0,
        @ShortAnswerMode = 'TEXT',
        @Status = 'ACTIVE',
        @ActorId = (SELECT Id FROM dbo.Users WHERE Username = 'teacher_mixed_test');

    SET @i = @i + 1;
END
