-- BƯỚC 3: TẠO QUIZ VỚI CẤU HÌNH NGÂN HÀNG CÂU HỎI
-- ============================================
PRINT '--- Bước 3: Tạo Quiz với cấu hình ngân hàng câu hỏi ---';

DECLARE @QuizID BIGINT;
DECLARE @TeacherID BIGINT;
SELECT @TeacherID = Id FROM dbo.Users WHERE Username = 'teacher_mixed_test';
DECLARE @LessonID BIGINT = (SELECT TOP 1 LessonID FROM dbo.SIM_Lessons WHERE Title = 'Lesson Mixed Test');

