    Status,
    -- Cấu hình mới
    QuestionBankMode,
    QuestionPoolSize,
    QuestionsToDisplay,
    RandomizeQuestions,
    RandomizeOptions,
    AutoGradeMultipleChoice,
    ManualGradingRequired,
    ScoreMode,
    AllowShowScoreBeforeManualGrading,
    GlobalMaxScore,
