    70.0,  -- Passing 70%
    3,     -- Max 3 attempts
    60,    -- 60 minutes
    1,     -- Shuffle questions
    'ACTIVE',
    -- Cấu hình ngân hàng câu hỏi
    1,     -- QuestionBankMode = 1 (chế độ ngân hàng)
    50,    -- QuestionPoolSize = 50 câu trong ngân hàng
    20,    -- QuestionsToDisplay = 20 câu hiển thị
    1,     -- RandomizeQuestions = 1 (ngẫu nhiên câu hỏi)
    1,     -- RandomizeOptions = 1 (ngẫu nhiên đáp án)
    1,     -- AutoGradeMultipleChoice = 1 (tự chấm trắc nghiệm)
    1,     -- ManualGradingRequired = 1 (cần chấm thủ công - có tự luận)
    'EQUAL_DISTRIBUTION',  -- ScoreMode = chia đều điểm
