DECLARE @QuizAttemptID BIGINT = (SELECT TOP 1 QuizAttemptID FROM dbo.LMS_QuizAttempts ORDER BY QuizAttemptID DESC);

SELECT
    'BỘ CÂU HỎI ĐÃ SINH CHO HỌC VIÊN' AS Info,
    AssignmentID,
    QuestionID,
    SortOrder,
    Points,
    QuestionType,
    CASE 
        WHEN QuestionType = 'ESSAY' THEN 'TỰ LUẬN (chờ chấm)'
        ELSE 'TRẮC NGHIỆM (tự chấm)'
    END AS Category,
    LEFT(QuestionText, 50) + '...' AS QuestionPreview
FROM dbo.LMS_QuizQuestionAssignments
WHERE QuizAttemptID = @QuizAttemptID
ORDER BY SortOrder;
GO

-- ============================================
-- BƯỚC 8: HỌC VIÊN TRẢ LỜI CÂU HỎI
-- ============================================
PRINT '--- Bước 8: Học viên trả lời câu hỏi ---';

DECLARE @QuizAttemptID BIGINT = (SELECT TOP 1 QuizAttemptID FROM dbo.LMS_QuizAttempts ORDER BY QuizAttemptID DESC);

-- Lấy danh sách câu hỏi
DECLARE @Answers NVARCHAR(MAX) = N'[';

-- Tạo câu trả lời mẫu
DECLARE @QuestionID BIGINT;
DECLARE @QuestionType VARCHAR(50);
DECLARE @Counter INT = 0;

DECLARE question_cursor CURSOR FOR
SELECT QuestionID, QuestionType
FROM dbo.LMS_QuizQuestionAssignments
WHERE QuizAttemptID = @QuizAttemptID
ORDER BY SortOrder;

OPEN question_cursor;
FETCH NEXT FROM question_cursor INTO @QuestionID, @QuestionType;

WHILE @@FETCH_STATUS = 0
BEGIN
    IF @Counter > 0
        SET @Answers = @Answers + ',';

    IF @QuestionType = 'ESSAY'
    BEGIN
        SET @Answers = @Answers + N'{"questionId":' + CAST(@QuestionID AS NVARCHAR(20)) + N',"answerText":"Đây là câu trả lời tự luận cho câu hỏi ' + CAST(@QuestionID AS NVARCHAR(20)) + N'. Học sinh trình bày suy nghĩ chi tiết về chủ đề."}';
    END
    ELSE
    BEGIN
        -- Trắc nghiệm: trả lời ngẫu nhiên 1, 2, 3, hoặc 4
        SET @Answers = @Answers + N'{"questionId":' + CAST(@QuestionID AS NVARCHAR(20)) + N',"answerText":"' + CAST(((@QuestionID % 4) + 1) AS NVARCHAR(10)) + N'"}';
    END

    SET @Counter = @Counter + 1;
    FETCH NEXT FROM question_cursor INTO @QuestionID, @QuestionType;
END

CLOSE question_cursor;
DEALLOCATE question_cursor;

SET @Answers = @Answers + N']';

PRINT 'Đã tạo câu trả lời JSON';
PRINT 'Số câu trả lời: ' + CAST(@Counter AS NVARCHAR(10));
GO

