-- =====================================================================
-- STORED PROCEDURE: LMS_ContentTree_Create
-- Tạo một node mới trong content tree
-- =====================================================================
-- Chức năng:
-- 1. Tạo node mới ở bất kỳ cấp nào
-- 2. Tự động tính Level và Path
-- 3. Cập nhật Path của các node con (nếu cần)
-- 4. Hỗ trợ tạo Course (Level 0) hoặc node con
-- =====================================================================

IF EXISTS (SELECT 1 FROM sys.procedures WHERE name = 'LMS_ContentTree_Create')
    DROP PROCEDURE dbo.LMS_ContentTree_Create;
GO

CREATE PROCEDURE dbo.LMS_ContentTree_Create
    @ContentID BIGINT = NULL OUTPUT,
    @ContentName NVARCHAR(200),
    @ContentType VARCHAR(50),
    @ParentID BIGINT = NULL,
    @Description NVARCHAR(MAX) = NULL,
    @ContentSubType VARCHAR(50) = NULL,
    @SortOrder INT = 0,
    @IsPublished BIT = 0,
    @IsRequired BIT = 1,
    @EstimatedMinutes INT = NULL,
    @MaxScore DECIMAL(8, 2) = NULL,
    @PassingScore DECIMAL(8, 2) = NULL,
    @MaxAttempts INT = NULL,
    @TimeLimitMinutes INT = NULL,
    @ActorID BIGINT,
    @CreatedUser NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    -- Validate
    IF NULLIF(LTRIM(RTRIM(@ContentName)), '') IS NULL
        THROW 50001, N'Tên nội dung không được để trống.', 1;

    IF NULLIF(LTRIM(RTRIM(@ContentType)), '') IS NULL
        THROW 50001, N'Loại nội dung không được để trống.', 1;

    -- Nếu là Course (Level 0), không có ParentID
    IF @ContentType = 'COURSE' AND @ParentID IS NOT NULL
        THROW 50002, N'Course không thể có node cha.', 1;

    -- Nếu không phải Course, phải có ParentID
    IF @ContentType != 'COURSE' AND @ParentID IS NULL
        THROW 50003, N'Nội dung phải có node cha (trừ Course).', 1;

    -- Kiểm tra ParentID tồn tại
    IF @ParentID IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dbo.LMS_ContentTree WHERE ContentID = @ParentID)
        THROW 50004, N'Node cha không tồn tại.', 1;

    BEGIN TRANSACTION;

    DECLARE @NewLevel INT;
    DECLARE @NewPath NVARCHAR(500);
    DECLARE @RootCourseID BIGINT;

    -- Tính Level và Path
    IF @ParentID IS NULL
    BEGIN
        -- Tạo Course (Level 0)
        SET @NewLevel = 0;
        SET @NewPath = '/' + CAST(SCOPE_IDENTITY() AS NVARCHAR(20)) + '/';  -- Will update after insert
        SET @RootCourseID = NULL;
    END
    ELSE
    BEGIN
        -- Tạo node con
        SELECT
            @NewLevel = Level + 1,
            @RootCourseID = CASE WHEN RootCourseID IS NULL THEN ContentID ELSE RootCourseID END
        FROM dbo.LMS_ContentTree
        WHERE ContentID = @ParentID;

        -- Path sẽ được cập nhật sau khi insert
        SET @NewPath = '';  -- Placeholder
    END

    -- Insert
    INSERT dbo.LMS_ContentTree
    (
        ContentName,
        ContentSlug,
        Description,
        ContentType,
        ContentSubType,
        ParentID,
        Level,
        Path,
        SortOrder,
        RootCourseID,
        IsPublished,
        IsRequired,
        EstimatedMinutes,
        MaxScore,
        PassingScore,
        MaxAttempts,
        TimeLimitMinutes,
        CreatedByUserID,
        CreatedUser,
        Status
    )
    VALUES
    (
        @ContentName,
        dbo.GenerateSlug(@ContentName),  -- Cần có function GenerateSlug
        @Description,
        @ContentType,
        @ContentSubType,
        @ParentID,
        @NewLevel,
        @NewPath,
        @SortOrder,
        @RootCourseID,
        @IsPublished,
        @IsRequired,
        @EstimatedMinutes,
        @MaxScore,
        @PassingScore,
        @MaxAttempts,
        @TimeLimitMinutes,
        @ActorID,
        @CreatedUser,
        'ACTIVE'
    );

    SET @ContentID = SCOPE_IDENTITY();

    -- Cập nhật Path
    IF @ParentID IS NULL
    BEGIN
        -- Course: Path = /ContentID/
        UPDATE dbo.LMS_ContentTree
        SET Path = '/' + CAST(@ContentID AS NVARCHAR(20)) + '/',
            RootCourseID = @ContentID
        WHERE ContentID = @ContentID;
    END
    ELSE
    BEGIN
        -- Node con: Path = ParentPath + ContentID + /
        DECLARE @ParentPath NVARCHAR(500);
        SELECT @ParentPath = Path FROM dbo.LMS_ContentTree WHERE ContentID = @ParentID;

        UPDATE dbo.LMS_ContentTree
        SET Path = @ParentPath + CAST(@ContentID AS NVARCHAR(20)) + '/'
        WHERE ContentID = @ContentID;
    END

    COMMIT TRANSACTION;

    -- Audit log
    INSERT dbo.AuditLogs (UserId, Action, Module, EntityName, EntityId)
    VALUES (@ActorID, 'CREATE', 'CONTENT_TREE', 'ContentNode', CONVERT(NVARCHAR(100), @ContentID));

    -- Return
    SELECT
        @ContentID ContentID,
        ContentName,
        ContentType,
        Level,
        Path,
        RootCourseID
    FROM dbo.LMS_ContentTree
    WHERE ContentID = @ContentID;

    PRINT 'Đã tạo node: ' + @ContentName + ' (ID: ' + CAST(@ContentID AS NVARCHAR(20)) + ')';
END
GO

-- Tạo function GenerateSlug (nếu chưa có)
IF EXISTS (SELECT 1 FROM sys.functions WHERE name = 'GenerateSlug' AND type = 'FN')
    DROP FUNCTION dbo.GenerateSlug;
GO

CREATE FUNCTION dbo.GenerateSlug
(
    @Text NVARCHAR(500)
)
RETURNS NVARCHAR(500)
AS
BEGIN
    DECLARE @Slug NVARCHAR(500) = @Text;

    -- Chuyển thành lowercase
    SET @Slug = LOWER(@Slug);

    -- Thay thế các ký tự đặc biệt
    SET @Slug = REPLACE(@Slug, N' ', '-');
    SET @Slug = REPLACE(@Slug, N'á', 'a');
    SET @Slug = REPLACE(@Slug, N'à', 'a');
    SET @Slug = REPLACE(@Slug, N'ả', 'a');
    SET @Slug = REPLACE(@Slug, N'ã', 'a');
    SET @Slug = REPLACE(@Slug, N'ạ', 'a');
    SET @Slug = REPLACE(@Slug, N'ă', 'a');
    SET @Slug = REPLACE(@Slug, N'ắ', 'a');
    SET @Slug = REPLACE(@Slug, N'ằ', 'a');
    SET @Slug = REPLACE(@Slug, N'ẳ', 'a');
    SET @Slug = REPLACE(@Slug, N'ẵ', 'a');
    SET @Slug = REPLACE(@Slug, N'ặ', 'a');
    SET @Slug = REPLACE(@Slug, N'â', 'a');
    SET @Slug = REPLACE(@Slug, N'ấ', 'a');
    SET @Slug = REPLACE(@Slug, N'ầ', 'a');
    SET @Slug = REPLACE(@Slug, N'ẩ', 'a');
    SET @Slug = REPLACE(@Slug, N'ẫ', 'a');
    SET @Slug = REPLACE(@Slug, N'ậ', 'a');
    SET @Slug = REPLACE(@Slug, N'é', 'e');
    SET @Slug = REPLACE(@Slug, N'è', 'e');
    SET @Slug = REPLACE(@Slug, N'ẻ', 'e');
    SET @Slug = REPLACE(@Slug, N'ẽ', 'e');
    SET @Slug = REPLACE(@Slug, N'ẹ', 'e');
    SET @Slug = REPLACE(@Slug, N'ê', 'e');
    SET @Slug = REPLACE(@Slug, N'ế', 'e');
    SET @Slug = REPLACE(@Slug, N'ề', 'e');
    SET @Slug = REPLACE(@Slug, N'ể', 'e');
    SET @Slug = REPLACE(@Slug, N'ễ', 'e');
    SET @Slug = REPLACE(@Slug, N'ệ', 'e');
    SET @Slug = REPLACE(@Slug, N'í', 'i');
    SET @Slug = REPLACE(@Slug, N'ì', 'i');
    SET @Slug = REPLACE(@Slug, N'ỉ', 'i');
    SET @Slug = REPLACE(@Slug, N'ĩ', 'i');
    SET @Slug = REPLACE(@Slug, N'ị', 'i');
    SET @Slug = REPLACE(@Slug, N'ó', 'o');
    SET @Slug = REPLACE(@Slug, N'ò', 'o');
    SET @Slug = REPLACE(@Slug, N'ỏ', 'o');
    SET @Slug = REPLACE(@Slug, N'õ', 'o');
    SET @Slug = REPLACE(@Slug, N'ọ', 'o');
    SET @Slug = REPLACE(@Slug, N'ô', 'o');
    SET @Slug = REPLACE(@Slug, N'ố', 'o');
    SET @Slug = REPLACE(@Slug, N'ồ', 'o');
    SET @Slug = REPLACE(@Slug, N'ổ', 'o');
    SET @Slug = REPLACE(@Slug, N'ỗ', 'o');
    SET @Slug = REPLACE(@Slug, N'ộ', 'o');
    SET @Slug = REPLACE(@Slug, N'ơ', 'o');
    SET @Slug = REPLACE(@Slug, N'ớ', 'o');
    SET @Slug = REPLACE(@Slug, N'ờ', 'o');
    SET @Slug = REPLACE(@Slug, N'ở', 'o');
    SET @Slug = REPLACE(@Slug, N'ỡ', 'o');
    SET @Slug = REPLACE(@Slug, N'ợ', 'o');
    SET @Slug = REPLACE(@Slug, N'ú', 'u');
    SET @Slug = REPLACE(@Slug, N'ù', 'u');
    SET @Slug = REPLACE(@Slug, N'ủ', 'u');
    SET @Slug = REPLACE(@Slug, N'ũ', 'u');
    SET @Slug = REPLACE(@Slug, N'ụ', 'u');
    SET @Slug = REPLACE(@Slug, N'ư', 'u');
    SET @Slug = REPLACE(@Slug, N'ứ', 'u');
    SET @Slug = REPLACE(@Slug, N'ừ', 'u');
    SET @Slug = REPLACE(@Slug, N'ử', 'u');
    SET @Slug = REPLACE(@Slug, N'ữ', 'u');
    SET @Slug = REPLACE(@Slug, N'ự', 'u');
    SET @Slug = REPLACE(@Slug, N'ý', 'y');
    SET @Slug = REPLACE(@Slug, N'ỳ', 'y');
    SET @Slug = REPLACE(@Slug, N'ỷ', 'y');
    SET @Slug = REPLACE(@Slug, N'ỹ', 'y');
    SET @Slug = REPLACE(@Slug, N'ỵ', 'y');
    SET @Slug = REPLACE(@Slug, N'đ', 'd');

    -- Xóa các ký tự không phải alphanumeric và hyphen
    DECLARE @i INT = 1;
    DECLARE @Result NVARCHAR(500) = '';
    DECLARE @Char NCHAR(1);

    WHILE @i <= LEN(@Slug)
    BEGIN
        SET @Char = SUBSTRING(@Slug, @i, 1);
        IF (@Char BETWEEN 'a' AND 'z') OR (@Char BETWEEN '0' AND '9') OR @Char = '-'
            SET @Result = @Result + @Char;
        SET @i = @i + 1;
    END

    -- Xóa dấu gạch nối thừa
    WHILE @Result LIKE '%--%'
        SET @Result = REPLACE(@Result, '--', '-');

    -- Xóa dấu gạch nối ở đầu/cuối
    IF LEFT(@Result, 1) = '-'
        SET @Result = SUBSTRING(@Result, 2, LEN(@Result));
    IF RIGHT(@Result, 1) = '-'
        SET @Result = SUBSTRING(@Result, 1, LEN(@Result) - 1);

    RETURN @Result;
END
GO

PRINT '========================================';
PRINT 'Đã tạo SP: LMS_ContentTree_Create';
PRINT 'Đã tạo Function: GenerateSlug';
PRINT '========================================';
GO

-- =====================================================================
-- STORED PROCEDURE: LMS_ContentTree_Move
-- Di chuyển một node sang node cha khác
-- =====================================================================
-- Chức năng:
-- 1. Di chuyển node (và tất cả con) sang parent mới
-- 2. Tự động cập nhật Level và Path cho node và tất cả con
-- 3. Validate: không thể di chuyển Course thành con của node khác
-- 4. Validate: không thể di chuyển node thành con của chính nó
-- =====================================================================

IF EXISTS (SELECT 1 FROM sys.procedures WHERE name = 'LMS_ContentTree_Move')
    DROP PROCEDURE dbo.LMS_ContentTree_Move;
GO

CREATE PROCEDURE dbo.LMS_ContentTree_Move
    @ContentID BIGINT,
    @NewParentID BIGINT = NULL,
    @NewSortOrder INT = NULL,
    @ActorID BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    -- Validate
    IF @ContentID IS NULL
        THROW 50001, N'ContentID không được để trống.', 1;

    -- Lấy thông tin node hiện tại
    DECLARE @CurrentContentType VARCHAR(50);
    DECLARE @CurrentLevel INT;
    DECLARE @CurrentPath NVARCHAR(500);
    DECLARE @CurrentRootCourseID BIGINT;

    SELECT
        @CurrentContentType = ContentType,
        @CurrentLevel = Level,
        @CurrentPath = Path,
        @CurrentRootCourseID = RootCourseID
    FROM dbo.LMS_ContentTree
    WHERE ContentID = @ContentID;

    IF @CurrentContentType IS NULL
        THROW 50002, N'Content không tồn tại.', 1;

    -- Course không thể di chuyển thành con
    IF @CurrentContentType = 'COURSE' AND @NewParentID IS NOT NULL
        THROW 50003, N'Course không thể di chuyển thành node con.', 1;

    -- Kiểm tra NewParentID
    IF @NewParentID IS NOT NULL
    BEGIN
        IF @NewParentID = @ContentID
            THROW 50004, N'Không thể di chuyển node thành con của chính nó.', 1;

        -- Kiểm tra NewParentID không phải là con của @ContentID
        DECLARE @NewParentPath NVARCHAR(500);
        SELECT @NewParentPath = Path FROM dbo.LMS_ContentTree WHERE ContentID = @NewParentID;

        IF @NewParentPath IS NULL
            THROW 50005, N'Parent mới không tồn tại.', 1;

        IF @NewParentPath LIKE @CurrentPath + '%'
            THROW 50006, N'Không thể di chuyển node thành con của chính nó (hoặc con của nó).', 1;
    END;

    BEGIN TRANSACTION;

    -- Tính Level và Path mới
    DECLARE @NewLevel INT;
    DECLARE @NewPath NVARCHAR(500);
    DECLARE @NewRootCourseID BIGINT;

    IF @NewParentID IS NULL
    BEGIN
        -- Di chuyển lên thành Course (không hợp lệ vì đã check ở trên)
        THROW 50007, N'Không thể di chuyển node lên thành Course.', 1;
    END
    ELSE
    BEGIN
        -- Di chuyển sang parent mới
        DECLARE @ParentLevel INT;
        DECLARE @ParentPath NVARCHAR(500);
        DECLARE @ParentRootCourseID BIGINT;

        SELECT
            @ParentLevel = Level,
            @ParentPath = Path,
            @ParentRootCourseID = RootCourseID
        FROM dbo.LMS_ContentTree
        WHERE ContentID = @NewParentID;

        SET @NewLevel = @ParentLevel + 1;
        SET @NewPath = @ParentPath + CAST(@ContentID AS NVARCHAR(20)) + '/';
        SET @NewRootCourseID = CASE WHEN @ParentRootCourseID IS NULL THEN @NewParentID ELSE @ParentRootCourseID END;
    END

    -- Tính level offset
    DECLARE @LevelOffset INT = @NewLevel - @CurrentLevel;

    -- Cập nhật node hiện tại
    UPDATE dbo.LMS_ContentTree
    SET
        ParentID = @NewParentID,
        Level = @NewLevel,
        Path = @NewPath,
        RootCourseID = @NewRootCourseID,
        SortOrder = ISNULL(@NewSortOrder, SortOrder),
        UpdatedAt = SYSUTCDATETIME()
    WHERE ContentID = @ContentID;

    -- Cập nhật tất cả con (recursively)
    -- Cần tính lại Path cho tất cả node có Path LIKE @CurrentPath + '%'

    DECLARE @OldPathPrefix NVARCHAR(500) = @CurrentPath;
    DECLARE @NewPathPrefix NVARCHAR(500) = @NewPath;

    -- Cập nhật path cho tất cả descendants
    -- Path cũ: /1/5/12/23/
    -- Path mới: /1/8/23/
    -- Descendant cũ: /1/5/12/23/45/ -> mới: /1/8/23/45/

    UPDATE dbo.LMS_ContentTree
    SET
        Path = REPLACE(Path, @OldPathPrefix, @NewPathPrefix),
        Level = Level + @LevelOffset,
        RootCourseID = @NewRootCourseID,
        UpdatedAt = SYSUTCDATETIME()
    WHERE Path LIKE @OldPathPrefix + '%'
        AND ContentID != @ContentID;

    COMMIT TRANSACTION;

    -- Audit log
    INSERT dbo.AuditLogs (UserId, Action, Module, EntityName, EntityId)
    VALUES (@ActorID, 'MOVE', 'CONTENT_TREE', 'ContentNode', CONVERT(NVARCHAR(100), @ContentID));

    -- Return result
    SELECT
        @ContentID ContentID,
        @NewParentID NewParentID,
        @NewLevel NewLevel,
        @NewPath NewPath,
        @NewRootCourseID NewRootCourseID;

    PRINT 'Đã di chuyển ContentID: ' + CAST(@ContentID AS NVARCHAR(20)) + ' sang ParentID: ' + ISNULL(CAST(@NewParentID AS NVARCHAR(20)), 'NULL');
END
GO

-- =====================================================================
-- STORED PROCEDURE: LMS_ContentTree_Update
-- Cập nhật thông tin node
-- =====================================================================

IF EXISTS (SELECT 1 FROM sys.procedures WHERE name = 'LMS_ContentTree_Update')
    DROP PROCEDURE dbo.LMS_ContentTree_Update;
GO

CREATE PROCEDURE dbo.LMS_ContentTree_Update
    @ContentID BIGINT,
    @ContentName NVARCHAR(200) = NULL,
    @Description NVARCHAR(MAX) = NULL,
    @ContentSubType VARCHAR(50) = NULL,
    @SortOrder INT = NULL,
    @IsPublished BIT = NULL,
    @IsRequired BIT = NULL,
    @IsFree BIT = NULL,
    @AllowPreview BIT = NULL,
    @EstimatedMinutes INT = NULL,
    @MaxScore DECIMAL(8, 2) = NULL,
    @PassingScore DECIMAL(8, 2) = NULL,
    @MaxAttempts INT = NULL,
    @TimeLimitMinutes INT = NULL,
    @Icon VARCHAR(100) = NULL,
    @Color VARCHAR(20) = NULL,
    @Thumbnail NVARCHAR(500) = NULL,
    @ActorID BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    -- Validate
    IF NOT EXISTS (SELECT 1 FROM dbo.LMS_ContentTree WHERE ContentID = @ContentID)
        THROW 50001, N'Content không tồn tại.', 1;

    -- Update
    UPDATE dbo.LMS_ContentTree
    SET
        ContentName = ISNULL(@ContentName, ContentName),
        ContentSlug = CASE WHEN @ContentName IS NOT NULL THEN dbo.GenerateSlug(@ContentName) ELSE ContentSlug END,
        Description = ISNULL(@Description, Description),
        ContentSubType = ISNULL(@ContentSubType, ContentSubType),
        SortOrder = ISNULL(@SortOrder, SortOrder),
        IsPublished = ISNULL(@IsPublished, IsPublished),
        IsRequired = ISNULL(@IsRequired, IsRequired),
        IsFree = ISNULL(@IsFree, IsFree),
        AllowPreview = ISNULL(@AllowPreview, AllowPreview),
        EstimatedMinutes = ISNULL(@EstimatedMinutes, EstimatedMinutes),
        MaxScore = ISNULL(@MaxScore, MaxScore),
        PassingScore = ISNULL(@PassingScore, PassingScore),
        MaxAttempts = ISNULL(@MaxAttempts, MaxAttempts),
        TimeLimitMinutes = ISNULL(@TimeLimitMinutes, TimeLimitMinutes),
        Icon = ISNULL(@Icon, Icon),
        Color = ISNULL(@Color, Color),
        Thumbnail = ISNULL(@Thumbnail, Thumbnail),
        UpdatedAt = SYSUTCDATETIME()
    WHERE ContentID = @ContentID;

    -- Audit log
    INSERT dbo.AuditLogs (UserId, Action, Module, EntityName, EntityId)
    VALUES (@ActorID, 'UPDATE', 'CONTENT_TREE', 'ContentNode', CONVERT(NVARCHAR(100), @ContentID));

    PRINT 'Đã cập nhật ContentID: ' + CAST(@ContentID AS NVARCHAR(20));
END
GO

-- =====================================================================
-- STORED PROCEDURE: LMS_ContentTree_Delete
-- Xóa node (hard delete hoặc soft delete)
-- =====================================================================

IF EXISTS (SELECT 1 FROM sys.procedures WHERE name = 'LMS_ContentTree_Delete')
    DROP PROCEDURE dbo.LMS_ContentTree_Delete;
GO

CREATE PROCEDURE dbo.LMS_ContentTree_Delete
    @ContentID BIGINT,
    @DeleteChildren BIT = 0,      -- 0: chỉ xóa node này, 1: xóa cả tất cả con
    @SoftDelete BIT = 1,          -- 0: hard delete, 1: soft delete (set Status = DELETED)
    @ActorID BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    -- Validate
    DECLARE @ContentType VARCHAR(50);
    DECLARE @HasChildren BIT;

    SELECT
        @ContentType = ContentType,
        @HasChildren = CASE WHEN EXISTS (SELECT 1 FROM dbo.LMS_ContentTree WHERE ParentID = @ContentID) THEN 1 ELSE 0 END
    FROM dbo.LMS_ContentTree
    WHERE ContentID = @ContentID;

    IF @ContentType IS NULL
        THROW 50001, N'Content không tồn tại.', 1;

    -- Course không thể xóa (để lại cho enrollment data)
    IF @ContentType = 'COURSE'
        THROW 50002, N'Không thể xóa Course. Vui lòng xóa enrollment trước.', 1;

    -- Nếu có con và không muốn xóa con
    IF @HasChildren = 1 AND @DeleteChildren = 0
        THROW 50003, N'Node có con. Sử dụng @DeleteChildren=1 để xóa cả tất cả con.', 1;

    BEGIN TRANSACTION;

    IF @SoftDelete = 1
    BEGIN
        -- Soft delete
        IF @DeleteChildren = 1
        BEGIN
            -- Xóa node và tất cả con
            DECLARE @CurrentPath NVARCHAR(500);
            SELECT @CurrentPath = Path FROM dbo.LMS_ContentTree WHERE ContentID = @ContentID;

            UPDATE dbo.LMS_ContentTree
            SET Status = 'DELETED', UpdatedAt = SYSUTCDATETIME()
            WHERE Path LIKE @CurrentPath + '%';
        END
        ELSE
        BEGIN
            -- Chỉ xóa node này
            UPDATE dbo.LMS_ContentTree
            SET Status = 'DELETED', UpdatedAt = SYSUTCDATETIME()
            WHERE ContentID = @ContentID;
        END
    END
    ELSE
    BEGIN
        -- Hard delete
        IF @DeleteChildren = 1
        BEGIN
            -- Xóa node và tất cả con
            DECLARE @CurrentPath NVARCHAR(500);
            SELECT @CurrentPath = Path FROM dbo.LMS_ContentTree WHERE ContentID = @ContentID;

            -- Xóa files
            DELETE FROM dbo.LMS_ContentFiles
            WHERE ContentID IN (SELECT ContentID FROM dbo.LMS_ContentTree WHERE Path LIKE @CurrentPath + '%');

            -- Xóa progress
            DELETE FROM dbo.LMS_ContentProgress
            WHERE ContentID IN (SELECT ContentID FROM dbo.LMS_ContentTree WHERE Path LIKE @CurrentPath + '%');

            -- Xóa comments
            DELETE FROM dbo.LMS_ContentComments
            WHERE ContentID IN (SELECT ContentID FROM dbo.LMS_ContentTree WHERE Path LIKE @CurrentPath + '%');

            -- Xóa tag map
            DELETE FROM dbo.LMS_ContentTagMap
            WHERE ContentID IN (SELECT ContentID FROM dbo.LMS_ContentTree WHERE Path LIKE @CurrentPath + '%');

            -- Xóa node
            DELETE FROM dbo.LMS_ContentTree
            WHERE Path LIKE @CurrentPath + '%';
        END
        ELSE
        BEGIN
            -- Chỉ xóa node này
            DELETE FROM dbo.LMS_ContentFiles WHERE ContentID = @ContentID;
            DELETE FROM dbo.LMS_ContentProgress WHERE ContentID = @ContentID;
            DELETE FROM dbo.LMS_ContentComments WHERE ContentID = @ContentID;
            DELETE FROM dbo.LMS_ContentTagMap WHERE ContentID = @ContentID;
            DELETE FROM dbo.LMS_ContentTree WHERE ContentID = @ContentID;
        END
    END

    COMMIT TRANSACTION;

    -- Audit log
    INSERT dbo.AuditLogs (UserId, Action, Module, EntityName, EntityId)
    VALUES (@ActorID, 'DELETE', 'CONTENT_TREE', 'ContentNode', CONVERT(NVARCHAR(100), @ContentID));

    PRINT 'Đã xóa ContentID: ' + CAST(@ContentID AS NVARCHAR(20));
END
GO

