-- ============================================
-- BƯỚC 14: XEM TREE THEO ĐỊNH DẠNG INDENT
-- ============================================
PRINT '--- Bước 14: Xem tree định dạng indent ---';

DECLARE @CourseID BIGINT = (SELECT TOP 1 ContentID FROM dbo.LMS_ContentTree WHERE ContentType = 'COURSE' AND ContentName LIKE 'Test Tree%');

SELECT
    REPLICATE('   ', Level) + 
    CASE 
        WHEN ContentType = 'COURSE' THEN '📚 '
        WHEN ContentType = 'CHAPTER' THEN '📖 '
        WHEN ContentType = 'LESSON' THEN '📝 '
        WHEN ContentType = 'SECTION' THEN '📌 '
        WHEN ContentType = 'QUIZ' THEN '❓ '
        WHEN ContentType = 'ASSIGNMENT' THEN '✏️ '
        WHEN ContentType = 'VIDEO' THEN '🎬 '
        WHEN ContentType = 'DOCUMENT' THEN '📄 '
        WHEN ContentType = 'INTERACTIVE' THEN '🎮 '
        ELSE '📦 '
    END +
    ContentName + 
    ' [' + ContentType + 
    CASE WHEN ContentSubType IS NOT NULL THEN ' - ' + ContentSubType ELSE '' END +
    ']' AS TreeStructure,
    ContentID,
    ParentID,
    Level,
    Path,
    SortOrder,
    IsPublished,
    EstimatedMinutes,
    MaxScore
