-- ============================================
-- BƯỚC 19: XEM LẠI TREE SAU KHI DI CHUYỂN
-- ============================================
PRINT '--- Bước 19: Xem lại tree sau khi di chuyển ---';

DECLARE @CourseID BIGINT = (SELECT TOP 1 ContentID FROM dbo.LMS_ContentTree WHERE ContentType = 'COURSE' AND ContentName LIKE 'Test Tree%');

SELECT
    REPLICATE('   ', Level) + 
    CASE 
        WHEN ContentType = 'COURSE' THEN '📚 '
        WHEN ContentType = 'CHAPTER' THEN '📖 '
        WHEN ContentType = 'LESSON' THEN '📝 '
        WHEN ContentType = 'SECTION' THEN '📌 '
        WHEN ContentType = 'QUIZ' THEN '❓ '
        WHEN ContentType = 'ASSIGNMENT' THEN '✏️ '
        WHEN ContentType = 'VIDEO' THEN '🎬 '
        WHEN ContentType = 'DOCUMENT' THEN '📄 '
        WHEN ContentType = 'INTERACTIVE' THEN '🎮 '
        ELSE '📦 '
    END +
    ContentName + 
    ' [' + ContentType + 
    CASE WHEN ContentSubType IS NOT NULL THEN ' - ' + ContentSubType ELSE '' END +
    ']' AS TreeStructure,
    ContentID,
    ParentID,
    Level,
    Path,
    SortOrder
FROM dbo.LMS_ContentTree
WHERE RootCourseID = @CourseID OR ContentID = @CourseID
    AND Status = 'ACTIVE'
ORDER BY Path, SortOrder;
GO

-- ============================================
-- BƯỚC 20: THỐNG KÊ
-- ============================================
PRINT '--- Bước 20: Thống kê ---';

DECLARE @CourseID BIGINT = (SELECT TOP 1 ContentID FROM dbo.LMS_ContentTree WHERE ContentType = 'COURSE' AND ContentName LIKE 'Test Tree%');

SELECT
    'THỐNG KÊ COURSE' AS Info,
    COUNT(*) AS TotalNodes,
    SUM(CASE WHEN Level = 0 THEN 1 ELSE 0 END) AS Courses,
    SUM(CASE WHEN Level = 1 THEN 1 ELSE 0 END) AS Chapters,
    SUM(CASE WHEN Level = 2 THEN 1 ELSE 0 END) AS Lessons,
    SUM(CASE WHEN Level = 3 THEN 1 ELSE 0 END) AS Sections,
    SUM(CASE WHEN Level >= 4 THEN 1 ELSE 0 END) AS ContentItems,
    SUM(CASE WHEN ContentType = 'QUIZ' THEN 1 ELSE 0 END) AS Quizzes,
    SUM(CASE WHEN ContentType = 'VIDEO' THEN 1 ELSE 0 END) AS Videos,
    SUM(CASE WHEN ContentType = 'DOCUMENT' THEN 1 ELSE 0 END) AS Documents,
    SUM(CASE WHEN ContentType = 'INTERACTIVE' THEN 1 ELSE 0 END) AS Interactives,
    SUM(CASE WHEN ContentType = 'ASSIGNMENT' THEN 1 ELSE 0 END) AS Assignments,
    SUM(EstimatedMinutes) AS TotalEstimatedMinutes
FROM dbo.LMS_ContentTree
WHERE RootCourseID = @CourseID OR ContentID = @CourseID
    AND Status = 'ACTIVE';
GO

