        public static void InitLookUpEdit(UGridLookUpEdit lookup, string condition)
        {
            DataTable dtbCopy = null;
            if (condition != "" && condition != null)
            {
                dtbCopy = Table.Copy();
                dtbCopy.DefaultView.RowFilter = "(" + condition + ")" + " or ContentID is null";
            }
            else
                dtbCopy = Table;
            lookup.InitData(dtbCopy, "--Chọn--", "ContentID", "ContentName", "", "Mã", "ContentName", "Tên");
        }

        #endregion

        #region InitRepositoryLookUpEdit

        public static void InitRepositoryLookUpEdit(DevExpress.XtraEditors.Repository.RepositoryItemGridLookUpEdit lookup, DgAdvBandedGridView gridView)
        {
            lookup.DataSource = Table;
            lookup.ValueMember = "ContentID";
            lookup.DisplayMember = "ContentName";
            lookup.NullText = "--Chọn--";
        }

        public static void InitRepositoryLookUpEdit(DevExpress.XtraEditors.Repository.RepositoryItemGridLookUpEdit lookup, DgGridView gridView)
        {
            lookup.DataSource = Table;
            lookup.ValueMember = "ContentID";
            lookup.DisplayMember = "ContentName";
            lookup.NullText = "--Chọn--";
        }

        #endregion

        #region Tree Helper Methods

        /// <summary>
        /// Lấy toàn bộ tree của một course
        /// </summary>
        public static DataTable GetCourseTree(long courseId, bool includeProgress = false, long? studentUserId = null)
        {
            LMS_ContentTree obj = new LMS_ContentTree();
            obj.IDB = DCore.Data.CreateData();
            obj.IDB.CreateNewStoredProcedure(LMS_ContentTree.StoreGetTree);
            obj.IDB.AddParameter(LMS_ContentTree.P_CourseID, courseId);
            obj.IDB.AddParameter(LMS_ContentTree.P_IncludeProgress, includeProgress);
            obj.IDB.AddParameter(LMS_ContentTree.P_StudentUserID, studentUserId);
            DataTable dtb = obj.IDB.ExecStoreToDataTable();
            obj.IDB.Disconnect();
            return dtb;
        }

        /// <summary>
        /// Lấy các node con trực tiếp
        /// </summary>
        public static DataTable GetChildren(long parentId, bool includeProgress = false, long? studentUserId = null)
        {
            LMS_ContentTree obj = new LMS_ContentTree();
            obj.IDB = DCore.Data.CreateData();
            obj.IDB.CreateNewStoredProcedure(LMS_ContentTree.StoreGetChildren);
            obj.IDB.AddParameter(LMS_ContentTree.P_ParentID, parentId);
            obj.IDB.AddParameter(LMS_ContentTree.P_IncludeProgress, includeProgress);
            obj.IDB.AddParameter(LMS_ContentTree.P_StudentUserID, studentUserId);
            DataTable dtb = obj.IDB.ExecStoreToDataTable();
            obj.IDB.Disconnect();
            return dtb;
        }

        /// <summary>
        /// Lấy path (breadcrumb) từ root đến node
        /// </summary>
        public static DataTable GetPath(long contentId)
        {
            LMS_ContentTree obj = new LMS_ContentTree();
            obj.IDB = DCore.Data.CreateData();
            obj.IDB.CreateNewStoredProcedure(LMS_ContentTree.StoreGetPath);
            obj.IDB.AddParameter(LMS_ContentTree.P_ContentID, contentId);
            DataTable dtb = obj.IDB.ExecStoreToDataTable();
            obj.IDB.Disconnect();
            return dtb;
        }

        /// <summary>
        /// Lấy tất cả descendants (con, cháu, chắt...)
        /// </summary>
        public static DataTable GetAllDescendants(long parentId, int? maxLevel = null, string contentType = null)
        {
            LMS_ContentTree obj = new LMS_ContentTree();
            obj.IDB = DCore.Data.CreateData();
            obj.IDB.CreateNewStoredProcedure(LMS_ContentTree.StoreGetAllDescendants);
            obj.IDB.AddParameter(LMS_ContentTree.P_ParentID, parentId);
            obj.IDB.AddParameter("@MaxLevel", maxLevel);
            obj.IDB.AddParameter("@ContentType", contentType);
            DataTable dtb = obj.IDB.ExecStoreToDataTable();
            obj.IDB.Disconnect();
            return dtb;
        }

        /// <summary>
        /// Tạo node mới
        /// </summary>
        public static long CreateNode(string contentName, string contentType, long? parentId, 
            string description = null, string contentSubType = null, int sortOrder = 0, 
            bool isPublished = false, bool isRequired = true, int? estimatedMinutes = null,
            decimal? maxScore = null, decimal? passingScore = null, int? maxAttempts = null,
            int? timeLimitMinutes = null, long actorId = 0, string createdUser = null)
        {
            LMS_ContentTree obj = new LMS_ContentTree();
            obj.ContentName = contentName;
            obj.ContentType = contentType;
            obj.ParentID = parentId;
            obj.Description = description;
            obj.ContentSubType = contentSubType;
            obj.SortOrder = sortOrder;
            obj.IsPublished = isPublished;
            obj.IsRequired = isRequired;
            obj.EstimatedMinutes = estimatedMinutes;
            obj.MaxScore = maxScore;
            obj.PassingScore = passingScore;
            obj.MaxAttempts = maxAttempts;
            obj.TimeLimitMinutes = timeLimitMinutes;
            obj.CreatedByUserID = actorId;
            obj.CreatedUser = createdUser;

            if (obj.Create())
            {
                HaveNewData = true;
                return obj.ContentID;
            }
            return 0;
        }

        /// <summary>
        /// Di chuyển node sang parent khác
        /// </summary>
        public static bool MoveNode(long contentId, long? newParentId, int newSortOrder, long actorId)
        {
            LMS_ContentTree obj = new LMS_ContentTree();
            obj.ContentID = contentId;
            if (obj.Move(newParentId, newSortOrder))
            {
                HaveNewData = true;
                return true;
            }
            return false;
        }

        /// <summary>
        /// Xóa node
        /// </summary>
        public static bool DeleteNode(long contentId, bool deleteChildren = false, bool softDelete = true, long actorId = 0)
        {
            LMS_ContentTree obj = new LMS_ContentTree();
            obj.ContentID = contentId;
            obj.CreatedByUserID = actorId;
            if (obj.Delete())
            {
                HaveNewData = true;
                return true;
            }
            return false;
        }

        #endregion
    }
