using System;
using System.Data;
using Control;
using LmsObject;

namespace LmsService
{
    /// <summary>
    /// DCore: 20/10/2026  For LMS
    /// Created by      : NgocTrong
    /// Created date    : 20/10/2026
    /// Description     : Service cho bảng LMS_ContentFiles - Đính kèm file cho nội dung trong Content Tree
    /// </summary>
    public partial class LMS_ContentFilesService
    {
        #region Static Variables

        private static bool bolHaveNewData = false;
        private static DataTable dtbTable = null;

        #endregion

        #region Static Properties

        public static DataTable Table
        {
            get
            {
                if (dtbTable == null || bolHaveNewData)
                {
                    LMS_ContentFiles obj = new LMS_ContentFiles();
                    dtbTable = obj.GetDataTable("LMS_ContentFiles_SearchCbx");
                    DataRow drw = dtbTable.NewRow();
                    dtbTable.Rows.InsertAt(drw, 0); // thêm dòng trống
                    bolHaveNewData = false;
                }
                return dtbTable;
            }
            set { dtbTable = value; }
        }

        public static bool HaveNewData
        {
            get { return bolHaveNewData; }
            set { bolHaveNewData = value; }
        }

        #endregion

        #region InitLookUpEdit Methods

        public static void InitLookUpEdit(DgLookUpEdit lookup)
        {
            InitLookUpEdit(lookup, "");
        }

        public static void InitLookUpEdit(DgLookUpEdit lookup, string condition)
        {
            DataTable dtbCopy = null;
            if (condition != "" && condition != null)
            {
                dtbCopy = Table.Copy();
                dtbCopy.DefaultView.RowFilter = "(" + condition + ")" + " or FileID is null";
            }
            else
                dtbCopy = Table;
            lookup.InitData(dtbCopy, "--Chọn--", "FileID", "FileName", "FileOriginalName", "Mã", "Tên file", "Tên gốc");
        }

        public static void InitLookUpEdit(ULookUpEdit lookup)
        {
            InitLookUpEdit(lookup, "");
        }

        public static void InitLookUpEdit(ULookUpEdit lookup, string condition)
        {
            DataTable dtbCopy = null;
            if (condition != "" && condition != null)
            {
                dtbCopy = Table.Copy();
                dtbCopy.DefaultView.RowFilter = "(" + condition + ")" + " or FileID is null";
            }
            else
                dtbCopy = Table;
            lookup.InitData(dtbCopy, "--Chọn--", "FileID", "FileName", "FileOriginalName", "Mã", "Tên file", "Tên gốc");
        }

        public static void InitLookUpEdit(UGridLookUpEdit lookup)
        {
            InitLookUpEdit(lookup, "");
        }

        public static void InitLookUpEdit(UGridLookUpEdit lookup, string condition)
        {
            DataTable dtbCopy = null;
            if (condition != "" && condition != null)
            {
                dtbCopy = Table.Copy();
                dtbCopy.DefaultView.RowFilter = "(" + condition + ")" + " or FileID is null";
            }
            else
                dtbCopy = Table;
            lookup.InitData(dtbCopy, "--Chọn--", "FileID", "FileName", "FileOriginalName", "Mã", "Tên file", "Tên gốc");
        }

        #endregion

        #region InitRepositoryLookUpEdit

        public static void InitRepositoryLookUpEdit(DevExpress.XtraEditors.Repository.RepositoryItemGridLookUpEdit lookup, DgAdvBandedGridView gridView)
        {
            lookup.DataSource = Table;
            lookup.ValueMember = "FileID";
            lookup.DisplayMember = "FileName";
            lookup.NullText = "--Chọn--";
        }

        public static void InitRepositoryLookUpEdit(DevExpress.XtraEditors.Repository.RepositoryItemGridLookUpEdit lookup, DgGridView gridView)
        {
            lookup.DataSource = Table;
            lookup.ValueMember = "FileID";
            lookup.DisplayMember = "FileName";
            lookup.NullText = "--Chọn--";
        }

        #endregion

        #region File Helper Methods

        /// <summary>
        /// Lấy danh sách file của một nội dung
        /// </summary>
        /// <param name="contentId">ID của nội dung</param>
        /// <param name="fileType">Loại file (tùy chọn)</param>
        /// <returns>DataTable chứa danh sách file</returns>
        public static DataTable GetFilesByContent(long contentId, string fileType = null)
        {
            LMS_ContentFiles obj = new LMS_ContentFiles();
            obj.IDB = DCore.Data.CreateData();
            obj.IDB.CreateNewStoredProcedure("LMS_ContentFiles_GetByContent");
            obj.IDB.AddParameter("@ContentID", contentId);
            obj.IDB.AddParameter("@FileType", fileType);
            DataTable dtb = obj.IDB.ExecStoreToDataTable();
            obj.IDB.Disconnect();
            return dtb;
        }

        /// <summary>
        /// Lấy file chính (primary) của nội dung
        /// </summary>
        /// <param name="contentId">ID của nội dung</param>
        /// <returns>DataRow chứa file chính, null nếu không có</returns>
        public static DataRow GetPrimaryFile(long contentId)
        {
            DataTable dtb = GetFilesByContent(contentId);
            if (dtb != null && dtb.Rows.Count > 0)
            {
                foreach (DataRow dr in dtb.Rows)
                {
                    if (dr["IsPrimary"] != DBNull.Value && Convert.ToBoolean(dr["IsPrimary"]))
                    {
                        return dr;
                    }
                }
                // Nếu không có file primary, trả về file đầu tiên
                return dtb.Rows[0];
            }
            return null;
        }

        /// <summary>
        /// Upload file mới
        /// </summary>
        /// <param name="contentId">ID của nội dung</param>
        /// <param name="fileName">Tên file sau khi upload</param>
        /// <param name="fileOriginalName">Tên gốc của file</param>
        /// <param name="filePath">Đường dẫn vật lý hoặc URL</param>
        /// <param name="fileSize">Kích thước file (bytes)</param>
        /// <param name="fileType">Loại file (PDF, VIDEO, IMAGE, etc.)</param>
        /// <param name="mimeType">MIME type</param>
        /// <param name="isPrimary">Có phải file chính không</param>
        /// <param name="sortOrder">Thứ tự hiển thị</param>
        /// <param name="duration">Thời lượng (giây) - cho video/audio</param>
        /// <param name="width">Chiều rộng (pixels) - cho image/video</param>
        /// <param name="height">Chiều cao (pixels) - cho image/video</param>
        /// <param name="actorId">ID người upload</param>
        /// <returns>FileID nếu thành công, 0 nếu thất bại</returns>
        public static long UploadFile(long contentId, string fileName, string fileOriginalName, 
            string filePath, long fileSize, string fileType, string mimeType, 
            bool isPrimary = false, int sortOrder = 0, int? duration = null, 
            int? width = null, int? height = null, long actorId = 0)
        {
            LMS_ContentFiles obj = new LMS_ContentFiles();
            obj.ContentID = contentId;
            obj.FileName = fileName;
            obj.FileOriginalName = fileOriginalName;
            obj.FilePath = filePath;
            obj.FileSize = fileSize;
            obj.FileType = fileType;
            obj.MimeType = mimeType;
            obj.IsPrimary = isPrimary;
            obj.SortOrder = sortOrder;
            obj.Duration = duration;
            obj.Width = width;
            obj.Height = height;
            obj.CreatedByUserID = actorId;
            obj.CreatedAt = DateTime.UtcNow;
            obj.Status = "ACTIVE";

            if (obj.Create())
            {
                HaveNewData = true;
                return obj.FileID;
            }
            return 0;
        }

        /// <summary>
        /// Đặt file làm file chính
        /// </summary>
        /// <param name="fileId">ID của file</param>
        /// <param name="contentId">ID của nội dung (để bỏ primary của các file khác)</param>
        /// <returns>True nếu thành công, False nếu thất bại</returns>
        public static bool SetPrimaryFile(long fileId, long contentId)
        {
            try
            {
                // Bỏ primary của tất cả file khác trong cùng content
                LMS_ContentFiles obj = new LMS_ContentFiles();
                obj.IDB = DCore.Data.CreateData();
                obj.IDB.CreateNewStoredProcedure("LMS_ContentFiles_ClearPrimary");
                obj.IDB.AddParameter("@ContentID", contentId);
                obj.IDB.ExecStore();
                obj.IDB.Disconnect();

                // Đặt primary cho file được chọn
                obj.FileID = fileId;
                obj.IsPrimary = true;
                if (obj.Update())
                {
                    HaveNewData = true;
                    return true;
                }
                return false;
            }
            catch (Exception ex)
            {
                return false;
            }
        }

        /// <summary>
        /// Xóa file
        /// </summary>
        /// <param name="fileId">ID của file</param>
        /// <param name="softDelete">True = soft delete (update Status = DELETED), False = hard delete</param>
        /// <returns>True nếu thành công, False nếu thất bại</returns>
        public static bool DeleteFile(long fileId, bool softDelete = true)
        {
            LMS_ContentFiles obj = new LMS_ContentFiles();
            obj.FileID = fileId;

            if (softDelete)
            {
                obj.Status = "DELETED";
                if (obj.Update())
                {
                    HaveNewData = true;
                    return true;
                }
            }
            else
            {
                if (obj.Delete())
                {
                    HaveNewData = true;
                    return true;
                }
            }
            return false;
        }

        /// <summary>
        /// Xóa tất cả file của một nội dung
        /// </summary>
        /// <param name="contentId">ID của nội dung</param>
        /// <param name="softDelete">True = soft delete, False = hard delete</param>
        /// <returns>True nếu thành công, False nếu thất bại</returns>
        public static bool DeleteFilesByContent(long contentId, bool softDelete = true)
        {
            try
            {
                LMS_ContentFiles obj = new LMS_ContentFiles();
                obj.IDB = DCore.Data.CreateData();
                obj.IDB.CreateNewStoredProcedure("LMS_ContentFiles_DeleteByContent");
                obj.IDB.AddParameter("@ContentID", contentId);
                obj.IDB.AddParameter("@SoftDelete", softDelete);
                obj.IDB.ExecStore();
                obj.IDB.Disconnect();
                HaveNewData = true;
                return true;
            }
            catch (Exception ex)
            {
                return false;
            }
        }

        /// <summary>
        /// Tính tổng kích thước file của một nội dung
        /// </summary>
        /// <param name="contentId">ID của nội dung</param>
        /// <returns>Tổng kích thước (bytes)</returns>
        public static long GetTotalFileSize(long contentId)
        {
            try
            {
                LMS_ContentFiles obj = new LMS_ContentFiles();
                obj.IDB = DCore.Data.CreateData();
                obj.IDB.CreateNewStoredProcedure("LMS_ContentFiles_GetTotalSize");
                obj.IDB.AddParameter("@ContentID", contentId);
                object result = obj.IDB.ExecStoreToScalar();
                obj.IDB.Disconnect();

                if (result != null && result != DBNull.Value)
                {
                    return Convert.ToInt64(result);
                }
                return 0;
            }
            catch (Exception ex)
            {
                return 0;
            }
        }

        #endregion
    }
}

