            obj.IDB = DCore.Data.CreateData();
            obj.IDB.CreateNewStoredProcedure("LMS_ContentProgress_GetByContentAndStudent");
            obj.IDB.AddParameter("@ContentID", contentId);
            obj.IDB.AddParameter("@StudentUserID", studentUserId);
            DataTable dtb = obj.IDB.ExecStoreToDataTable();
            obj.IDB.Disconnect();

            if (dtb != null && dtb.Rows.Count > 0)
            {
                return dtb.Rows[0];
            }
            return null;
        }

        /// <summary>
        /// Lấy tất cả tiến độ của học viên trong một course
        /// </summary>
        /// <param name="rootCourseId">ID của course gốc</param>
        /// <param name="studentUserId">ID của học viên</param>
        /// <returns>DataTable chứa danh sách tiến độ</returns>
        public static DataTable GetStudentProgressByCourse(long rootCourseId, long studentUserId)
        {
            LMS_ContentProgress obj = new LMS_ContentProgress();
            obj.IDB = DCore.Data.CreateData();
            obj.IDB.CreateNewStoredProcedure("LMS_ContentProgress_GetByCourseAndStudent");
            obj.IDB.AddParameter("@RootCourseID", rootCourseId);
            obj.IDB.AddParameter("@StudentUserID", studentUserId);
            DataTable dtb = obj.IDB.ExecStoreToDataTable();
            obj.IDB.Disconnect();
            return dtb;
        }

        /// <summary>
        /// Khởi tạo tiến độ mới cho học viên
        /// </summary>
        /// <param name="contentId">ID của nội dung</param>
        /// <param name="studentUserId">ID của học viên</param>
        /// <param name="enrollmentId">ID của enrollment (tùy chọn)</param>
        /// <returns>ProgressID nếu thành công, 0 nếu thất bại</returns>
        public static long InitProgress(long contentId, long studentUserId, long? enrollmentId = null)
        {
            LMS_ContentProgress obj = new LMS_ContentProgress();
            obj.ContentID = contentId;
            obj.StudentUserID = studentUserId;
            obj.EnrollmentID = enrollmentId;
            obj.ProgressPercent = 0;
            obj.IsCompleted = false;
            obj.TimeSpentSeconds = 0;
            obj.AttemptCount = 0;
            obj.ViewCount = 0;
            obj.DownloadCount = 0;
            obj.CreatedAt = DateTime.UtcNow;
            obj.UpdatedAt = DateTime.UtcNow;

            if (obj.Create())
            {
                HaveNewData = true;
                return obj.ProgressID;
            }
            return 0;
        }

        /// <summary>
        /// Cập nhật tiến độ
        /// </summary>
        /// <param name="contentId">ID của nội dung</param>
        /// <param name="studentUserId">ID của học viên</param>
        /// <param name="progressPercent">Tỷ lệ hoàn thành (0-100)</param>
        /// <param name="timeSpentSeconds">Thời gian học thêm (giây)</param>
        /// <returns>True nếu thành công, False nếu thất bại</returns>
        public static bool UpdateProgress(long contentId, long studentUserId, decimal progressPercent, int timeSpentSeconds = 0)
        {
            try
            {
                LMS_ContentProgress obj = new LMS_ContentProgress();
                DataRow dr = GetProgress(contentId, studentUserId);

                if (dr == null)
                {
                    // Nếu chưa có progress, tạo mới
                    if (InitProgress(contentId, studentUserId) == 0)
                    {
                        return false;
                    }
                    dr = GetProgress(contentId, studentUserId);
                }

                if (dr != null)
                {
                    obj.ProgressID = Convert.ToInt64(dr["ProgressID"]);
                    obj.ProgressPercent = progressPercent;
                    obj.TimeSpentSeconds = Convert.ToInt32(dr["TimeSpentSeconds"]) + timeSpentSeconds;
                    obj.LastAccessAt = DateTime.UtcNow;
                    obj.UpdatedAt = DateTime.UtcNow;

                    // Kiểm tra xem đã hoàn thành chưa
                    if (progressPercent >= 100 && !obj.IsCompleted)
                    {
                        obj.IsCompleted = true;
                        obj.CompletedAt = DateTime.UtcNow;
                    }

                    if (obj.Update())
                    {
                        HaveNewData = true;
                        return true;
                    }
                }
                return false;
            }
            catch (Exception ex)
            {
                return false;
            }
        }

        /// <summary>
        /// Đánh dấu nội dung đã hoàn thành
        /// </summary>
        /// <param name="contentId">ID của nội dung</param>
        /// <param name="studentUserId">ID của học viên</param>
        /// <param name="score">Điểm đạt được (tùy chọn)</param>
        /// <param name="maxScore">Điểm tối đa (tùy chọn)</param>
        /// <param name="passed">Đã đạt hay chưa (tùy chọn)</param>
        /// <returns>True nếu thành công, False nếu thất bại</returns>
        public static bool MarkCompleted(long contentId, long studentUserId, 
            decimal? score = null, decimal? maxScore = null, bool? passed = null)
        {
            try
            {
                LMS_ContentProgress obj = new LMS_ContentProgress();
                DataRow dr = GetProgress(contentId, studentUserId);

                if (dr == null)
                {
                    // Nếu chưa có progress, tạo mới
                    if (InitProgress(contentId, studentUserId) == 0)
                    {
                        return false;
                    }
                    dr = GetProgress(contentId, studentUserId);
                }

                if (dr != null)
                {
                    obj.ProgressID = Convert.ToInt64(dr["ProgressID"]);
                    obj.ProgressPercent = 100;
                    obj.IsCompleted = true;
                    obj.CompletedAt = DateTime.UtcNow;
                    obj.LastAccessAt = DateTime.UtcNow;
                    obj.UpdatedAt = DateTime.UtcNow;

                    if (score.HasValue)
                    {
                        obj.Score = score.Value;
                    }
                    if (maxScore.HasValue)
                    {
                        obj.MaxScore = maxScore.Value;
                    }
                    if (passed.HasValue)
                    {
                        obj.Passed = passed.Value;
                    }

                    if (obj.Update())
                    {
                        HaveNewData = true;
                        return true;
                    }
                }
                return false;
            }
            catch (Exception ex)
            {
                return false;
            }
        }

        /// <summary>
        /// Tăng số lượt xem
        /// </summary>
        /// <param name="contentId">ID của nội dung</param>
        /// <param name="studentUserId">ID của học viên</param>
        /// <returns>True nếu thành công, False nếu thất bại</returns>
