                    }
                }
                return false;
            }
            catch (Exception ex)
            {
                return false;
            }
        }

        /// <summary>
        /// Tăng số lượt tải
        /// </summary>
        /// <param name="contentId">ID của nội dung</param>
        /// <param name="studentUserId">ID của học viên</param>
        /// <returns>True nếu thành công, False nếu thất bại</returns>
