                    {
                        return false;
                    }
                    dr = GetProgress(contentId, studentUserId);
                }

                if (dr != null)
                {
                    obj.ProgressID = Convert.ToInt64(dr["ProgressID"]);
                    obj.AttemptCount = Convert.ToInt32(dr["AttemptCount"]) + 1;
                    obj.LastAccessAt = DateTime.UtcNow;
                    obj.UpdatedAt = DateTime.UtcNow;

                    if (obj.Update())
                    {
                        HaveNewData = true;
                        return true;
                    }
                }
                return false;
            }
            catch (Exception ex)
            {
                return false;
            }
        }

        /// <summary>
        /// Cập nhật ghi chú của học viên
        /// </summary>
        /// <param name="contentId">ID của nội dung</param>
        /// <param name="studentUserId">ID của học viên</param>
        /// <param name="note">Nội dung ghi chú</param>
        /// <returns>True nếu thành công, False nếu thất bại</returns>
        public static bool UpdateStudentNote(long contentId, long studentUserId, string note)
        {
            try
            {
                LMS_ContentProgress obj = new LMS_ContentProgress();
                DataRow dr = GetProgress(contentId, studentUserId);

                if (dr == null)
                {
                    // Nếu chưa có progress, tạo mới
                    if (InitProgress(contentId, studentUserId) == 0)
                    {
                        return false;
                    }
                    dr = GetProgress(contentId, studentUserId);
                }

                if (dr != null)
                {
                    obj.ProgressID = Convert.ToInt64(dr["ProgressID"]);
                    obj.StudentNote = note;
                    obj.UpdatedAt = DateTime.UtcNow;

                    if (obj.Update())
                    {
                        HaveNewData = true;
                        return true;
                    }
                }
                return false;
            }
            catch (Exception ex)
            {
                return false;
            }
        }

        /// <summary>
        /// Tính tổng tiến độ của học viên trong một course
        /// </summary>
        /// <param name="rootCourseId">ID của course gốc</param>
        /// <param name="studentUserId">ID của học viên</param>
        /// <returns>Tỷ lệ hoàn thành trung bình (0-100)</returns>
        public static decimal GetCourseProgress(long rootCourseId, long studentUserId)
        {
            try
            {
                LMS_ContentProgress obj = new LMS_ContentProgress();
                obj.IDB = DCore.Data.CreateData();
                obj.IDB.CreateNewStoredProcedure("LMS_ContentProgress_GetCourseProgress");
                obj.IDB.AddParameter("@RootCourseID", rootCourseId);
                obj.IDB.AddParameter("@StudentUserID", studentUserId);
                object result = obj.IDB.ExecStoreToScalar();
                obj.IDB.Disconnect();

                if (result != null && result != DBNull.Value)
                {
                    return Convert.ToDecimal(result);
                }
                return 0;
            }
            catch (Exception ex)
            {
                return 0;
            }
        }

        /// <summary>
        /// Lấy thống kê chi tiết tiến độ của học viên
        /// </summary>
        /// <param name="rootCourseId">ID của course gốc</param>
        /// <param name="studentUserId">ID của học viên</param>
        /// <returns>DataTable chứa thống kê (tổng content, đã hoàn thành, điểm trung bình, thời gian học)</returns>
        public static DataTable GetStudentProgressStats(long rootCourseId, long studentUserId)
        {
            LMS_ContentProgress obj = new LMS_ContentProgress();
            obj.IDB = DCore.Data.CreateData();
            obj.IDB.CreateNewStoredProcedure("LMS_ContentProgress_GetStats");
            obj.IDB.AddParameter("@RootCourseID", rootCourseId);
            obj.IDB.AddParameter("@StudentUserID", studentUserId);
            DataTable dtb = obj.IDB.ExecStoreToDataTable();
            obj.IDB.Disconnect();
            return dtb;
        }

        #endregion
    }
}

/* =====================================================================
   CONTENT TREE MANAGER CSS
   =====================================================================
   Purpose: Styling cho Content Tree Management UI
   Based on: Existing CMS/LMS design system
   Created by: NgocTrong
   Created date: 20/10/2026
   ===================================================================== */

.content-tree-manager {
  display: grid;
  gap: 1rem;
}

/* ============================================
   TOOLBAR SECTION
   ============================================ */
.tree-toolbar {
  align-items: center;
  background: #fff;
  border: 1px solid var(--neutral-line);
  border-radius: var(--card-radius);
  display: flex;
  gap: 0.75rem;
  justify-content: space-between;
  padding: 0.85rem 1rem;
}

.tree-toolbar-left {
  align-items: center;
  display: flex;
  gap: 0.75rem;
}

.tree-toolbar-right {
  align-items: center;
  display: flex;
  gap: 0.5rem;
}

.tree-search-box {
  position: relative;
  width: 320px;
}

.tree-search-box i {
  color: var(--text-muted);
  left: 0.85rem;
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
}

.tree-search-box .form-control {
  padding-left: 2.3rem;
}

.tree-filter-dropdown {
  min-width: 180px;
}

.tree-eyebrow {
  color: var(--brand-green);
  display: block;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  margin-bottom: 0.35rem;
}

/* ============================================
   MAIN LAYOUT - TREE + DETAILS
   ============================================ */
.tree-layout {
  display: grid;
  gap: 1rem;
  grid-template-columns: minmax(320px, 0.35fr) minmax(0, 0.65fr);
  min-height: 600px;
}

/* ============================================
   TREE PANEL (LEFT)
   ============================================ */
.tree-panel {
  background: #fff;
  border: 1px solid var(--neutral-line);
  border-radius: var(--card-radius);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.tree-panel-header {
  align-items: center;
  background: #f8faf9;
  border-bottom: 1px solid var(--neutral-line);
  display: flex;
  gap: 0.75rem;
  justify-content: space-between;
  padding: 0.85rem 1rem;
}

.tree-panel-header h3 {
  color: var(--text-primary);
  font-size: 0.95rem;
  font-weight: 700;
  margin: 0;
}

.tree-panel-header small {
  color: var(--text-muted);
  font-size: 0.75rem;
}

.tree-panel-actions {
  display: flex;
  gap: 0.4rem;
}

.tree-content {
  flex: 1;
  overflow: auto;
  padding: 0.5rem;
}

/* ============================================
   TREE NODE STYLING
   ============================================ */
.tree-node {
  border-radius: 8px;
  display: grid;
  gap: 0.4rem;
  padding: 0.6rem 0.75rem;
  transition: background 0.18s ease;
}

.tree-node:hover {
  background: rgba(var(--brand-green-rgb), 0.05);
}

.tree-node.selected {
  background: rgba(var(--brand-green-rgb), 0.1);
  border: 1px solid var(--brand-green);
}

.tree-node-header {
  align-items: center;
  display: flex;
  gap: 0.6rem;
}

.tree-node-toggle {
  align-items: center;
  background: transparent;
  border: 0;
  color: var(--text-muted);
  cursor: pointer;
  display: inline-flex;
  flex: 0 0 24px;
  height: 24px;
  justify-content: center;
  transition: transform 0.18s ease;
  width: 24px;
}

.tree-node-toggle:hover {
  color: var(--brand-green);
}

.tree-node-toggle.expanded {
  transform: rotate(90deg);
}

.tree-node-icon {
  align-items: center;
  color: var(--brand-blue);
  display: grid;
  flex: 0 0 32px;
  font-size: 1.1rem;
  height: 32px;
  justify-content: center;
  width: 32px;
}

.tree-node-icon.type-course {
  color: var(--brand-green);
}

.tree-node-icon.type-chapter {
  color: var(--brand-blue);
}

.tree-node-icon.type-lesson {
  color: var(--brand-success);
}

.tree-node-icon.type-quiz {
  color: #7452bd;
}

.tree-node-icon.type-assignment {
  color: #e87500;
}

.tree-node-icon.type-video {
  color: #1976bd;
}

.tree-node-icon.type-document {
  color: #d93b42;
}

.tree-node-info {
  display: grid;
  flex: 1;
  min-width: 0;
}

.tree-node-title {
  color: var(--text-primary);
  font-size: 0.85rem;
  font-weight: 600;
  margin: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tree-node-meta {
  align-items: center;
  display: flex;
  gap: 0.5rem;
  font-size: 0.72rem;
}

.tree-node-meta span {
