}

.tree-node-meta .badge {
  background: rgba(var(--brand-blue-rgb), 0.1);
  border-radius: 4px;
  color: var(--brand-blue);
  font-size: 0.7rem;
  font-weight: 600;
  padding: 0.2rem 0.5rem;
}

.tree-node-meta .badge.published {
  background: rgba(var(--brand-success-rgb), 0.1);
  color: var(--brand-success);
}

.tree-node-meta .badge.draft {
  background: rgba(var(--brand-yellow-rgb), 0.15);
