.file-item-actions .btn {
  align-items: center;
  background: transparent;
  border: 0;
  color: var(--text-muted);
  display: grid;
  height: 28px;
  justify-content: center;
  padding: 0;
  width: 28px;
}

.file-item-actions .btn:hover {
  background: rgba(var(--brand-green-rgb), 0.1);
  color: var(--brand-green);
}

.file-item-actions .btn-delete:hover {
  background: rgba(var(--brand-red-rgb), 0.1);
  color: var(--brand-red);
}

.file-item.primary {
  border-color: var(--brand-success);
  background: rgba(var(--brand-success-rgb), 0.05);
}

.file-item.primary .file-item-icon {
  background: var(--brand-success);
  color: #fff;
}

/* ============================================
   PROGRESS INDICATOR IN DETAILS
   ============================================ */
.progress-stats {
  background: #f8faf9;
  border: 1px solid var(--neutral-line);
  border-radius: 8px;
  display: grid;
  gap: 0.75rem;
  padding: 1rem;
}

.progress-stat-item {
  align-items: center;
  display: flex;
  gap: 0.75rem;
}

.progress-stat-icon {
  align-items: center;
  background: rgba(var(--brand-green-rgb), 0.1);
  border-radius: 8px;
  color: var(--brand-green);
  display: grid;
  flex: 0 0 40px;
  font-size: 1.1rem;
  height: 40px;
  justify-content: center;
  width: 40px;
}

.progress-stat-info {
  display: grid;
  flex: 1;
}

.progress-stat-value {
  color: var(--text-primary);
  font-size: 1.25rem;
  font-weight: 700;
  line-height: 1;
}

.progress-stat-label {
  color: var(--text-muted);
  font-size: 0.75rem;
  margin-top: 0.2rem;
}

/* ============================================
   ACTION BUTTONS
   ============================================ */
.details-actions {
  border-top: 1px solid var(--neutral-line);
  display: flex;
  gap: 0.6rem;
  justify-content: flex-end;
  padding: 1rem;
}

.btn-add-node {
  align-items: center;
  background: var(--brand-success);
  border-color: var(--brand-success);
  color: #fff;
  display: inline-flex;
  gap: 0.4rem;
}

.btn-add-node:hover,
.btn-add-node:focus {
  background: var(--brand-success-dark);
  border-color: var(--brand-success-dark);
  color: #fff;
}

.btn-refresh-tree {
  align-items: center;
  background: transparent;
  border: 1px solid var(--neutral-line);
  color: var(--text-secondary);
  display: inline-flex;
  gap: 0.4rem;
}

.btn-refresh-tree:hover,
.btn-refresh-tree:focus {
  background: rgba(var(--brand-green-rgb), 0.05);
  border-color: var(--brand-green);
  color: var(--brand-green);
}

/* ============================================
   CONTEXT MENU
   ============================================ */
.tree-context-menu {
  background: #fff;
  border: 1px solid var(--neutral-line);
  border-radius: var(--control-radius);
  box-shadow: 0 8px 24px rgba(18, 53, 82, 0.15);
  display: grid;
  gap: 0.15rem;
  min-width: 180px;
  padding: 0.4rem;
  position: absolute;
  z-index: 1000;
}

.tree-context-menu button {
  align-items: center;
  background: transparent;
  border: 0;
  color: var(--text-secondary);
  display: flex;
  gap: 0.6rem;
  font-size: 0.82rem;
  padding: 0.5rem 0.65rem;
  text-align: left;
  width: 100%;
}

.tree-context-menu button:hover {
  background: rgba(var(--brand-green-rgb), 0.08);
  color: var(--brand-green);
}

.tree-context-menu button.danger:hover {
  background: rgba(var(--brand-red-rgb), 0.08);
  color: var(--brand-red);
}

.tree-context-menu-divider {
  border-top: 1px solid var(--neutral-line);
  margin: 0.35rem 0;
}

/* ============================================
   RESPONSIVE DESIGN
   ============================================ */
@media (max-width: 1200px) {
  .tree-layout {
    grid-template-columns: minmax(280px, 0.4fr) minmax(0, 0.6fr);
  }
}

@media (max-width: 991.98px) {
  .tree-layout {
    grid-template-columns: 1fr;
  }

  .tree-panel {
    max-height: 400px;
  }

  .details-panel {
    min-height: 400px;
  }

  .tree-toolbar {
    flex-wrap: wrap;
  }

  .tree-search-box {
    width: 100%;
  }

  .form-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 575.98px) {
  .tree-toolbar-left,
  .tree-toolbar-right {
    width: 100%;
    justify-content: space-between;
  }

  .tree-panel-header,
  .details-panel-header {
    flex-wrap: wrap;
  }

  .details-actions {
    flex-wrap: wrap;
  }

  .details-actions .btn {
    flex: 1;
  }
}

/* =====================================================================
   CONTENT FILE UPLOAD CSS
   =====================================================================
   Purpose: Styling cho File Upload UI cho Content Tree
   Based on: Existing CMS/LMS design system
   Created by: NgocTrong
   Created date: 20/10/2026
   ===================================================================== */

.file-upload-manager {
  display: grid;
  gap: 1rem;
}

/* ============================================
   UPLOAD AREA
   ============================================ */
.upload-area {
  align-items: center;
  background: #f8faf9;
  border: 2px dashed var(--neutral-line);
  border-radius: var(--card-radius);
  display: flex;
  flex-direction: column;
  gap: 1rem;
  justify-content: center;
  min-height: 200px;
  padding: 2rem;
  transition: border-color 0.18s ease, background 0.18s ease;
}

.upload-area:hover,
.upload-area.dragover {
  border-color: var(--brand-green);
  background: rgba(var(--brand-green-rgb), 0.03);
}

.upload-area-icon {
  align-items: center;
  background: rgba(var(--brand-green-rgb), 0.1);
  border-radius: 50%;
  color: var(--brand-green);
  display: grid;
  font-size: 2.5rem;
  height: 80px;
  justify-content: center;
  width: 80px;
}

.upload-area-text {
  text-align: center;
}

.upload-area-text h4 {
  color: var(--text-primary);
  font-size: 1.1rem;
  font-weight: 700;
  margin: 0 0 0.5rem;
}

.upload-area-text p {
  color: var(--text-muted);
  font-size: 0.9rem;
  margin: 0;
}

.upload-area-text small {
  color: var(--text-disabled);
  display: block;
  font-size: 0.75rem;
  margin-top: 0.5rem;
}

.btn-browse-files {
  align-items: center;
  background: var(--brand-green);
  border-color: var(--brand-green);
  color: #fff;
  display: inline-flex;
  gap: 0.4rem;
  justify-content: center;
  margin-top: 0.5rem;
}

.btn-browse-files:hover,
.btn-browse-files:focus {
  background: var(--brand-green-dark);
  border-color: var(--brand-green-dark);
  color: #fff;
}

/* ============================================
   FILE LIST
   ============================================ */
.file-upload-list {
  display: grid;
  gap: 0.6rem;
}

.file-upload-item {
  align-items: center;
  background: #fff;
  border: 1px solid var(--neutral-line);
  border-radius: 8px;
  display: flex;
  gap: 0.75rem;
  padding: 0.85rem 1rem;
}

.file-upload-item.uploading {
  background: #f8faf9;
  border-style: dashed;
}

.file-upload-item.completed {
  border-color: var(--brand-success);
}

.file-upload-item.error {
  border-color: var(--brand-red);
  background: #fef2f2;
}

.file-upload-item-icon {
  align-items: center;
  background: rgba(var(--brand-blue-rgb), 0.1);
  border-radius: 8px;
  color: var(--brand-blue);
  display: grid;
  flex: 0 0 42px;
  font-size: 1.2rem;
  height: 42px;
  justify-content: center;
  width: 42px;
}

.file-upload-item-icon.type-pdf {
  color: #d93b42;
  background: rgba(217, 59, 66, 0.1);
}

.file-upload-item-icon.type-video {
  color: #1976bd;
  background: rgba(25, 118, 189, 0.1);
}

.file-upload-item-icon.type-image {
  color: #008fa8;
  background: rgba(0, 143, 168, 0.1);
}

.file-upload-item-icon.type-zip {
  color: #e87500;
  background: rgba(232, 117, 0, 0.1);
}

.file-upload-item-info {
  display: grid;
  flex: 1;
  gap: 0.25rem;
  min-width: 0;
}

.file-upload-item-name {
  color: var(--text-primary);
  font-size: 0.88rem;
  font-weight: 600;
  margin: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.file-upload-item-meta {
  align-items: center;
  color: var(--text-muted);
  display: flex;
  gap: 0.75rem;
  font-size: 0.75rem;
}

.file-upload-item-meta span {
  display: flex;
  align-items: center;
  gap: 0.3rem;
}

.file-upload-item-progress {
  width: 100%;
}

.file-upload-item-progress-bar {
  background: #e9ecef;
  border-radius: 4px;
  height: 6px;
  overflow: hidden;
  width: 100%;
}

.file-upload-item-progress-fill {
  background: var(--brand-green);
  height: 100%;
  transition: width 0.3s ease;
}

.file-upload-item-progress-fill.error {
  background: var(--brand-red);
}

.file-upload-item-status {
  align-items: center;
  color: var(--text-muted);
  display: flex;
  font-size: 0.75rem;
  gap: 0.4rem;
}

.file-upload-item-status.completed {
  color: var(--brand-success);
}

.file-upload-item-status.error {
  color: var(--brand-red);
}

.file-upload-item-actions {
  display: flex;
  gap: 0.3rem;
}

.file-upload-item-actions .btn {
  align-items: center;
  background: transparent;
  border: 0;
  color: var(--text-muted);
  display: grid;
  height: 32px;
  justify-content: center;
  padding: 0;
  width: 32px;
}

.file-upload-item-actions .btn:hover {
  background: rgba(var(--brand-green-rgb), 0.1);
  color: var(--brand-green);
}

.file-upload-item-actions .btn-delete:hover {
  background: rgba(var(--brand-red-rgb), 0.1);
  color: var(--brand-red);
}

/* ============================================
   FILE PREVIEW
   ============================================ */
.file-preview {
  background: #fff;
  border: 1px solid var(--neutral-line);
  border-radius: var(--card-radius);
  overflow: hidden;
}

.file-preview-header {
  align-items: center;
  background: #f8faf9;
  border-bottom: 1px solid var(--neutral-line);
  display: flex;
  gap: 0.75rem;
  justify-content: space-between;
  padding: 0.85rem 1rem;
}

.file-preview-header h4 {
  color: var(--text-primary);
  font-size: 0.9rem;
  font-weight: 700;
  margin: 0;
}

.file-preview-content {
  align-items: center;
  display: flex;
  justify-content: center;
  min-height: 200px;
  padding: 1.5rem;
}

.file-preview-content img {
  max-height: 300px;
  max-width: 100%;
  object-fit: contain;
}

.file-preview-content video {
  max-height: 300px;
  max-width: 100%;
}

.file-preview-placeholder {
  align-items: center;
  color: var(--text-muted);
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  text-align: center;
}

.file-preview-placeholder i {
  font-size: 3rem;
}

.file-preview-placeholder span {
  font-size: 0.9rem;
}

/* ============================================
   FILE SETTINGS
   ============================================ */
.file-settings {
  background: #fff;
  border: 1px solid var(--neutral-line);
  border-radius: var(--card-radius);
  display: grid;
  gap: 1rem;
  padding: 1.25rem;
}

.file-settings-section {
  display: grid;
  gap: 0.75rem;
}

.file-settings-section h5 {
  color: var(--brand-green);
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  margin: 0;
  text-transform: uppercase;
}

.file-settings-grid {
  display: grid;
  gap: 0.85rem;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.file-settings-grid.full-width {
  grid-template-columns: 1fr;
}

.file-setting-field {
  display: grid;
  gap: 0.35rem;
}

.file-setting-field label {
  color: var(--text-secondary);
  font-size: 0.8rem;
  font-weight: 600;
}

.file-setting-field .form-control,
.file-setting-field select {
  border: 1px solid var(--neutral-line);
  border-radius: var(--control-radius);
  padding: 0.6rem 0.85rem;
  font-size: 0.85rem;
}

.file-setting-field .form-control:focus,
.file-setting-field select:focus {
  border-color: var(--brand-green);
  box-shadow: 0 0 0 3px rgba(var(--brand-green-rgb), 0.1);
  outline: 0;
}

.file-setting-field small {
  color: var(--text-muted);
  font-size: 0.72rem;
}

/* ============================================
   PRIMARY FILE TOGGLE
   ============================================ */
.primary-file-toggle {
  align-items: center;
  background: #f8faf9;
  border: 1px solid var(--neutral-line);
  border-radius: 8px;
  display: flex;
  gap: 0.75rem;
  padding: 0.85rem 1rem;
}

.primary-file-toggle.active {
  background: rgba(var(--brand-success-rgb), 0.05);
  border-color: var(--brand-success);
}

.primary-file-toggle-icon {
  align-items: center;
  background: var(--brand-success);
  border-radius: 50%;
  color: #fff;
  display: grid;
  flex: 0 0 32px;
  font-size: 0.9rem;
  height: 32px;
  justify-content: center;
  width: 32px;
}

.primary-file-toggle:not(.active) .primary-file-toggle-icon {
  background: var(--neutral-line);
  color: var(--text-muted);
}

.primary-file-toggle-info {
  display: grid;
  flex: 1;
}

.primary-file-toggle-info strong {
  color: var(--text-primary);
  font-size: 0.85rem;
  font-weight: 600;
  margin: 0;
}

.primary-file-toggle-info small {
  color: var(--text-muted);
  font-size: 0.72rem;
}

.primary-file-toggle-switch {
  flex: 0 0 auto;
}

/* ============================================
   FILE TYPE BADGES
   ============================================ */
.file-type-badge {
  align-items: center;
  background: rgba(var(--brand-blue-rgb), 0.1);
  border-radius: 4px;
  color: var(--brand-blue);
  display: inline-flex;
  font-size: 0.7rem;
  font-weight: 600;
  gap: 0.3rem;
  padding: 0.25rem 0.5rem;
}

.file-type-badge.type-pdf {
  background: rgba(217, 59, 66, 0.1);
  color: #d93b42;
}

.file-type-badge.type-video {
  background: rgba(25, 118, 189, 0.1);
  color: #1976bd;
}

.file-type-badge.type-image {
  background: rgba(0, 143, 168, 0.1);
  color: #008fa8;
}

.file-type-badge.type-zip {
  background: rgba(232, 117, 0, 0.1);
  color: #e87500;
}

.file-type-badge.type-audio {
  background: rgba(116, 82, 189, 0.1);
  color: #7452bd;
}

/* ============================================
   RESPONSIVE DESIGN
   ============================================ */
@media (max-width: 991.98px) {
  .file-settings-grid {
    grid-template-columns: 1fr;
  }

  .file-upload-item {
    flex-wrap: wrap;
  }

  .file-upload-item-info {
    flex: 1;
    min-width: 200px;
  }

  .file-upload-item-actions {
    width: 100%;
    justify-content: flex-end;
  }
}

@media (max-width: 575.98px) {
  .upload-area {
    min-height: 150px;
    padding: 1.5rem;
  }

  .upload-area-icon {
    height: 60px;
    width: 60px;
    font-size: 2rem;
  }

  .file-upload-item {
    grid-template-columns: 42px 1fr;
  }

  .file-upload-item-meta {
    grid-column: 2;
  }

  .file-upload-item-progress {
    grid-column: 2;
  }

  .file-upload-item-actions {
    grid-column: 2;
  }
}

/* =====================================================================
   CONTENT PROGRESS DASHBOARD CSS
   =====================================================================
   Purpose: Styling cho Progress Dashboard UI cho Content Tree
   Based on: Existing CMS/LMS design system
   Created by: NgocTrong
   Created date: 20/10/2026
   ===================================================================== */

.progress-dashboard {
  display: grid;
  gap: 1rem;
}

/* ============================================
   DASHBOARD HEADER
   ============================================ */
.dashboard-header {
  align-items: flex-end;
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  justify-content: space-between;
  margin-bottom: 0.5rem;
}

.dashboard-header h1 {
  color: var(--text-primary);
  font-size: clamp(1.55rem, 2.2vw, 2rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  margin: 0 0 0.25rem;
}

.dashboard-header p {
  color: var(--text-muted);
  font-size: 0.9rem;
  margin: 0;
}

.dashboard-actions {
  align-items: center;
  display: flex;
  gap: 0.5rem;
}

/* ============================================
   METRIC CARDS
   ============================================ */
.metric-grid {
  display: grid;
  gap: 1rem;
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.metric-card {
  background: #fff;
  border: 1px solid var(--neutral-line);
  border-radius: var(--card-radius);
  display: grid;
  gap: 0.5rem;
  padding: 1.25rem;
}

.metric-card-header {
  align-items: center;
  display: flex;
  gap: 0.75rem;
}

.metric-card-icon {
  align-items: center;
  background: rgba(var(--brand-green-rgb), 0.1);
  border-radius: 8px;
  color: var(--brand-green);
  display: grid;
  flex: 0 0 40px;
  font-size: 1.1rem;
  height: 40px;
  justify-content: center;
  width: 40px;
}

.metric-card-icon.icon-blue {
  background: rgba(var(--brand-blue-rgb), 0.1);
  color: var(--brand-blue);
}

.metric-card-icon.icon-success {
  background: rgba(var(--brand-success-rgb), 0.1);
  color: var(--brand-success);
}

.metric-card-icon.icon-warning {
  background: rgba(var(--brand-yellow-rgb), 0.15);
  color: #b38600;
}

.metric-card-info {
  display: grid;
  flex: 1;
}

.metric-card-title {
  color: var(--text-secondary);
  font-size: 0.75rem;
  font-weight: 600;
  margin: 0;
}

.metric-card-value {
  color: var(--text-primary);
  font-size: 1.75rem;
  font-weight: 800;
  line-height: 1;
  margin: 0.15rem 0 0;
}

.metric-card-trend {
  align-items: center;
  color: var(--brand-success);
  display: flex;
  font-size: 0.75rem;
  font-weight: 600;
  gap: 0.25rem;
  margin-top: 0.25rem;
}

.metric-card-trend.down {
  color: var(--brand-red);
}

/* ============================================
   DASHBOARD FILTERS
   ============================================ */
.dashboard-filters {
  align-items: center;
  background: #fff;
  border: 1px solid var(--neutral-line);
  border-radius: var(--card-radius);
  display: flex;
  gap: 0.75rem;
  padding: 0.85rem 1rem;
}

.dashboard-filters-label {
  color: var(--text-secondary);
  font-size: 0.8rem;
  font-weight: 600;
  white-space: nowrap;
}

.dashboard-filters-group {
  align-items: center;
  display: flex;
  gap: 0.5rem;
  flex: 1;
}

.dashboard-filters .form-control,
.dashboard-filters select {
  border: 1px solid var(--neutral-line);
  border-radius: var(--control-radius);
  padding: 0.5rem 0.75rem;
  font-size: 0.85rem;
  min-width: 150px;
}

.dashboard-filters .form-control:focus,
.dashboard-filters select:focus {
  border-color: var(--brand-green);
  box-shadow: 0 0 0 3px rgba(var(--brand-green-rgb), 0.1);
  outline: 0;
}

/* ============================================
   PROGRESS TABLE
   ============================================ */
.progress-table-card {
  background: #fff;
  border: 1px solid var(--neutral-line);
  border-radius: var(--card-radius);
  overflow: hidden;
}

.progress-table-header {
  align-items: center;
  background: #f8faf9;
  border-bottom: 1px solid var(--neutral-line);
  display: flex;
  gap: 0.75rem;
  justify-content: space-between;
  padding: 0.85rem 1rem;
}

.progress-table-header h3 {
  color: var(--text-primary);
  font-size: 0.95rem;
  font-weight: 700;
  margin: 0;
}

.progress-table-header small {
  color: var(--text-muted);
  font-size: 0.75rem;
}

.progress-table-actions {
  display: flex;
  gap: 0.4rem;
}

.table-responsive {
  border-radius: inherit;
}

.progress-table {
  margin-bottom: 0;
  color: var(--text-primary);
}

.progress-table thead th {
  background: var(--brand-green);
  border-bottom-color: var(--brand-green);
  color: #fff;
  font-size: 0.76rem;
  font-weight: 700;
  letter-spacing: 0.045em;
  padding: 0.9rem 1rem;
  text-transform: uppercase;
  white-space: nowrap;
}

.progress-table tbody td {
  border-bottom-color: var(--neutral-line);
  font-size: 0.82rem;
  padding: 0.9rem 1rem;
  vertical-align: middle;
}

.progress-table tbody tr:hover td {
  background: rgba(var(--brand-green-rgb), 0.05);
}

/* ============================================
   PROGRESS BAR IN TABLE
   ============================================ */
.progress-bar-cell {
  min-width: 150px;
}

.progress-bar-wrapper {
  background: #e9ecef;
  border-radius: 4px;
  height: 8px;
  overflow: hidden;
  width: 100%;
}

.progress-bar-fill {
  background: var(--brand-success);
  height: 100%;
  transition: width 0.3s ease;
}

.progress-bar-fill.warning {
  background: var(--brand-yellow);
}

.progress-bar-fill.danger {
  background: var(--brand-red);
}

.progress-bar-text {
