    /// Created date    : 20/10/2026
    /// Description     : Content Tree Manager - Quản lý cấu trúc cây nội dung
    /// </summary>
    public partial class ContentTreeManager : System.Web.UI.Page
    {
        #region Page Events

        protected void Page_Load(object sender, EventArgs e)
        {
            if (!IsPostBack)
            {
                LoadContentTree();
                UpdateTotalNodes();
            }
        }

        #endregion

        #region Tree Operations

        /// <summary>
        /// Load nội dung vào TreeView
        /// </summary>
        private void LoadContentTree()
        {
            try
            {
                // Lấy tất cả course (root nodes)
                DataTable dtbCourses = LMS_ContentTreeService.GetTable();

                // Filter nếu có search
                if (!string.IsNullOrEmpty(txtSearch.Text))
                {
                    dtbCourses.DefaultView.RowFilter = "ContentName LIKE '%" + txtSearch.Text + "%'";
                }

                // Filter theo type
                if (!string.IsNullOrEmpty(ddlFilterType.SelectedValue))
                {
                    if (dtbCourses.DefaultView.RowFilter == "")
                    {
                        dtbCourses.DefaultView.RowFilter = "ContentType = '" + ddlFilterType.SelectedValue + "'";
                    }
                    else
                    {
                        dtbCourses.DefaultView.RowFilter += " AND ContentType = '" + ddlFilterType.SelectedValue + "'";
                    }
                }

                // Filter theo status
                if (!string.IsNullOrEmpty(ddlFilterStatus.SelectedValue))
                {
                    if (dtbCourses.DefaultView.RowFilter == "")
                    {
                        dtbCourses.DefaultView.RowFilter = "Status = '" + ddlFilterStatus.SelectedValue + "'";
                    }
                    else
                    {
                        dtbCourses.DefaultView.RowFilter += " AND Status = '" + ddlFilterStatus.SelectedValue + "'";
                    }
                }

                tvContentTree.Nodes.Clear();

                foreach (DataRow dr in dtbCourses.Rows)
                {
                    TreeViewNode node = CreateTreeNode(dr);
                    tvContentTree.Nodes.Add(node);

                    // Load children recursively
                    LoadChildren(node, Convert.ToInt64(dr["ContentID"]));
                }
            }
            catch (Exception ex)
            {
                ShowStatus("Lỗi load cây nội dung: " + ex.Message, false);
            }
        }

        /// <summary>
        /// Load children của một node
        /// </summary>
        private void LoadChildren(TreeViewNode parentNode, long parentID)
        {
            try
            {
                DataTable dtbChildren = LMS_ContentTreeService.GetChildren(parentID);

                foreach (DataRow dr in dtbChildren.Rows)
                {
                    TreeViewNode childNode = CreateTreeNode(dr);
                    parentNode.Nodes.Add(childNode);

                    // Load children recursively
                    LoadChildren(childNode, Convert.ToInt64(dr["ContentID"]));
                }
            }
            catch (Exception ex)
            {
                ShowStatus("Lỗi load children: " + ex.Message, false);
            }
        }

        /// <summary>
        /// Tạo TreeViewNode từ DataRow
        /// </summary>
        private TreeViewNode CreateTreeNode(DataRow dr)
        {
            TreeViewNode node = new TreeViewNode();

            long contentID = Convert.ToInt64(dr["ContentID"]);
            string contentName = dr["ContentName"].ToString();
            string contentType = dr["ContentType"].ToString();
            string status = dr["Status"].ToString();

            node.Name = contentID.ToString();
            node.Text = contentName;
            node.Value = contentID;

            // Set icon dựa trên contentType
            node.ImageUrl = GetIconByType(contentType);

            // Set tooltip
            node.ToolTip = string.Format("{0} - {1}", contentType, contentName);

            // Set expanded mặc định cho Course và Chapter
            if (contentType == "COURSE" || contentType == "CHAPTER")
            {
                node.Expanded = true;
            }

            return node;
        }

        /// <summary>
        /// Lấy icon URL dựa trên content type
        /// </summary>
        private string GetIconByType(string contentType)
        {
            switch (contentType.ToUpper())
            {
                case "COURSE":
                    return "/assets/images/icons/course.png";
                case "CHAPTER":
                    return "/assets/images/icons/chapter.png";
                case "LESSON":
                    return "/assets/images/icons/lesson.png";
                case "QUIZ":
                    return "/assets/images/icons/quiz.png";
                case "ASSIGNMENT":
                    return "/assets/images/icons/assignment.png";
                case "DOCUMENT":
                    return "/assets/images/icons/document.png";
                default:
                    return "/assets/images/icons/default.png";
            }
        }

        /// <summary>
        /// Update tổng số nodes
        /// </summary>
        private void UpdateTotalNodes()
        {
            try
            {
                DataTable dtb = LMS_ContentTreeService.GetTable();
                lblTotalNodes.Text = dtb.Rows.Count + " node";
            }
            catch (Exception ex)
            {
                lblTotalNodes.Text = "0 node";
            }
        }

        #endregion

        #region Toolbar Events

        protected void txtSearch_TextChanged(object sender, EventArgs e)
        {
            LoadContentTree();
        }

        protected void ddlFilterType_SelectedIndexChanged(object sender, EventArgs e)
        {
