            ddlFilterStatus.SelectedIndex = 0;
            LoadContentTree();
            UpdateTotalNodes();
            ShowStatus("Đã làm mới cây nội dung", true);
        }

        protected void btnExpandAll_Click(object sender, EventArgs e)
        {
            tvContentTree.ExpandAll();
        }

        protected void btnCollapseAll_Click(object sender, EventArgs e)
        {
            tvContentTree.CollapseAll();
        }

        #endregion

        #region TreeView Events

        protected void tvContentTree_NodeClick(object sender, DevExpress.Web.DataViewNodeEventArgs e)
        {
            try
            {
                long contentID = Convert.ToInt64(e.Node.Value);
                LoadNodeDetails(contentID);
            }
            catch (Exception ex)
            {
                ShowStatus("Lỗi load chi tiết: " + ex.Message, false);
            }
        }

        protected void tvContentTree_NodeDragDrop(object sender, DevExpress.Web.ASPxTreeViewNodeDragDropEventArgs e)
        {
            try
            {
                long contentID = Convert.ToInt64(e.SourceNode.Value);
                long? newParentID = null;

                if (e.TargetNode != null)
                {
                    newParentID = Convert.ToInt64(e.TargetNode.Value);
                }

                // Move node
                bool success = LMS_ContentTreeService.MoveNode(contentID, newParentID ?? 0, 0, GetCurrentUserID());

                if (success)
                {
                    LoadContentTree();
                    ShowStatus("Đã di chuyển node thành công", true);
                }
                else
                {
                    ShowStatus("Lỗi di chuyển node", false);
                }
            }
            catch (Exception ex)
            {
                ShowStatus("Lỗi di chuyển node: " + ex.Message, false);
            }
        }

        #endregion

        #region Node Operations

        protected void btnCreateCourse_Click(object sender, EventArgs e)
        {
            ClearDetailsForm();
            pnlEmptyState.Visible = false;
            pnlDetails.Visible = true;

            ddlContentType.SelectedValue = "COURSE";
            ddlContentSubType.SelectedValue = "";
            ddlStatus.SelectedValue = "ACTIVE";

            btnSave.Visible = true;
            btnCancel.Visible = true;
            btnAddChild.Visible = false;
            btnDelete.Visible = false;

            pnlQuizSettings.Visible = false;
        }

        protected void btnAddRoot_Click(object sender, EventArgs e)
        {
            btnCreateCourse_Click(sender, e);
        }

        protected void btnAddChild_Click(object sender, EventArgs e)
        {
            try
            {
                long parentID = Convert.ToInt64(hfContentID.Value);
                string parentType = hfContentType.Value;

                // Xác định type mặc định cho child
                string defaultChildType = GetDefaultChildType(parentType);

                ClearDetailsForm();
                pnlEmptyState.Visible = false;
                pnlDetails.Visible = true;

                hfParentID.Value = parentID.ToString();
                ddlContentType.SelectedValue = defaultChildType;
                ddlContentSubType.SelectedValue = "";
                ddlStatus.SelectedValue = "ACTIVE";

                btnSave.Visible = true;
                btnCancel.Visible = true;
                btnAddChild.Visible = false;
                btnDelete.Visible = false;

                pnlQuizSettings.Visible = (defaultChildType == "QUIZ" || defaultChildType == "ASSIGNMENT");
            }
            catch (Exception ex)
            {
                ShowStatus("Lỗi thêm con: " + ex.Message, false);
            }
        }

        protected void btnSave_Click(object sender, EventArgs e)
        {
            try
            {
                LMS_ContentTree obj = new LMS_ContentTree();

                obj.ContentName = txtContentName.Text.Trim();
                obj.ContentSlug = txtContentSlug.Text.Trim();
                obj.Description = txtDescription.Text.Trim();
                obj.ContentType = ddlContentType.SelectedValue;
                obj.ContentSubType = ddlContentSubType.SelectedValue;
                obj.SortOrder = string.IsNullOrEmpty(txtSortOrder.Text) ? 0 : Convert.ToInt32(txtSortOrder.Text);
                obj.Icon = txtIcon.Text.Trim();
                obj.Color = txtColor.Text.Trim();
                obj.Thumbnail = txtThumbnail.Text.Trim();
                obj.Status = ddlStatus.SelectedValue;
                obj.EstimatedMinutes = string.IsNullOrEmpty(txtEstimatedMinutes.Text) ? (int?)null : Convert.ToInt32(txtEstimatedMinutes.Text);
                obj.IsPublished = chkIsPublished.Checked;
                obj.IsFree = chkIsFree.Checked;
                obj.IsRequired = chkIsRequired.Checked;
                obj.AllowPreview = chkAllowPreview.Checked;
                obj.LockPrevious = chkLockPrevious.Checked;
                obj.CreatedByUserID = GetCurrentUserID();
                obj.CreatedAt = DateTime.UtcNow;

                // Quiz/Assignment settings
                if (ddlContentType.SelectedValue == "QUIZ" || ddlContentType.SelectedValue == "ASSIGNMENT")
                {
                    obj.MaxScore = string.IsNullOrEmpty(txtMaxScore.Text) ? (decimal?)null : Convert.ToDecimal(txtMaxScore.Text);
                    obj.PassingScore = string.IsNullOrEmpty(txtPassingScore.Text) ? (decimal?)null : Convert.ToDecimal(txtPassingScore.Text);
                    obj.MaxAttempts = string.IsNullOrEmpty(txtMaxAttempts.Text) ? (int?)null : Convert.ToInt32(txtMaxAttempts.Text);
                    obj.TimeLimitMinutes = string.IsNullOrEmpty(txtTimeLimitMinutes.Text) ? (int?)null : Convert.ToInt32(txtTimeLimitMinutes.Text);
                    obj.ShuffleQuestions = chkShuffleQuestions.Checked;
                    obj.ShowResultAfterSubmit = chkShowResultAfterSubmit.Checked;
                }

                long contentID;

                if (!string.IsNullOrEmpty(hfContentID.Value))
                {
                    // Update existing
                    contentID = Convert.ToInt64(hfContentID.Value);
                    obj.ContentID = contentID;
                    obj.UpdatedByUserID = GetCurrentUserID();
                    obj.UpdatedAt = DateTime.UtcNow;

                    if (obj.Update())
                    {
                        ShowStatus("Đã cập nhật nội dung thành công", true);
                    }
                    else
                    {
                        ShowStatus("Lỗi cập nhật nội dung", false);
                        return;
                    }
                }
                else
                {
                    // Create new
                    if (!string.IsNullOrEmpty(hfParentID.Value))
                    {
                        obj.ParentID = Convert.ToInt64(hfParentID.Value);
                    }

                    if (obj.Create())
                    {
                        contentID = obj.ContentID;
                        ShowStatus("Đã tạo nội dung mới thành công", true);
                    }
                    else
                    {
                        ShowStatus("Lỗi tạo nội dung mới", false);
                        return;
                    }
                }

                // Refresh tree and load details
                LoadContentTree();
                LoadNodeDetails(contentID);
            }
            catch (Exception ex)
            {
                ShowStatus("Lỗi lưu: " + ex.Message, false);
            }
        }

        protected void btnCancel_Click(object sender, EventArgs e)
        {
            pnlEmptyState.Visible = true;
            pnlDetails.Visible = false;
            ClearDetailsForm();
        }

        protected void btnDelete_Click(object sender, EventArgs e)
        {
            try
            {
                long contentID = Convert.ToInt64(hfContentID.Value);

                bool success = LMS_ContentTreeService.DeleteNode(contentID, true, true, GetCurrentUserID());

                if (success)
                {
                    LoadContentTree();
                    pnlEmptyState.Visible = true;
                    pnlDetails.Visible = false;
                    ClearDetailsForm();
                    ShowStatus("Đã xóa nội dung thành công", true);
                }
                else
                {
                    ShowStatus("Lỗi xóa nội dung", false);
                }
            }
            catch (Exception ex)
            {
                ShowStatus("Lỗi xóa: " + ex.Message, false);
            }
        }

        #endregion

        #region Helper Methods

        /// <summary>
        /// Load chi tiết node vào form
        /// </summary>
        private void LoadNodeDetails(long contentID)
        {
            try
            {
                LMS_ContentTree obj = new LMS_ContentTree();
                obj.IDB = DCore.Data.CreateData();
                obj.IDB.CreateNewStoredProcedure("LMS_ContentTree_GetByID");
                obj.IDB.AddParameter("@ContentID", contentID);
                DataTable dtb = obj.IDB.ExecStoreToDataTable();
                obj.IDB.Disconnect();

                if (dtb != null && dtb.Rows.Count > 0)
                {
                    DataRow dr = dtb.Rows[0];

                    hfContentID.Value = dr["ContentID"].ToString();
                    hfContentType.Value = dr["ContentType"].ToString();
                    hfParentID.Value = dr["ParentID"] != DBNull.Value ? dr["ParentID"].ToString() : "";

                    txtContentName.Text = dr["ContentName"].ToString();
                    txtContentSlug.Text = dr["ContentSlug"] != DBNull.Value ? dr["ContentSlug"].ToString() : "";
                    txtDescription.Text = dr["Description"] != DBNull.Value ? dr["Description"].ToString() : "";
                    ddlContentType.SelectedValue = dr["ContentType"].ToString();
                    ddlContentSubType.SelectedValue = dr["ContentSubType"] != DBNull.Value ? dr["ContentSubType"].ToString() : "";
                    txtSortOrder.Text = dr["SortOrder"] != DBNull.Value ? dr["SortOrder"].ToString() : "";
                    txtIcon.Text = dr["Icon"] != DBNull.Value ? dr["Icon"].ToString() : "";
                    txtColor.Text = dr["Color"] != DBNull.Value ? dr["Color"].ToString() : "";
                    txtThumbnail.Text = dr["Thumbnail"] != DBNull.Value ? dr["Thumbnail"].ToString() : "";
                    ddlStatus.SelectedValue = dr["Status"].ToString();
                    txtEstimatedMinutes.Text = dr["EstimatedMinutes"] != DBNull.Value ? dr["EstimatedMinutes"].ToString() : "";

                    chkIsPublished.Checked = dr["IsPublished"] != DBNull.Value && Convert.ToBoolean(dr["IsPublished"]);
                    chkIsFree.Checked = dr["IsFree"] != DBNull.Value && Convert.ToBoolean(dr["IsFree"]);
                    chkIsRequired.Checked = dr["IsRequired"] != DBNull.Value && Convert.ToBoolean(dr["IsRequired"]);
                    chkAllowPreview.Checked = dr["AllowPreview"] != DBNull.Value && Convert.ToBoolean(dr["AllowPreview"]);
                    chkLockPrevious.Checked = dr["LockPrevious"] != DBNull.Value && Convert.ToBoolean(dr["LockPrevious"]);

                    // Quiz/Assignment settings
                    if (ddlContentType.SelectedValue == "QUIZ" || ddlContentType.SelectedValue == "ASSIGNMENT")
                    {
                        pnlQuizSettings.Visible = true;
                        txtMaxScore.Text = dr["MaxScore"] != DBNull.Value ? dr["MaxScore"].ToString() : "";
                        txtPassingScore.Text = dr["PassingScore"] != DBNull.Value ? dr["PassingScore"].ToString() : "";
                        txtMaxAttempts.Text = dr["MaxAttempts"] != DBNull.Value ? dr["MaxAttempts"].ToString() : "";
                        txtTimeLimitMinutes.Text = dr["TimeLimitMinutes"] != DBNull.Value ? dr["TimeLimitMinutes"].ToString() : "";
                        chkShuffleQuestions.Checked = dr["ShuffleQuestions"] != DBNull.Value && Convert.ToBoolean(dr["ShuffleQuestions"]);
                        chkShowResultAfterSubmit.Checked = dr["ShowResultAfterSubmit"] != DBNull.Value && Convert.ToBoolean(dr["ShowResultAfterSubmit"]);
                    }
                    else
                    {
                        pnlQuizSettings.Visible = false;
                    }

                    pnlEmptyState.Visible = false;
                    pnlDetails.Visible = true;
                    btnSave.Visible = true;
                    btnCancel.Visible = true;
                    btnAddChild.Visible = true;
                    btnDelete.Visible = true;
                }
            }
            catch (Exception ex)
            {
                ShowStatus("Lỗi load chi tiết: " + ex.Message, false);
            }
        }

        /// <summary>
        /// Clear form
        /// </summary>
        private void ClearDetailsForm()
        {
            hfContentID.Value = "";
            hfContentType.Value = "";
            hfParentID.Value = "";

            txtContentName.Text = "";
            txtContentSlug.Text = "";
            txtDescription.Text = "";
            ddlContentType.SelectedIndex = 0;
            ddlContentSubType.SelectedIndex = 0;
