using System;
using System.Data;
using System.IO;
using System.Web.UI.WebControls;
using LmsService;
using LmsObject;

namespace InformationWeb.Pages.Cms
{
    /// <summary>
    /// DCore: 20/10/2026  For LMS
    /// Created by      : NgocTrong
    /// Created date    : 20/10/2026
    /// Description     : Content File Upload - Upload và quản lý file đính kèm
    /// </summary>
    public partial class ContentFileUpload : System.Web.UI.Page
    {
        private long _contentID;

        #region Page Events

        protected void Page_Load(object sender, EventArgs e)
        {
            if (!IsPostBack)
            {
                // Get ContentID from query string
                if (Request.QueryString["ContentID"] != null && long.TryParse(Request.QueryString["ContentID"], out _contentID))
                {
                    LoadFiles();
                }
                else
                {
                    ShowStatus("Thiếu tham số ContentID", false);
                }
            }
        }

        #endregion

        #region File Upload Operations

        protected void btnBrowseFiles_Click(object sender, EventArgs e)
        {
            try
            {
                if (fileUpload.HasFiles)
                {
                    foreach (HttpPostedFile file in fileUpload.PostedFiles)
                    {
                        UploadFile(file);
                    }

                    LoadFiles();
                    ShowStatus("Đã upload file thành công", true);
                }
            }
            catch (Exception ex)
            {
                ShowStatus("Lỗi upload file: " + ex.Message, false);
            }
        }

        /// <summary>
        /// Upload một file
        /// </summary>
        private void UploadFile(HttpPostedFile file)
        {
            try
            {
                // Validate file
                if (file.ContentLength == 0)
                {
                    throw new Exception("File rỗng");
                }

                if (file.ContentLength > 500 * 1024 * 1024) // 500MB limit
                {
                    throw new Exception("File quá lớn (tối đa 500MB)");
                }

                // Determine file type
                string fileType = DetermineFileType(file.FileName);
                string mimeType = GetMimeType(file.FileName);

                // Generate unique filename
                string fileExtension = Path.GetExtension(file.FileName);
                string uniqueFileName = Guid.NewGuid().ToString() + fileExtension;
                string originalFileName = Path.GetFileName(file.FileName);

                // TODO: Implement actual file storage (local or cloud)
                string filePath = "/uploads/content/" + DateTime.Now.ToString("yyyy/MM/dd") + "/" + uniqueFileName;

                // Create directory if not exists
                string physicalPath = Server.MapPath(filePath);
                string directory = Path.GetDirectoryName(physicalPath);
                if (!Directory.Exists(directory))
                {
                    Directory.CreateDirectory(directory);
                }

                // Save file
                file.SaveAs(physicalPath);

                // Get file metadata (duration, dimensions for video/image)
                int? duration = null;
                int? width = null;
                int? height = null;

                if (fileType == "VIDEO" || fileType == "IMAGE")
                {
                    // TODO: Use FFmpeg or other library to get metadata
                    // For now, set default values
                    if (fileType == "VIDEO")
                    {
                        duration = 0; // TODO: Get actual duration
                        width = 1920;
                        height = 1080;
                    }
                    else if (fileType == "IMAGE")
                    {
                        // TODO: Get image dimensions
                        width = 1920;
                        height = 1080;
                    }
                }

                // Check if this is the first file (set as primary)
                DataTable dtbExisting = LMS_ContentFilesService.GetFilesByContent(_contentID);
                bool isPrimary = (dtbExisting == null || dtbExisting.Rows.Count == 0);

                // Upload to database
                long fileID = LMS_ContentFilesService.UploadFile(
                    _contentID,
                    uniqueFileName,
                    originalFileName,
                    filePath,
                    file.ContentLength,
                    fileType,
                    mimeType,
                    isPrimary,
                    0, // SortOrder
                    duration,
                    width,
                    height,
                    GetCurrentUserID()
                );

                if (fileID == 0)
                {
                    throw new Exception("Lỗi lưu file vào database");
                }
            }
            catch (Exception ex)
            {
                throw new Exception("Lỗi upload file '" + file.FileName + "': " + ex.Message);
            }
        }

        /// <summary>
        /// Xác định loại file dựa trên extension
        /// </summary>
        private string DetermineFileType(string fileName)
        {
            string extension = Path.GetExtension(fileName).ToLower();

            switch (extension)
            {
                case ".pdf":
                    return "DOCUMENT";
                case ".mp4":
                case ".avi":
                case ".mov":
                case ".wmv":
                    return "VIDEO";
                case ".jpg":
                case ".jpeg":
                case ".png":
                case ".gif":
                case ".bmp":
                    return "IMAGE";
                case ".mp3":
                case ".wav":
                case ".ogg":
                    return "AUDIO";
                case ".zip":
                case ".rar":
                case ".7z":
                    return "ZIP";
                default:
                    return "DOCUMENT";
            }
        }

        /// <summary>
        /// Lấy MIME type dựa trên extension
        /// </summary>
        private string GetMimeType(string fileName)
        {
            string extension = Path.GetExtension(fileName).ToLower();

            switch (extension)
            {
                case ".pdf":
                    return "application/pdf";
                case ".mp4":
                    return "video/mp4";
                case ".avi":
                    return "video/x-msvideo";
                case ".mov":
                    return "video/quicktime";
                case ".wmv":
                    return "video/x-ms-wmv";
                case ".jpg":
                case ".jpeg":
                    return "image/jpeg";
                case ".png":
                    return "image/png";
                case ".gif":
                    return "image/gif";
                case ".bmp":
                    return "image/bmp";
                case ".mp3":
                    return "audio/mpeg";
                case ".wav":
                    return "audio/wav";
                case ".ogg":
                    return "audio/ogg";
                case ".zip":
                    return "application/zip";
                case ".rar":
                    return "application/x-rar-compressed";
                default:
                    return "application/octet-stream";
            }
        }

        #endregion

        #region File List Operations

        /// <summary>
        /// Load danh sách file
        /// </summary>
        private void LoadFiles()
        {
            try
            {
                DataTable dtbFiles = LMS_ContentFilesService.GetFilesByContent(_contentID);

                // Add custom columns for UI
                dtbFiles.Columns.Add("Status", typeof(string));
                dtbFiles.Columns.Add("UploadProgress", typeof(int));
                dtbFiles.Columns.Add("ErrorMessage", typeof(string));

                foreach (DataRow dr in dtbFiles.Rows)
                {
                    dr["Status"] = "COMPLETED";
                    dr["UploadProgress"] = 100;
                    dr["ErrorMessage"] = "";
                }

                rptFiles.DataSource = dtbFiles;
                rptFiles.DataBind();
            }
            catch (Exception ex)
            {
                ShowStatus("Lỗi load danh sách file: " + ex.Message, false);
            }
        }

