        /// <summary>
        /// Download file
        /// </summary>
        private void DownloadFile(long fileID)
        {
            try
            {
                LMS_ContentFiles obj = new LMS_ContentFiles();
                obj.IDB = DCore.Data.CreateData();
                obj.IDB.CreateNewStoredProcedure("LMS_ContentFiles_GetByID");
                obj.IDB.AddParameter("@FileID", fileID);
                DataTable dtb = obj.IDB.ExecStoreToDataTable();
                obj.IDB.Disconnect();

                if (dtb != null && dtb.Rows.Count > 0)
                {
                    DataRow dr = dtb.Rows[0];
                    string filePath = Server.MapPath(dr["FilePath"].ToString());
                    string originalName = dr["FileOriginalName"].ToString();

                    if (File.Exists(filePath))
                    {
                        Response.Clear();
                        Response.ContentType = dr["MimeType"].ToString();
                        Response.AddHeader("Content-Disposition", "attachment; filename=" + originalName);
                        Response.TransmitFile(filePath);
                        Response.End();
                    }
                    else
                    {
                        ShowStatus("File không tồn tại", false);
                    }
                }
            }
            catch (Exception ex)
            {
                ShowStatus("Lỗi download file: " + ex.Message, false);
            }
        }

