        /// <summary>
        /// Check if file is previewable
        /// </summary>
        protected bool IsPreviewable(object fileType)
        {
            string type = fileType.ToString().ToLower();
            return type == "image" || type == "video";
        }

        /// <summary>
        /// Format file size
        /// </summary>
        protected string FormatFileSize(object fileSize)
        {
            if (fileSize == DBNull.Value)
                return "0 B";

            long size = Convert.ToInt64(fileSize);
            string[] sizes = { "B", "KB", "MB", "GB" };
            int order = 0;
            double sizeNum = size;

            while (sizeNum >= 1024 && order < sizes.Length - 1)
            {
                order++;
                sizeNum /= 1024;
            }

            return string.Format("{0:0.##} {1}", sizeNum, sizes[order]);
        }

        /// <summary>
        /// Format date
        /// </summary>
        protected string FormatDate(object date)
        {
            if (date == DBNull.Value)
                return "";

            DateTime dt = Convert.ToDateTime(date);
            return dt.ToString("dd/MM/yyyy HH:mm");
        }

