                // Get progress record
                LMS_ContentProgress obj = new LMS_ContentProgress();
                obj.IDB = DCore.Data.CreateData();
                obj.IDB.CreateNewStoredProcedure("LMS_ContentProgress_GetByID");
                obj.IDB.AddParameter("@ProgressID", progressID);
                DataTable dtb = obj.IDB.ExecStoreToDataTable();
                obj.IDB.Disconnect();

                if (dtb != null && dtb.Rows.Count > 0)
                {
                    DataRow dr = dtb.Rows[0];

                    hfProgressID.Value = progressID.ToString();

                    lblDetailStudentName.Text = dr["StudentName"] != DBNull.Value ? dr["StudentName"].ToString() : "Học viên " + dr["UserID"];
                    lblDetailStudentID.Text = dr["UserID"].ToString();
                    lblDetailCourseName.Text = dr["CourseName"] != DBNull.Value ? dr["CourseName"].ToString() : "Khóa học " + dr["CourseID"];
                    lblDetailContentName.Text = dr["ContentName"] != DBNull.Value ? dr["ContentName"].ToString() : "Nội dung " + dr["ContentID"];
                    lblDetailContentType.Text = dr["ContentType"] != DBNull.Value ? dr["ContentType"].ToString() : "";
                    lblDetailStatus.Text = GetStatusText(dr["Status"]);
                    lblDetailProgress.Text = dr["ProgressPercent"] != DBNull.Value ? dr["ProgressPercent"].ToString() : "0";
                    lblDetailScore.Text = (dr["Score"] != DBNull.Value ? dr["Score"].ToString() : "0") + "/" + (dr["MaxScore"] != DBNull.Value ? dr["MaxScore"].ToString() : "0");
                    lblDetailTimeSpent.Text = FormatTimeSpent(dr["TimeSpentMinutes"]);
                    lblDetailAttempts.Text = dr["Attempts"] != DBNull.Value ? dr["Attempts"].ToString() : "0";
                    lblDetailStartedAt.Text = FormatDate(dr["StartedAt"]);
                    lblDetailCompletedAt.Text = FormatDate(dr["CompletedAt"]);

                    // Load timeline
                    LoadTimeline(progressID);

                    pnlDetailModal.Visible = true;
                }
            }
            catch (Exception ex)
            {
                ShowStatus("Lỗi load chi tiết: " + ex.Message, false);
            }
        }

        /// <summary>
        /// Load timeline hoạt động
        /// </summary>
        private void LoadTimeline(long progressID)
        {
            try
            {
                DataTable dtbTimeline = LMS_ContentProgressService.GetProgressTimeline(progressID);

                rptTimeline.DataSource = dtbTimeline;
                rptTimeline.DataBind();
            }
            catch (Exception ex)
            {
                ShowStatus("Lỗi load timeline: " + ex.Message, false);
            }
        }

