        /// <summary>
        /// Reset tiến độ
        /// </summary>
        private void ResetProgress(long progressID)
        {
            try
            {
                bool success = LMS_ContentProgressService.ResetProgress(progressID, GetCurrentUserID());

                if (success)
                {
                    LoadProgressData();
                    LoadMetrics();
                    ShowStatus("Đã reset tiến độ thành công", true);
                }
                else
                {
                    ShowStatus("Lỗi reset tiến độ", false);
                }
            }
            catch (Exception ex)
            {
                ShowStatus("Lỗi reset: " + ex.Message, false);
            }
        }

        protected void btnResetProgress_Click(object sender, EventArgs e)
        {
            long progressID = Convert.ToInt64(hfProgressID.Value);
            ResetProgress(progressID);
            pnlDetailModal.Visible = false;
        }

