        #region Helper Methods

        /// <summary>
        /// Get student initial for avatar
        /// </summary>
        protected string GetStudentInitial(object studentName)
        {
            if (studentName == DBNull.Value || string.IsNullOrEmpty(studentName.ToString()))
                return "U";

            string name = studentName.ToString();
            return name.Substring(0, 1).ToUpper();
        }

        /// <summary>
        /// Get status CSS class
        /// </summary>
        protected string GetStatusClass(object status)
        {
            string s = status.ToString();
            switch (s)
            {
                case "COMPLETED":
                    return "";
                case "IN_PROGRESS":
                    return "in-progress";
                case "NOT_STARTED":
                    return "not-started";
                case "OVERDUE":
                    return "overdue";
                default:
                    return "";
            }
        }

        /// <summary>
        /// Get status icon
        /// </summary>
        protected string GetStatusIcon(object status)
        {
            string s = status.ToString();
            switch (s)
            {
                case "COMPLETED":
                    return "fa-check-circle";
                case "IN_PROGRESS":
                    return "fa-spinner";
                case "NOT_STARTED":
                    return "fa-clock";
                case "OVERDUE":
                    return "fa-exclamation-circle";
                default:
                    return "fa-question-circle";
            }
        }

        /// <summary>
        /// Get status text
        /// </summary>
        protected string GetStatusText(object status)
        {
            string s = status.ToString();
            switch (s)
            {
                case "COMPLETED":
                    return "Hoàn thành";
                case "IN_PROGRESS":
                    return "Đang học";
                case "NOT_STARTED":
                    return "Chưa bắt đầu";
                case "OVERDUE":
                    return "Quá hạn";
                default:
                    return s;
            }
        }

        /// <summary>
        /// Get progress bar CSS class
        /// </summary>
        protected string GetProgressBarClass(object progressPercent)
        {
            if (progressPercent == DBNull.Value)
                return "";

            int percent = Convert.ToInt32(progressPercent);

            if (percent >= 80)
                return "";
            else if (percent >= 50)
                return "warning";
            else
                return "danger";
        }

        /// <summary>
        /// Get score CSS class
        /// </summary>
        protected string GetScoreClass(object score, object maxScore)
        {
            if (score == DBNull.Value || maxScore == DBNull.Value)
                return "";

            decimal s = Convert.ToDecimal(score);
            decimal m = Convert.ToDecimal(maxScore);

            if (m == 0)
                return "";

            decimal percent = (s / m) * 100;

            if (percent >= 50)
                return "passed";
            else
                return "failed";
        }

        /// <summary>
        /// Format time spent
        /// </summary>
        protected string FormatTimeSpent(object minutes)
        {
            if (minutes == DBNull.Value)
                return "0 phút";

            int mins = Convert.ToInt32(minutes);

            if (mins < 60)
                return mins + " phút";
            else
            {
                int hours = mins / 60;
                int remainingMins = mins % 60;
                return hours + "h " + remainingMins + "p";
            }
        }

        /// <summary>
        /// Format date
        /// </summary>
        protected string FormatDate(object date)
        {
            if (date == DBNull.Value)
                return "-";

            DateTime dt = Convert.ToDateTime(date);
            return dt.ToString("dd/MM/yyyy HH:mm");
        }

